/* ISLGrind — extra competitions beyond the IMO Shortlist.
   IMO, USAMO, USA TST, USA TSTST, EGMO, APMO, RMM.
   Sources: MathNet (MIT, huggingface.co/datasets/ShadenA/MathNet, CC-BY-4.0)
   and the AoPS Wiki (artofproblemsolving.com). Concatenated onto the ISL bank. */
window.ISL_BANK = (window.ISL_BANK || []).concat(
[{"id":"USAMO-2000-1","source":"USAMO","year":2000,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Call a real-valued function $f$ \\emph{very convex} if\n\n\\[ \\frac {f(x) + f(y)}{2} \\ge f\\left(\\frac {x + y}{2}\\right) + |x - y| \\]\n\nholds for all real numbers $x$ and $y$. Prove that no very convex function exists.","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_1"},{"id":"USAMO-2000-2","source":"USAMO","year":2000,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $S$ be the set of all triangles $ABC$ for which\n\n\\[ 5 \\left( \\dfrac{1}{AP} + \\dfrac{1}{BQ} + \\dfrac{1}{CR} \\right) - \\dfrac{3}{\\min\\{ AP, BQ, CR \\}} = \\dfrac{6}{r}, \\]\n\nwhere $r$ is the inradius and $P, Q, R$ are the points of tangency of the incircle with sides $AB, BC, CA,$ respectively. Prove that all triangles in $S$ are isosceles  and similar to one another.","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_2"},{"id":"USAMO-2000-3","source":"USAMO","year":2000,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A game of solitaire is played with $R$ red cards, $W$ white cards, and $B$ blue cards. A player plays all the cards one at a time. With each play he accumulates a penalty. If he plays a blue card, then he is charged a penalty which is the number of white cards still in his hand. If he plays a white card, then he is charged a penalty which is twice the number of red cards still in his hand. If he plays a red card, then he is charged a penalty which is three times the number of blue cards still in his hand. Find, as a function of $R, W,$ and $B,$ the minimal total penalty a player can amass and all the ways in which this minimum can be achieved.","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_3"},{"id":"USAMO-2000-4","source":"USAMO","year":2000,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Find the smallest positive integer $n$ such that if $n$ squares of a $1000 \\times 1000$ chessboard are colored, then there will exist three colored squares whose centers form a right triangle with sides parallel to the edges of the board.","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_4"},{"id":"USAMO-2000-5","source":"USAMO","year":2000,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $A_1A_2A_3$ be a triangle and let $\\omega_1$ be a circle in its plane passing through $A_1$ and $A_2.$ Suppose there exist circles $\\omega_2, \\omega_3, \\dots, \\omega_7$ such that for $k = 2, 3, \\dots, 7,$ $\\omega_k$ is externally tangent to $\\omega_{k - 1}$ and passes through $A_k$ and $A_{k + 1},$  where $A_{n + 3} = A_{n}$ for all $n \\ge 1$. Prove that $\\omega_7 = \\omega_1.$","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_5"},{"id":"USAMO-2000-6","source":"USAMO","year":2000,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $a_1, b_1, a_2, b_2, \\dots , a_n, b_n$ be nonnegative real numbers. Prove that\n\n\\[ \\sum_{i, j = 1}^{n} \\min\\{a_ia_j, b_ib_j\\} \\le \\sum_{i, j = 1}^{n} \\min\\{a_ib_j, a_jb_i\\}. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2000_USAMO_Problems/Problem_6"},{"id":"USAMO-2001-1","source":"USAMO","year":2001,"code":"C1","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Each of eight boxes contains six balls. Each ball has been colored with one of $n$ colors, such that no two balls in the same box are the same color, and no two colors occur together in more than one box. Determine, with justification, the smallest integer $n$ for which this is possible.","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_1"},{"id":"USAMO-2001-2","source":"USAMO","year":2001,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle and let $\\omega$ be its incircle. Denote by $D_1$ and $E_1$ the points where $\\omega$ is tangent to sides $BC$ and $AC$, respectively. Denote by $D_2$ and $E_2$ the points on sides $BC$ and $AC$, respectively, such that $CD_2 = BD_1$ and $CE_2 = AE_1$, and denote by $P$ the point of intersection of segments $AD_2$ and $BE_2$. Circle $\\omega$ intersects segment $AD_2$ at two points, the closer of which to the vertex $A$ is denoted by $Q$. Prove that $AQ = D_2P$.","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_2"},{"id":"USAMO-2001-3","source":"USAMO","year":2001,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $a, b, c \\geq 0$ and satisfy\n$a^2 + b^2 + c^2 + abc = 4.$\nShow that\n$0 \\le ab + bc + ca - abc \\leq 2.$","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_3"},{"id":"USAMO-2001-4","source":"USAMO","year":2001,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $P$ be a point in the plane of triangle $ABC$ such that the segments $PA$, $PB$, and $PC$ are the sides of an obtuse triangle. Assume that in this triangle the obtuse angle opposes the side congruent to $PA$. Prove that $\\angle BAC$ is acute.","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_4"},{"id":"USAMO-2001-5","source":"USAMO","year":2001,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $S$ be a set of integers (not necessarily positive) such that\n\n(a) there exist $a,b \\in S$ with $\\gcd(a,b) = \\gcd(a - 2,b - 2) = 1$;\n\n(b) if $x$ and $y$ are elements of $S$ (possibly equal), then $x^2 - y$ also belongs to $S$. \n\nProve that $S$ is the set of all integers.","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_5"},{"id":"USAMO-2001-6","source":"USAMO","year":2001,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Each point in the plane is assigned a real number such that, for any triangle, the number at the center of its inscribed circle is equal to the arithmetic mean of the three numbers at its vertices. Prove that all points in the plane are assigned the same number.","url":"https://artofproblemsolving.com/wiki/index.php/2001_USAMO_Problems/Problem_6"},{"id":"USAMO-2002-1","source":"USAMO","year":2002,"code":"C1","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $S$ be a set with 2002 elements, and let $N$ be an integer with $0 \\le N \\le 2^{2002}$.  Prove that it is possible to color every subset of $S$ either blue or red so that the following conditions hold:\n\n(a) the union of any two red subsets is red;\n\n(b) the union of any two blue subsets is blue;\n\n(c) there are exactly $N$ red subsets.","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_1"},{"id":"USAMO-2002-2","source":"USAMO","year":2002,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle such that\n\n$\\left( \\cot \\frac{A}{2} \\right)^2 + \\left( 2 \\cot \\frac{B}{2} \\right)^2 + \\left( 3 \\cot \\frac{C}{2} \\right)^2 = \\left( \\frac{6s}{7r} \\right)^2$,\n\nwhere $s$ and $r$ denote its semiperimeter and inradius, respectively.  Prove that triangle $ABC$ is similar to a triangle $T$ whose side lengths are all positive integers with no common divisor and determine those integers.","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_2"},{"id":"USAMO-2002-3","source":"USAMO","year":2002,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Prove that any monic polynomial (a polynomial with leading coefficient 1) of degree $n$ with real coefficients is the average of two monic polynomials of degree $n$ with $n$ real roots.","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_3"},{"id":"USAMO-2002-4","source":"USAMO","year":2002,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $\\mathbb{R}$ be the set of real numbers.  Determine all functions $f : \\mathbb{R} \\rightarrow \\mathbb{R}$ such that\n\n$f(x^2 - y^2) = xf(x) - yf(y)$\n\nfor all pairs of real numbers $x$ and $y$.","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_4"},{"id":"USAMO-2002-5","source":"USAMO","year":2002,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $a, b$ be integers greater than 2.  Prove that there exists a positive integer $k$ and a finite sequence $n_1, n_2, \\ldots, n_k$ of positive integers such that $n_1 = a$, $n_k = b$, and $n_in_{i+1}$ is divisible by $n_i + n_{i+1}$ for each $i$ ($1 \\le i \\le k$).","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_5"},{"id":"USAMO-2002-6","source":"USAMO","year":2002,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"I have an $n \\times n$ sheet of stamps, from which I've been asked to tear out blocks of three adjacent stamps in a single row or column. (I can only tear along the perforations separating adjacent stamps, and each block must come out of the sheet in one piece.) Let $b(n)$ be the smallest number of blocks I can tear out and make it impossible to tear out any more blocks. Prove that there are real constants $c$ and $d$ such that $\\dfrac{1}{7} n^2 - cn \\leq b(n) \\leq \\dfrac{1}{5} n^2 + dn$ for all $n > 0$.","url":"https://artofproblemsolving.com/wiki/index.php/2002_USAMO_Problems/Problem_6"},{"id":"USAMO-2003-1","source":"USAMO","year":2003,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Titu Andreescu})\nProve that for every positive integer $n$ there exists an $n$-digit number divisible by $5^n$ all of whose digits are odd.","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_1"},{"id":"USAMO-2003-2","source":"USAMO","year":2003,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"A convex polygon $\\mathcal{P}$ in the plane is dissected into smaller convex polygons by drawing all of its diagonals. The lengths of all sides and all diagonals of the polygon $\\mathcal{P}$ are rational numbers. Prove that the lengths of all sides of all polygons in the dissection are also rational numbers.","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_2"},{"id":"USAMO-2003-3","source":"USAMO","year":2003,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n \\neq 0$. For every sequence of integers\n\n$A = a_0,a_1,a_2,\\dots, a_n$\n\nsatisfying $0 \\le a_i \\le i$, for $i=0,\\dots,n$, define another sequence\n\n$t(A)= t(a_0), t(a_1), t(a_2), \\dots, t(a_n)$\n\nby setting $t(a_i)$ to be the number of  terms in the sequence $A$ that precede the term $a_i$ and are different from $a_i$. Show that, starting from any sequence $A$ as above, fewer than $n$ applications of the transformation $t$ lead to a sequence $B$ such that $t(B) = B$.","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_3"},{"id":"USAMO-2003-4","source":"USAMO","year":2003,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle. A circle passing through $A$ and $B$ intersects segments $AC$ and $BC$ at $D$ and $E$, respectively. Lines $AB$ and $DE$ intersect at $F$, while lines $BD$ and $CF$ intersect at $M$. Prove that $MF = MC$ if and only if $MB\\cdot MD = MC^2$.","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_4"},{"id":"USAMO-2003-5","source":"USAMO","year":2003,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $a$, $b$, $c$ be positive real numbers. Prove that\n$\\dfrac{(2a + b + c)^2}{2a^2 + (b + c)^2} + \\dfrac{(2b + c + a)^2}{2b^2 + (c + a)^2} + \\dfrac{(2c + a + b)^2}{2c^2 + (a + b)^2} \\le 8.$","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_5"},{"id":"USAMO-2003-6","source":"USAMO","year":2003,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"At the vertices of a regular hexagon are written six nonnegative integers whose sum is 2003. Bert is allowed to make moves of the following form: he may pick a vertex and replace the number written there by the absolute value of the difference between the numbers written at the two neighboring vertices. Prove that Bert can make a sequence of moves, after which the number 0 appears at all six vertices.","url":"https://artofproblemsolving.com/wiki/index.php/2003_USAMO_Problems/Problem_6"},{"id":"USAMO-2004-1","source":"USAMO","year":2004,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"(\\emph{Titu Andreescu}) Let $ABCD$ be a quadrilateral circumscribed about a circle, whose interior and exterior angles are at least 60 degrees. Prove that\n\n\\[ \\frac {1}{3}|AB^3 - AD^3| \\le |BC^3 - CD^3| \\le 3|AB^3 - AD^3|. \\]\n\nWhen does equality hold?","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_1"},{"id":"USAMO-2004-2","source":"USAMO","year":2004,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"(\\emph{Kiran Kedlaya}) Suppose $a_1, \\dots, a_n$ are integers whose greatest common divisor is 1. Let $S$ be a set of integers with the following properties:\n\n(a) For $i = 1, \\dots, n$, $a_i \\in S$.\n\n(b) For $i,j = 1, \\dots, n$ (not necessarily distinct), $a_i - a_j \\in S$.\n\n(c) For any integers $x,y \\in S$, if $x + y \\in S$, then $x - y \\in S$.\n\nProve that $S$ must be equal to the set of all integers.","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_2"},{"id":"USAMO-2004-3","source":"USAMO","year":2004,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"(\\emph{Ricky Liu}) For what values of $k > 0$ is it possible to dissect a $1 \\times k$ rectangle into two similar, but incongruent, polygons?","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_3"},{"id":"USAMO-2004-4","source":"USAMO","year":2004,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"(\\emph{Melanie Wood})\nAlice and Bob play a game on a 6 by 6 grid.  On his or her turn, a player chooses a rational number not yet appearing on the grid and writes it in an empty square of the grid.  Alice goes first and then the players alternate.  When all squares have numbers written in them, in each row, the square with the greatest number is colored black.  Alice wins if she can then draw a line from the top of the grid to the bottom of the grid that stays in black squares, and Bob wins if she can't.  (If two squares share a vertex, Alice can draw a line from on to the other that stays in those two squares.)  Find, with proof, a winning strategy for one of the players.","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_4"},{"id":"USAMO-2004-5","source":"USAMO","year":2004,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"(\\emph{Titu Andreescu})\nLet $a$, $b$, and $c$ be positive real numbers.  Prove that\n\n$(a^5 - a^2 + 3)(b^5 - b^2 + 3)(c^5 - c^2 + 3) \\ge (a+b+c)^3$.","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_5"},{"id":"USAMO-2004-6","source":"USAMO","year":2004,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"(\\emph{Zuming Feng}) A circle $\\omega$ is inscribed in a quadrilateral $ABCD$.  Let $I$ be the center of $\\omega$.  Suppose that\n\n$(AI + DI)^2 + (BI + CI)^2 = (AB + CD)^2$.\n\nProve that $ABCD$ is an isosceles trapezoid.","url":"https://artofproblemsolving.com/wiki/index.php/2004_USAMO_Problems/Problem_6"},{"id":"USAMO-2005-1","source":"USAMO","year":2005,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Zuming Feng}) Determine all composite positive integers $n$ for which it is possible to arrange all divisors of $n$ that are greater than 1 in a circle so that no two adjacent divisors are relatively prime.","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_1"},{"id":"USAMO-2005-2","source":"USAMO","year":2005,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"(\\emph{Răzvan Gelca}) Prove that the system\n\\[ \\begin{align*}x^6 + x^3 + x^3y + y &= 147^{157} \\\\\nx^3 + x^3y + y^2 + y + z^9 &= 157^{147}\\end{align*} \\]\nhas no solutions in integers $x$, $y$, and $z$.","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_2"},{"id":"USAMO-2005-3","source":"USAMO","year":2005,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"(\\emph{Zuming Feng}) Let $ABC$ be an acute-angled triangle, and let $P$ and $Q$ be two points on side $BC$. Construct point $C_1$ in such a way that convex quadrilateral $APBC_1$ is cyclic, $QC_1 \\parallel CA$, and $C_1$ and $Q$ lie on opposite sides of line $AB$. Construct point $B_1$ in such a way that convex quadrilateral $APCB_1$ is cyclic, $QB_1 \\parallel BA$, and $B_1$ and $Q$  lie on opposite sides of line $AC$.  Prove that points $B_1, C_1,P$, and $Q$ lie on a circle.","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_3"},{"id":"USAMO-2005-4","source":"USAMO","year":2005,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"(\\emph{Elgin Johnston}) Legs $L_1, L_2, L_3, L_4$ of a square table each have  length $n$, where $n$ is a positive integer.  For how many ordered  4-tuples $(k_1, k_2, k_3, k_4)$ of nonnegative integers can we cut  a piece of length $k_i$ from the end of leg $L_i \\; (i = 1,2,3,4)$ and still have a stable table?\n\n(The table is \\emph{stable} if it can be placed so that  all four of the leg ends touch the floor. Note that a cut leg of length 0 is permitted.)","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_4"},{"id":"USAMO-2005-5","source":"USAMO","year":2005,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"(\\emph{Kiran Kedlaya}) Let $n$ be an integer greater than 1. Suppose $2n$ points are given in the plane, no three of which are collinear. Suppose $n$ of the given $2n$ points are colored blue and the other $n$ colored red. A line in the plane is called a \\emph{balancing line} if it passes through one blue and one red point and, for each side of the line, the number of blue points on that side is equal to the number of red points on the same side.\n\nProve that there exist at least two balancing lines.","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_5"},{"id":"USAMO-2005-6","source":"USAMO","year":2005,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"(\\emph{Titu Andreescu, Gabriel Dospinescu}) For $m$ a positive integer, let $s(m)$ be the sum of the digits of $m$. For $n\\ge 2$, let $f(n)$ be the minimal $k$ for which there  exists a set $S$ of $n$ positive integers such that  $s\\left(\\sum_{x\\in X} x\\right) = k$ for any nonempty subset $X\\subset S$.  Prove that there are constants $0 < C_1 < C_2$ with\n\\[ C_1 \\log_{10} n \\le f(n) \\le C_2 \\log_{10} n. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2005_USAMO_Problems/Problem_6"},{"id":"USAMO-2006-1","source":"USAMO","year":2006,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Kiran Kedlaya}) Let $p$ be a prime number and let $s$ be an integer with $0 < s < p$. Prove that there exist integers $m$ and $n$ with $0 < m < n < p$ and\n\n$\\left\\{ \\frac{sm}{p} \\right\\} < \\left\\{ \\frac{sn}{p} \\right\\} < \\frac{s}{p}$\n\nif and only if $s$ is not a divisor of $p-1$.\n\nNote: For $x$ a real number, let $\\lfloor x \\rfloor$ denote the greatest integer less than or equal to $x$, and let $\\{x\\} = x - \\lfloor x \\rfloor$ denote the fractional part of $x$.","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_1"},{"id":"USAMO-2006-2","source":"USAMO","year":2006,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"(\\emph{Dick Gibbs}) For a given positive integer $k$ find, in terms of $k$, the minimum value of $N$ for which there is a set of $2k+1$ distinct positive integers that has sum greater than $N$ but every subset of size $k$ has sum at most $N/2$.","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_2"},{"id":"USAMO-2006-3","source":"USAMO","year":2006,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"(\\emph{Titu Andreescu, Gabriel Dospinescu}) For integral $m$, let $p(m)$ be the greatest prime divisor of $m$. By convention, we set $p(\\pm 1)=1$ and $p(0)=\\infty$. Find all polynomials $f$ with integer coefficients such that the sequence $\\{ p(f(n^2))-2n) \\}_{n \\in \\mathbb{Z} \\ge 0}$ is bounded above. (In particular, this requires $f(n^2)\\neq 0$ for $n\\ge 0$.)","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_3"},{"id":"USAMO-2006-4","source":"USAMO","year":2006,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Ricky Liu}) Find all positive integers $n$ such that there are $k\\ge 2$ positive rational numbers $a_1, a_2, \\ldots, a_k$ satisfying $a_1 + a_2 + \\cdots + a_k = a_1\\cdot a_2\\cdots a_k = n$.","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_4"},{"id":"USAMO-2006-5","source":"USAMO","year":2006,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"(\\emph{Zoran Sunik}) A mathematical frog jumps along the number line. The frog starts at 1, and jumps according to the following rule: if the frog is at integer $n$, then it can jump either to $n+1$ or to $n+2^{m_n+1}$ where $2^{m_n}$ is the largest power of 2 that is a factor of $n$. Show that if $k\\ge 2$ is a positive integer and $i$ is a nonnegative integer, then the minimum number of jumps needed to reach $2^i k$ is greater than the minimum number of jumps needed to reach $2^i$.","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_5"},{"id":"USAMO-2006-6","source":"USAMO","year":2006,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"(\\emph{Zuming Feng, Zhonghao Ye}) Let $ABCD$ be a quadrilateral, and let $E$ and $F$ be points on sides $AD$ and $BC$, respectively, such that $AE/ED = BF/FC$.  Ray $FE$ meets rays $BA$ and $CD$ at $S$ and $T$ respectively. Prove that the circumcircles of triangles $SAE$, $SBF$, $TCF$, and $TDE$ pass through a common point.","url":"https://artofproblemsolving.com/wiki/index.php/2006_USAMO_Problems/Problem_6"},{"id":"USAMO-2007-1","source":"USAMO","year":2007,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Sam Vandervelde}) Let $n$ be a positive integer.  Define a sequence by setting $a_1 = n$ and, for each $k>1$, letting $a_k$ be the unique integer in the range $0 \\le a_k \\le k-1$ for which $a_1 + a_2 + \\cdots + a_k$ is divisible by $k$.  For instance, when $n=9$ the obtained sequence is $9, 1, 2, 0, 3, 3, 3, \\ldots$.  Prove that for any $n$ the sequence $a_1, a_2, a_3, \\ldots$ eventually becomes constant.","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_1"},{"id":"USAMO-2007-2","source":"USAMO","year":2007,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"(\\emph{Gregory Galperin}) A square grid on the Euclidean plane consists of all points $(m,n)$, where $m$ and $n$ are integers.  Is it possible to cover all grid points by an infinite family of discs with non-overlapping interiors if each disc in the family has radius at least 5?","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_2"},{"id":"USAMO-2007-3","source":"USAMO","year":2007,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"(\\emph{András Gyárfás}) Let $S$ be a set containing $n^2+n-1$ elements, for some positive integer $n$.  Suppose that the $n$-element subsets of $S$ are partitioned into two classes.  Prove that there are at least $n$ pairwise disjoint sets in the same class.","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_3"},{"id":"USAMO-2007-4","source":"USAMO","year":2007,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"(\\emph{Reid Barton}) An \\emph{animal} with $n$ \\emph{cells} is a connected figure consisting of $n$ equal-sized square cells.${}^1$ The figure below shows an 8-cell animal.\n\n350px\n\nA \\emph{dinosaur} is an animal with at least 2007 cells.  It is said to be \\emph{primitive} if its cells cannot be partitioned into two or more dinosaurs.  Find with proof the maximum number of cells in a primitive dinosaur.\n\n${}^1$Animals are also called \\emph{polyominoes}.  They can be defined inductively.  Two cells are \\emph{adjacent} if they share a complete edge.  A single cell is an animal, and given an animal with $n$ cells, one with $n+1$ cells is obtained by adjoining a new cell by making it adjacent to one or more existing cells.","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_4"},{"id":"USAMO-2007-5","source":"USAMO","year":2007,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"(\\emph{Titu Andreescu}) Prove that for every nonnegative integer $n$, the number $7^{7^n}+1$ is the product of at least $2n+3$ (not necessarily distinct) primes.","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_5"},{"id":"USAMO-2007-6","source":"USAMO","year":2007,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"(\\emph{Kiran Kedlaya, Sungyoon Kim}) Let $ABC$ be an acute triangle with $\\omega$, $\\Omega$, and $R$ being its incircle, circumcircle, and circumradius, respectively.  The circle $\\omega_A$ is tangent internally to $\\Omega$ at $A$ and externally tangent to $\\omega$.  Circle $\\Omega_A$ is internally tangent to $\\Omega$ at $A$ and tangent internally to $\\omega$.  Let $P_A$ and $Q_A$ denote the centers of $\\omega_A$ and $\\Omega_A$, respectively.  Define points $P_B$, $Q_B$, $P_C$, $Q_C$ analogously.  Prove that\n\\[ 8P_AQ_A \\cdot P_BQ_B \\cdot P_CQ_C \\le R^3, \\]\nwith equality if and only if triangle $ABC$ is equilateral.","url":"https://artofproblemsolving.com/wiki/index.php/2007_USAMO_Problems/Problem_6"},{"id":"USAMO-2008-1","source":"USAMO","year":2008,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"(\\emph{Titu Andreescu}) Prove that for each positive integer $n$, there are pairwise relatively prime integers $k_0, k_1 \\dotsc, k_n$, all strictly greater than 1, such that $k_0 k_1 \\dotsm k_n -1$ is the product of two consecutive integers.","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_1"},{"id":"USAMO-2008-2","source":"USAMO","year":2008,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"(\\emph{Zuming Feng}) Let $ABC$ be an acute, scalene triangle, and let $M$, $N$, and $P$ be the midpoints of $\\overline{BC}$, $\\overline{CA}$, and $\\overline{AB}$, respectively. Let the perpendicular bisectors of $\\overline{AB}$ and $\\overline{AC}$ intersect ray $AM$ in points $D$ and $E$ respectively, and let lines $BD$ and $CE$ intersect in point $F$, inside of triangle $ABC$. Prove that points $A$, $N$, $F$, and $P$ all lie on one circle.","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_2"},{"id":"USAMO-2008-3","source":"USAMO","year":2008,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"(\\emph{Gabriel Carroll}) Let $n$ be a positive integer. Denote by $S_n$ the set of points $(x, y)$ with integer coordinates such that\n\\[ \\left|x\\right| + \\left|y + \\frac {1}{2}\\right| < n \\]\nA \\emph{path} is a sequence of distinct points $(x_1 , y_1 ), (x_2 , y_2 ), \\ldots , (x_\\ell, y_\\ell)$ in $S_n$ such that, for $i = 2, \\ldots , \\ell$, the distance between $(x_i , y_i )$ and $(x_{i - 1} , y_{i - 1} )$ is $1$ (in other words, the points $(x_i , y_i )$ and $(x_{i - 1} , y_{i - 1} )$ are neighbors in the lattice of points with integer coordinates). Prove that the points in $S_n$ cannot be partitioned into fewer than $n$ paths (a partition of $S_n$ into $m$ paths is a set $\\mathcal{P}$ of $m$ nonempty paths such that each point in $S_n$ appears in exactly one of the $m$ paths in $\\mathcal{P}$).","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_3"},{"id":"USAMO-2008-4","source":"USAMO","year":2008,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"(\\emph{Gregory Galparin}) Let $\\mathcal{P}$ be a convex polygon with $n$ sides, $n\\ge3$. Any set of $n - 3$ diagonals of $\\mathcal{P}$ that do not intersect in the interior of the polygon determine a \\emph{triangulation} of $\\mathcal{P}$ into $n - 2$ triangles. If $\\mathcal{P}$ is regular and there is a triangulation of $\\mathcal{P}$ consisting of only isosceles triangles, find all the possible values of $n$.","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_4"},{"id":"USAMO-2008-5","source":"USAMO","year":2008,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"(\\emph{Kiran Kedlaya}) Three nonnegative real numbers $r_1$, $r_2$, $r_3$ are written on a blackboard. These numbers have the property that there exist integers $a_1$, $a_2$, $a_3$, not all zero, satisfying $a_1r_1 + a_2r_2 + a_3r_3 = 0$. We are permitted to perform the following operation: find two numbers $x$, $y$ on the blackboard with $x \\le y$, then erase $y$ and write $y - x$ in its place. Prove that after a finite number of such operations, we can end up with at least one $0$ on the blackboard.","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_5"},{"id":"USAMO-2008-6","source":"USAMO","year":2008,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"(\\emph{Sam Vandervelde}) At a certain mathematical conference, every pair of mathematicians are either friends or strangers. At mealtime, every participant eats in one of two large dining rooms. Each mathematician insists upon eating in a room which contains an even number of his or her friends. Prove that the number of ways that the mathematicians may be split between the two rooms is a power of two (i.e., is of the form $2^k$ for some positive integer $k$).","url":"https://artofproblemsolving.com/wiki/index.php/2008_USAMO_Problems/Problem_6"},{"id":"USAMO-2009-1","source":"USAMO","year":2009,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Given circles $\\omega_1$ and $\\omega_2$ intersecting at points $X$ and $Y$, let $\\ell_1$ be a line through the center of $\\omega_1$ intersecting $\\omega_2$ at points $P$ and $Q$ and let $\\ell_2$ be a line through the center of $\\omega_2$ intersecting $\\omega_1$ at points $R$ and $S$.  Prove that if $P, Q, R$ and $S$ lie on a circle then the center of this circle lies on line $XY$.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_1"},{"id":"USAMO-2009-2","source":"USAMO","year":2009,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer.  Determine the size of the largest subset of $\\{ - n, - n + 1, \\ldots , n - 1, n\\}$ which does not contain three elements $a, b, c$ (not necessarily distinct) satisfying $a + b + c = 0$.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_2"},{"id":"USAMO-2009-3","source":"USAMO","year":2009,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"We define a \\emph{chessboard polygon} to be a polygon whose sides are situated along lines of the form $x = a$ or $y = b$, where $a$ and $b$ are integers. These lines divide the interior into unit squares, which are shaded alternately grey and white so that adjacent squares have different colors. To tile a chessboard polygon by dominoes is to exactly cover the polygon by non-overlapping $1 \\times 2$ rectangles. Finally, a \\emph{tasteful tiling} is one which avoids the two configurations of dominoes shown on the left below. Two tilings of a $3 \\times 4$ rectangle are shown; the first one is tasteful, while the second is not, due to the vertical dominoes in the upper right corner.\n\n a) Prove that if a chessboard polygon can be tiled by dominoes, then it can be done so tastefully.\n\nb) Prove that such a tasteful tiling is unique.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_3"},{"id":"USAMO-2009-4","source":"USAMO","year":2009,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"For $n \\ge 2$ let $a_1$, $a_2$, ..., $a_n$ be positive real numbers such that \n$(a_1+a_2+ ... +a_n)\\left( {1 \\over a_1} + {1 \\over a_2} + ... +{1 \\over a_n} \\right) \\le \\left(n+ {1 \\over 2} \\right) ^2$\nProve that $\\text{max}(a_1, a_2, ... ,a_n) \\le  4 \\text{min}(a_1, a_2, ... , a_n)$.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_4"},{"id":"USAMO-2009-5","source":"USAMO","year":2009,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Trapezoid $ABCD$, with $\\overline{AB}||\\overline{CD}$, is inscribed in circle $\\omega$ and point $G$ lies inside triangle $BCD$.  Rays $AG$ and $BG$ meet $\\omega$ again at points $P$ and $Q$, respectively.  Let the line through $G$ parallel to $\\overline{AB}$ intersect $\\overline{BD}$ and $\\overline{BC}$ at points $R$ and $S$, respectively.  Prove that quadrilateral $PQRS$ is cyclic if and only if $\\overline{BG}$ bisects $\\angle CBD$.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_5"},{"id":"USAMO-2009-6","source":"USAMO","year":2009,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $s_1, s_2, s_3, \\ldots$ be an infinite, nonconstant sequence of rational numbers, meaning it is not the case that $s_1 = s_2 = s_3 = \\cdots.$  Suppose that $t_1, t_2, t_3, \\ldots$ is also an infinite, nonconstant sequence of rational numbers with the property that $(s_i - s_j)(t_i - t_j)$ is an integer for all $i$ and $j$.  Prove that there exists a rational number $r$ such that $(s_i - s_j)r$ and $(t_i - t_j)/r$ are integers for all $i$ and $j$.","url":"https://artofproblemsolving.com/wiki/index.php/2009_USAMO_Problems/Problem_6"},{"id":"USAMO-2010-1","source":"USAMO","year":2010,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $AXYZB$ be a convex pentagon inscribed in a semicircle of diameter\n$AB$. Denote by $P, Q, R, S$ the feet of the perpendiculars from $Y$ onto\nlines $AX, BX, AZ, BZ$, respectively. Prove that the acute angle\nformed by lines $PQ$ and $RS$ is half the size of $\\angle XOZ$, where\n$O$ is the midpoint of segment $AB$.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_1"},{"id":"USAMO-2010-2","source":"USAMO","year":2010,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"There are $n$ students standing in a circle, one behind the\nother. The students have heights $h_1 < h_2 < \\ldots < h_n$. If a\nstudent with height $h_k$ is standing directly behind a student\nwith height $h_{k-2}$ or less, the two students are permitted to\nswitch places. Prove that it is not possible to make more than\n$\\binom{n}{3}$ such switches before reaching a position in which\nno further switches are possible.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_2"},{"id":"USAMO-2010-3","source":"USAMO","year":2010,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"The $2010$ positive numbers $a_1, a_2, \\ldots , a_{2010}$ satisfy\nthe inequality $a_ia_j \\le i+j$ for all distinct indices $i, j$.\nDetermine, with proof, the largest possible value of the product\n$a_1a_2\\cdots a_{2010}$.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_3"},{"id":"USAMO-2010-4","source":"USAMO","year":2010,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with $\\angle A = 90^{\\circ}$. Points $D$\nand $E$ lie on sides $AC$ and $AB$, respectively, such that $\\angle\nABD = \\angle DBC$ and $\\angle ACE = \\angle ECB$. Segments $BD$ and\n$CE$ meet at $I$.  Determine whether or not it is possible for\nsegments $AB, AC, BI, ID, CI, IE$ to all have integer lengths.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_4"},{"id":"USAMO-2010-5","source":"USAMO","year":2010,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $q = \\dfrac{3p-5}{2}$ where $p$ is an odd prime, and let\n\n\\[ S_q = \n  \\frac{1}{2\\cdot 3 \\cdot 4} +\n  \\frac{1}{5\\cdot 6 \\cdot 7} + \\cdots +\n  \\frac{1}{q\\cdot (q+1) \\cdot (q+2)}. \\]\n\nProve that if $\\dfrac{1}{p}-2S_q = \\dfrac{m}{n}$ for integers\n$m$ and $n$, then $m-n$ is divisible by $p$.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_5"},{"id":"USAMO-2010-6","source":"USAMO","year":2010,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A blackboard contains 68 pairs of nonzero integers.  Suppose that for each positive integer $k$ at most one of the pairs $(k, k)$ and $(-k, -k)$ is written on the blackboard.  A student erases some of the 136 integers, subject to the condition that no two erased integers may add to 0.  The student then scores one point for each of the 68 pairs in which at least one integer is erased.  Determine, with proof, the largest number $N$ of points that the student can guarantee to score regardless of which 68 pairs have been written on the board.","url":"https://artofproblemsolving.com/wiki/index.php/2010_USAMO_Problems/Problem_6"},{"id":"USAMO-2011-1","source":"USAMO","year":2011,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $a$, $b$, $c$ be positive real numbers such that $a^2 + b^2 + c^2 + (a + b + c)^2 \\le 4$.  Prove that\n\\[ \\frac{ab + 1}{(a + b)^2} + \\frac{bc + 1}{(b + c)^2} + \\frac{ca + 1}{(c + a)^2} \\ge 3. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_1"},{"id":"USAMO-2011-2","source":"USAMO","year":2011,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"An integer is assigned to each vertex of a regular pentagon so that the sum of the five integers is 2011. A turn of a solitaire game consists of subtracting an integer $m$ from each of the integers at two neighboring vertices and adding 2m to the opposite vertex, which is not adjacent to either of the first two vertices. (The amount $m$ and the vertices chosen can vary from turn to turn.) The game is won at a certain vertex if, after some number of turns, that vertex has the number 2011 and the other four vertices have the number 0. Prove that for any choice of the initial integers, there is exactly one vertex at which the game can be won.","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_2"},{"id":"USAMO-2011-3","source":"USAMO","year":2011,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"In hexagon $ABCDEF$, which is nonconvex but not self-intersecting, no pair of opposite sides are parallel. The internal angles satisfy $\\angle A = 3\\angle D$, $\\angle C = 3\\angle F$, and $\\angle E = 3\\angle B$. Furthermore $AB=DE$, $BC=EF$, and $CD=FA$. Prove that diagonals $\\overline{AD}$, $\\overline{BE}$, and $\\overline{CF}$ are concurrent.","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_3"},{"id":"USAMO-2011-4","source":"USAMO","year":2011,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Consider the assertion that for each positive integer $n \\ge 2$, the remainder upon dividing $2^{2^n}$ by $2^n-1$ is a power of 4. Either prove the assertion or find (with proof) a counter-example.","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_4"},{"id":"USAMO-2011-5","source":"USAMO","year":2011,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $P$ be a given point inside quadrilateral $ABCD$.  Points $Q_1$ and $Q_2$ are located within $ABCD$ such that $\\angle Q_1 BC = \\angle ABP$, $\\angle Q_1 CB = \\angle DCP$, $\\angle Q_2 AD = \\angle BAP$, $\\angle Q_2 DA = \\angle CDP$.  Prove that $\\overline{Q_1 Q_2} \\parallel \\overline{AB}$ if and only if $\\overline{Q_1 Q_2} \\parallel \\overline{CD}$.","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_5"},{"id":"USAMO-2011-6","source":"USAMO","year":2011,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $A$ be a set with $|A| = 225$, meaning that $A$ has 225 elements.  Suppose further that there are eleven subsets $A_1$, $\\dots$, $A_{11}$ of $A$ such that $|A_i | = 45$ for $1 \\le i \\le 11$ and $|A_i \\cap A_j| = 9$ for $1 \\le i < j \\le 11$.  Prove that $|A_1 \\cup A_2 \\cup \\dots \\cup A_{11}| \\ge 165$, and give an example for which equality holds.","url":"https://artofproblemsolving.com/wiki/index.php/2011_USAMO_Problems/Problem_6"},{"id":"USAMO-2012-1","source":"USAMO","year":2012,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Find all integers $n \\ge 3$ such that among any $n$ positive real numbers $a_1$, $a_2$, $\\dots$, $a_n$ with\n\\[ \\max(a_1, a_2, \\dots, a_n) \\le n \\cdot \\min(a_1, a_2, \\dots, a_n), \\]\nthere exist three that are the side lengths of an acute triangle.","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_1"},{"id":"USAMO-2012-2","source":"USAMO","year":2012,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"A circle is divided into 432 congruent arcs by 432 points.  The points are colored in four colors such that some 108 points are colored Red, some 108 points are colored Green, some 108 points are colored Blue, and the remaining 108 points are colored Yellow.  Prove that one can choose three points of each color in such a way that the four triangles formed by the chosen points of the same color are congruent.","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_2"},{"id":"USAMO-2012-3","source":"USAMO","year":2012,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Determine which integers $n > 1$ have the property that there exists an infinite sequence $a_1$, $a_2$, $a_3$, $\\dots$ of nonzero integers such that the equality\n\\[ a_k + 2a_{2k} + \\dots + na_{nk} = 0 \\]\nholds for every positive integer $k$.\n\n==Partial Solution==\nFor $n$ equal to any odd prime $p$, the sequence $\\left\\{a_i = \\left(\\frac{1-n}{2}\\right)^{m_p\\left(i\\right)}\\right\\}$, where $p^{m_p\\left(i\\right)}$ is the greatest power of $p$ that divides $i$, gives a valid sequence. Therefore, the set of possible values for $n$ is at least the set of odd primes.","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_3"},{"id":"USAMO-2012-4","source":"USAMO","year":2012,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Find all functions $f : \\mathbb{Z}^+ \\to \\mathbb{Z}^+$ (where $\\mathbb{Z}^+$ is the set of positive integers) such that $f(n!) = f(n)!$ for all positive integers $n$ and such that $m - n$ divides $f(m) - f(n)$ for all distinct positive integers $m$, $n$.","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_4"},{"id":"USAMO-2012-5","source":"USAMO","year":2012,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $P$ be a point in the plane of triangle $ABC$, and $\\gamma$ a line passing through $P$.  Let $A'$, $B'$, $C'$ be the points where the reflections of lines $PA$, $PB$, $PC$ with respect to $\\gamma$ intersect lines $BC$, $AC$, $AB$, respectively.  Prove that $A'$, $B'$, $C'$ are collinear.","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_5"},{"id":"USAMO-2012-6","source":"USAMO","year":2012,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"For integer $n \\ge 2$, let $x_1$, $x_2$, $\\dots$, $x_n$ be real numbers satisfying\n\\[ x_1 + x_2 + \\dots + x_n = 0, \\quad \\text{and} \\quad x_1^2 + x_2^2 + \\dots + x_n^2 = 1. \\]\nFor each subset $A \\subseteq \\{1, 2, \\dots, n\\}$, define\n\\[ S_A = \\sum_{i \\in A} x_i. \\]\n(If $A$ is the empty set, then $S_A = 0$.)\n\nProve that for any positive number $\\lambda$, the number of sets $A$ satisfying $S_A \\ge \\lambda$ is at most $2^{n - 3}/\\lambda^2$.  For what choices of $x_1$, $x_2$, $\\dots$, $x_n$, $\\lambda$ does equality hold?","url":"https://artofproblemsolving.com/wiki/index.php/2012_USAMO_Problems/Problem_6"},{"id":"USAMO-2013-1","source":"USAMO","year":2013,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"In triangle $ABC$, points $P,Q,R$ lie on sides $BC,CA,AB$ respectively.  Let $\\omega_A$, $\\omega_B$, $\\omega_C$ denote the circumcircles of triangles $AQR$, $BRP$, $CPQ$, respectively.  Given the fact that segment $AP$ intersects $\\omega_A$, $\\omega_B$, $\\omega_C$ again at $X,Y,Z$ respectively, prove that $YX/XZ=BP/PC$.","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_1"},{"id":"USAMO-2013-2","source":"USAMO","year":2013,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"For a positive integer $n\\geq 3$ plot $n$ equally spaced points around a circle.  Label one of them $A$, and place a marker at $A$.  One may move the marker forward in a clockwise direction to either the next point or the point after that.  Hence there are a total of $2n$ distinct moves available; two from each point.  Let $a_n$ count the number of ways to advance around the circle exactly twice, beginning and ending at $A$, without repeating a move.  Prove that $a_{n-1}+a_n=2^n$ for all $n\\geq 4$.","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_2"},{"id":"USAMO-2013-3","source":"USAMO","year":2013,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n$ be a positive integer.  There are $\\tfrac{n(n+1)}{2}$ marks, each with a black side and a white side, arranged into an equilateral triangle, with the biggest row containing $n$ marks.  Initially, each mark has the black side up.  An \\emph{operation} is to choose a line parallel to the sides of the triangle, and flipping all the marks on that line.  A configuration is called \\emph{admissible} if it can be obtained from the initial configuration by performing a finite number of operations.  For each admissible configuration $C$, let $f(C)$ denote the smallest number of operations required to obtain $C$ from the initial configuration.  Find the maximum value of $f(C)$, where $C$ varies over all admissible configurations.","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_3"},{"id":"USAMO-2013-4","source":"USAMO","year":2013,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Find all real numbers $x,y,z\\geq 1$ satisfying \\[ \\min(\\sqrt{x+xyz},\\sqrt{y+xyz},\\sqrt{z+xyz})=\\sqrt{x-1}+\\sqrt{y-1}+\\sqrt{z-1}. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_4"},{"id":"USAMO-2013-5","source":"USAMO","year":2013,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Given positive integers $m$ and $n$, prove that there is a positive integer $c$ such that the numbers $cm$ and $cn$ have the same number of occurrences of each non-zero digit when written in base ten.","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_5"},{"id":"USAMO-2013-6","source":"USAMO","year":2013,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle.  Find all points $P$ on segment $BC$ satisfying the following property:  If $X$ and $Y$ are the intersections of line $PA$ with the common external tangent lines of the circumcircles of triangles $PAB$ and $PAC$, then \\[ \\left(\\frac{PA}{XY}\\right)^2+\\frac{PB\\cdot PC}{AB\\cdot AC}=1. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2013_USAMO_Problems/Problem_6"},{"id":"USAMO-2014-1","source":"USAMO","year":2014,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $a,b,c,d$ be real numbers such that $b-d \\ge 5$ and all zeros $x_1, x_2, x_3,$ and $x_4$ of the polynomial $P(x)=x^4+ax^3+bx^2+cx+d$ are real. Find the smallest value the product $(x_1^2+1)(x_2^2+1)(x_3^2+1)(x_4^2+1)$ can take.","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_1"},{"id":"USAMO-2014-2","source":"USAMO","year":2014,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $\\mathbb{Z}$ be the set of integers. Find all functions $f : \\mathbb{Z} \\rightarrow \\mathbb{Z}$ such that \\[ xf(2f(y)-x)+y^2f(2x-f(y))=\\frac{f(x)^2}{x}+f(yf(y)) \\] for all $x, y \\in \\mathbb{Z}$ with $x \\neq 0$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_2"},{"id":"USAMO-2014-3","source":"USAMO","year":2014,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Prove that there exists an infinite set of points \\[ \\ldots,\\,\\,\\,\\,P_{-3},\\,\\,\\,\\,P_{-2},\\,\\,\\,\\,P_{-1},\\,\\,\\,\\,P_0,\\,\\,\\,\\,P_1,\\,\\,\\,\\,P_2,\\,\\,\\,\\,P_3,\\,\\,\\,\\,\\ldots \\] in the plane with the following property: For any three distinct integers $a,b,$ and $c$, points $P_a$, $P_b$, and $P_c$ are collinear if and only if $a+b+c=2014$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_3"},{"id":"USAMO-2014-4","source":"USAMO","year":2014,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $k$ be a positive integer. Two players $A$ and $B$ play a game on an infinite grid of regular hexagons. Initially all the grid cells are empty. Then the players alternately take turns with $A$ moving first. In his move, $A$ may choose two adjacent hexagons in the grid which are empty and place a counter in both of them. In his move, $B$ may choose any counter on the board and remove it. If at any time there are $k$ consecutive grid cells in a line all of which contain a counter, $A$ wins. Find the minimum value of $k$ for which $A$ cannot win in a finite number of moves, or prove that no such minimum value exists.","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_4"},{"id":"USAMO-2014-5","source":"USAMO","year":2014,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle with orthocenter $H$ and let $P$ be the second intersection of the circumcircle of triangle $AHC$ with the internal bisector of the angle $\\angle BAC$.  Let $X$ be the circumcenter of triangle $APB$ and $Y$ the orthocenter of triangle $APC$.  Prove that the length of segment $XY$ is equal to the circumradius of triangle $ABC$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_5"},{"id":"USAMO-2014-6","source":"USAMO","year":2014,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Prove that there is a constant $c>0$ with the following property: If $a, b, n$ are positive integers such that $\\gcd(a+i, b+j)>1$ for all $i, j\\in\\{0, 1, \\ldots n\\}$, then\\[ \\min\\{a, b\\}>c^n\\cdot n^{\\frac{n}{2}}. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2014_USAMO_Problems/Problem_6"},{"id":"USAMO-2015-1","source":"USAMO","year":2015,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Solve in integers the equation\n\\[ x^2+xy+y^2 = \\left(\\frac{x+y}{3}+1\\right)^3. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_1"},{"id":"USAMO-2015-2","source":"USAMO","year":2015,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Quadrilateral $APBQ$ is inscribed in circle $\\omega$ with $\\angle P = \\angle Q = 90^{\\circ}$ and $AP = AQ < BP$. Let $X$ be a variable point on segment $\\overline{PQ}$. Line $AX$ meets $\\omega$ again at $S$ (other than $A$). Point $T$ lies on arc $AQB$ of $\\omega$ such that $\\overline{XT}$ is perpendicular to $\\overline{AX}$. Let $M$ denote the midpoint of chord $\\overline{ST}$. As $X$ varies on segment $\\overline{PQ}$, show that $M$ moves along a circle.","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_2"},{"id":"USAMO-2015-3","source":"USAMO","year":2015,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $S = \\{1, 2, ..., n\\}$, where $n \\ge 1$. Each of the $2^n$ subsets of $S$ is to be colored red or blue. (The subset itself is assigned a color and not its individual elements.) For any set $T \\subseteq S$, we then write $f(T)$ for the number of subsets of T that are blue. \n\nDetermine the number of colorings that satisfy the following condition: for any subsets $T_1$ and $T_2$ of $S$, \\[ f(T_1)f(T_2) = f(T_1 \\cup T_2)f(T_1 \\cap T_2). \\]","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_3"},{"id":"USAMO-2015-4","source":"USAMO","year":2015,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Steve is piling $m\\geq 1$ indistinguishable stones on the squares of an $n\\times n$ grid. Each square can have an arbitrarily high pile of stones. After he finished piling his stones in some manner, he can then perform stone moves, defined as follows. Consider any four grid squares, which are corners of a rectangle, i.e. in positions $(i, k), (i, l), (j, k), (j, l)$ for some $1\\leq i, j, k, l\\leq n$, such that $i<j$ and $k<l$. A stone move consists of either removing one stone from each of $(i, k)$ and $(j, l)$ and moving them to $(i, l)$ and $(j, k)$ respectively,j or removing one stone from each of $(i, l)$ and $(j, k)$ and moving them to $(i, k)$ and $(j, l)$ respectively.\n\nTwo ways of piling the stones are equivalent if they can be obtained from one another by a sequence of stone moves.\n\nHow many different non-equivalent ways can Steve pile the stones on the grid?","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_4"},{"id":"USAMO-2015-5","source":"USAMO","year":2015,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $a, b, c, d, e$ be distinct positive integers such that $a^4 + b^4 = c^4 + d^4 = e^5$. Show that $ac + bd$ is a composite number.","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_5"},{"id":"USAMO-2015-6","source":"USAMO","year":2015,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Consider $0<\\lambda<1$, and let $A$ be a multiset of positive integers. Let $A_n=\\{a\\in A: a\\leq n\\}$. Assume that for every $n\\in\\mathbb{N}$, the set $A_n$ contains at most $n\\lambda$numbers. Show that there are infinitely many $n\\in\\mathbb{N}$ for which the sum of the elements in $A_n$ is at most $\\frac{n(n+1)}{2}\\lambda$. (A multiset is a set-like collection of elements in which order is ignored, but repetition of elements is allowed and multiplicity of elements is significant. For example, multisets $\\{1, 2, 3\\}$ and $\\{2, 1, 3\\}$ are equivalent, but $\\{1, 1, 2, 3\\}$ and $\\{1, 2, 3\\}$ differ.)","url":"https://artofproblemsolving.com/wiki/index.php/2015_USAMO_Problems/Problem_6"},{"id":"USAMO-2016-1","source":"USAMO","year":2016,"code":"C1","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $X_1, X_2, \\ldots, X_{100}$ be a sequence of mutually distinct nonempty subsets of a set $S$. Any two sets $X_i$ and $X_{i+1}$ are disjoint and their union is not the whole set $S$, that is, $X_i\\cap X_{i+1}=\\emptyset$ and $X_i\\cup X_{i+1}\\neq S$, for all $i\\in\\{1, \\ldots, 99\\}$. Find the smallest possible number of elements in $S$.","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_1"},{"id":"USAMO-2016-2","source":"USAMO","year":2016,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Prove that for any positive integer $k,$\n\\[ \\left(k^2\\right)!\\cdot\\prod_{j=0}^{k-1}\\frac{j!}{\\left(j+k\\right)!} \\]\nis an integer.","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_2"},{"id":"USAMO-2016-3","source":"USAMO","year":2016,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $\\triangle ABC$ be an acute triangle, and let $I_B, I_C,$ and $O$ denote its $B$-excenter, $C$-excenter, and circumcenter, respectively. Points $E$ and $Y$ are selected on $\\overline{AC}$ such that $\\angle ABY = \\angle CBY$ and $\\overline{BE}\\perp\\overline{AC}.$ Similarly, points $F$ and $Z$ are selected on $\\overline{AB}$ such that $\\angle ACZ = \\angle BCZ$ and $\\overline{CF}\\perp\\overline{AB}.$\n\nLines $I_B F$ and $I_C E$ meet at $P.$ Prove that $\\overline{PO}$ and $\\overline{YZ}$ are perpendicular.","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_3"},{"id":"USAMO-2016-4","source":"USAMO","year":2016,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Find all functions $f:\\mathbb{R}\\rightarrow \\mathbb{R}$ such that for all real numbers $x$ and $y$, \\[ (f(x)+xy)\\cdot f(x-3y)+(f(y)+xy)\\cdot f(3x-y)=(f(x+y))^2. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_4"},{"id":"USAMO-2016-5","source":"USAMO","year":2016,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"An equilateral pentagon $AMNPQ$ is inscribed in triangle $ABC$ such that $M\\in\\overline{AB},$ $Q\\in\\overline{AC},$ and $N, P\\in\\overline{BC}.$ Let $S$ be the intersection of lines $MN$ and $PQ.$ Denote by $\\ell$ the angle bisector of $\\angle MSQ.$\n\nProve that $\\overline{OI}$ is parallel to $\\ell,$ where $O$ is the circumcenter of triangle $ABC,$ and $I$ is the incenter of triangle $ABC.$","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_5"},{"id":"USAMO-2016-6","source":"USAMO","year":2016,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Integers $n$ and $k$ are given, with $n\\ge k\\ge 2.$ You play the following game against an evil wizard.\n\nThe wizard has $2n$ cards; for each $i = 1, ..., n,$ there are two cards labeled $i.$ Initially, the wizard places all cards face down in a row, in unknown order.\n\nYou may repeatedly make moves of the following form: you point to any $k$ of the cards. The wizard then turns those cards face up. If any two of the cards match, the game is over and you win. Otherwise, you must look away, while the wizard arbitrarily permutes the $k$ chosen cards and turns them back face-down. Then, it is your turn again.\n\nWe say this game is $\\textit{winnable}$ if there exist some positive integer $m$ and some strategy that is guaranteed to win in at most $m$ moves, no matter how the wizard responds.\n\nFor which values of $n$ and $k$ is the game winnable?","url":"https://artofproblemsolving.com/wiki/index.php/2016_USAMO_Problems/Problem_6"},{"id":"USAMO-2017-1","source":"USAMO","year":2017,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Prove that there are infinitely many distinct pairs $(a,b)$ of relatively prime positive integers $a>1$ and $b>1$ such that $a^b+b^a$ is divisible by $a+b$.","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_1"},{"id":"USAMO-2017-2","source":"USAMO","year":2017,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $m_1, m_2, \\ldots, m_n$ be a collection of $n$ positive integers, not necessarily distinct. For any sequence of integers $A = (a_1, \\ldots, a_n)$ and any permutation $w = w_1, \\ldots, w_n$ of $m_1, \\ldots, m_n$, define an $A$-inversion of $w$ to be a pair of entries $w_i, w_j$ with $i < j$ for which one of the following conditions holds:\n\n\\[ a_i \\ge w_i > w_j, \\]\n\\[ w_j > a_i \\ge w_i, \\]\nor\n\\[ w_i > w_j > a_i. \\]\nShow that, for any two sequences of integers $A = (a_1, \\ldots, a_n)$ and $B = (b_1, \\ldots, b_n)$, and for any positive integer $k$, the number of permutations of $m_1, \\ldots, m_n$ having exactly $k$ $A$-inversions is equal to the number of permutations of $m_1, \\ldots, m_n$ having exactly $k$ $B$-inversions.","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_2"},{"id":"USAMO-2017-3","source":"USAMO","year":2017,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with circumcircle $\\Omega$ and incenter $I.$ Ray $AI$ meets $BC$ at $D$ and $\\Omega$ again at $M;$ the circle with diameter $DM$ cuts $\\Omega$ again at $K.$ Lines $MK$ and $BC$ meet at $S,$ and $N$ is the midpoint of $IS.$ The circumcircles of $\\triangle KID$ and $\\triangle MAN$ intersect at points $L_1$ and $L.$ Prove that $\\Omega$ passes through the midpoint of either $IL_1$ or $IL.$","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_3"},{"id":"USAMO-2017-4","source":"USAMO","year":2017,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $P_1, \\ldots, P_{2n}$ be $2n$ distinct points on the unit circle $x^2 + y^2 = 1$ other than $(1,0)$. Each point is colored either red or blue, with exactly $n$ of them red and exactly $n$ of them blue. Let $R_1, \\ldots, R_n$ be any ordering of the red points. Let $B_1$ be the nearest blue point to $R_1$ traveling counterclockwise around the circle starting from $R_1$. Then let $B_2$ be the nearest of the remaining blue points to $R_2$ traveling counterclockwise around the circle from $R_2$, and so on, until we have labeled all the blue points $B_1, \\ldots, B_n$. Show that the number of counterclockwise arcs of the form $R_i \\rightarrow B_i$ that contain the point $(1,0)$ is independent of the way we chose the ordering $R_1, \\ldots, R_n$ of the red points.","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_4"},{"id":"USAMO-2017-5","source":"USAMO","year":2017,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $\\mathbf{Z}$ denote the set of all integers. Find all real numbers $c > 0$ such that there exists a labeling of the lattice points $( x, y ) \\in \\mathbf{Z}^2$ with positive integers for which: only finitely many distinct labels occur, and for each label $i$, the distance between any two points labeled $i$ is at least $c^i$.","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_5"},{"id":"USAMO-2017-6","source":"USAMO","year":2017,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find the minimum possible value of \n\n\\[ \\frac{a}{b^3+4}+\\frac{b}{c^3+4}+\\frac{c}{d^3+4}+\\frac{d}{a^3+4}, \\]\n\ngiven that $a,b,c,d,$ are nonnegative real numbers such that $a+b+c+d=4$.","url":"https://artofproblemsolving.com/wiki/index.php/2017_USAMO_Problems/Problem_6"},{"id":"USAMO-2018-1","source":"USAMO","year":2018,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $a,b,c$ be positive real numbers such that $a+b+c=4\\sqrt[3]{abc}$. Prove that \\[ 2(ab+bc+ca)+4\\min(a^2,b^2,c^2)\\ge a^2+b^2+c^2. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_1"},{"id":"USAMO-2018-2","source":"USAMO","year":2018,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all functions $f:(0,\\infty) \\to (0,\\infty)$ such that\n\n\\[ f\\left(x+\\frac{1}{y}\\right)+f\\left(y+\\frac{1}{z}\\right) + f\\left(z+\\frac{1}{x}\\right) = 1 \\] for all $x,y,z >0$ with $xyz =1.$","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_2"},{"id":"USAMO-2018-3","source":"USAMO","year":2018,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"For a given integer $n\\ge 2,$ let $\\{a_1,a_2,…,a_m\\}$ be the set of positive integers less than $n$ that are relatively prime to $n.$ Prove that if every prime that divides $m$ also divides $n,$ then $a_1^k+a_2^k + \\dots + a_m^k$ is divisible by $m$ for every positive integer $k.$","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_3"},{"id":"USAMO-2018-4","source":"USAMO","year":2018,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Let $p$ be a prime, and let $a_1, \\dots, a_p$ be integers. Show that there exists an integer $k$ such that the numbers \\[ a_1 + k, a_2 + 2k, \\dots, a_p + pk \\]produce at least $\\tfrac{1}{2} p$ distinct remainders upon division by $p$.","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_4"},{"id":"USAMO-2018-5","source":"USAMO","year":2018,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"In convex cyclic quadrilateral $ABCD,$ we know that lines $AC$ and $BD$ intersect at $E,$ lines $AB$ and $CD$ intersect at $F,$ and lines $BC$ and $DA$ intersect at $G.$ Suppose that the circumcircle of $\\triangle ABE$ intersects line $CB$ at $B$ and $P$, and the circumcircle of $\\triangle ADE$ intersects line $CD$ at $D$ and $Q$, where $C,B,P,G$ and $C,Q,D,F$ are collinear in that order. Prove that if lines $FP$ and $GQ$ intersect at $M$, then $\\angle MAC = 90^{\\circ}.$","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_5"},{"id":"USAMO-2018-6","source":"USAMO","year":2018,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $a_n$ be the number of permutations $(x_1, x_2, \\dots, x_n)$ of the numbers $(1,2,\\dots, n)$ such that the $n$ ratios $\\frac{x_k}{k}$ for $1\\le k\\le n$ are all distinct. Prove that $a_n$ is odd for all $n\\ge 1.$","url":"https://artofproblemsolving.com/wiki/index.php/2018_USAMO_Problems/Problem_6"},{"id":"USAMO-2019-1","source":"USAMO","year":2019,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $\\mathbb{N}$ be the set of positive integers. A function $f:\\mathbb{N}\\to\\mathbb{N}$ satisfies the equation \\[ \\underbrace{f(f(\\ldots f}_{f(n)\\text{ times}}(n)\\ldots))=\\frac{n^2}{f(f(n))} \\]for all positive integers $n$. Given this information, determine all possible values of $f(1000)$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_1"},{"id":"USAMO-2019-2","source":"USAMO","year":2019,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic quadrilateral satisfying $AD^2 + BC^2 = AB^2$. The diagonals of $ABCD$ intersect at $E$. Let $P$ be a point on side $\\overline{AB}$ satisfying $\\angle APD = \\angle BPC$. Show that line $PE$ bisects $\\overline{CD}$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_2"},{"id":"USAMO-2019-3","source":"USAMO","year":2019,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $K$ be the set of all positive integers that do not contain the digit $7$ in their base-$10$ representation. Find all polynomials $f$ with nonnegative integer coefficients such that $f(n)\\in K$ whenever $n\\in K$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_3"},{"id":"USAMO-2019-4","source":"USAMO","year":2019,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $n$ be a nonnegative integer. Determine the number of ways that one can choose $(n+1)^2$ sets $S_{i,j}\\subseteq\\{1,2,\\ldots,2n\\}$, for integers $i,j$ with $0\\leq i,j\\leq n$, such that:\n\n$\\bullet$ for all $0\\leq i,j\\leq n$, the set $S_{i,j}$ has $i+j$ elements; and\n\n$\\bullet$ $S_{i,j}\\subseteq S_{k,l}$ whenever $0\\leq i\\leq k\\leq n$ and $0\\leq j\\leq l\\leq n$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_4"},{"id":"USAMO-2019-5","source":"USAMO","year":2019,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Two rational numbers $\\frac{m}{n}$ and $\\frac{n}{m}$ are written on a blackboard, where $m$ and $n$ are relatively prime positive integers. At any point, Evan may pick two of the numbers $x$ and $y$ written on the board and write either their arithmetic mean $\\frac{x+y}{2}$ or their harmonic mean $\\frac{2xy}{x+y}$ on the board as well. Find all pairs $(m,n)$ such that Evan can write $1$ on the board in finitely many steps.\n\nProposed by Yannick Yao","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_5"},{"id":"USAMO-2019-6","source":"USAMO","year":2019,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all polynomials $P$ with real coefficients such that \\[ \\frac{P(x)}{yz}+\\frac{P(y)}{zx}+\\frac{P(z)}{xy}=P(x-y)+P(y-z)+P(z-x) \\]holds for all nonzero real numbers $x,y,z$ satisfying $2xyz=x+y+z$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_USAMO_Problems/Problem_6"},{"id":"USAMO-2020-1","source":"USAMO","year":2020,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a fixed acute triangle inscribed in a circle $\\omega$ with center $O$. A variable point $X$ is chosen on minor arc $AB$ of $\\omega$, and segments $CX$ and $AB$ meet at $D$. Denote by $O_1$ and $O_2$ the circumcenters of triangles $ADX$ and $BDX$, respectively. Determine all points $X$ for which the area of triangle $OO_1O_2$ is minimized.","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_1"},{"id":"USAMO-2020-2","source":"USAMO","year":2020,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"An empty $2020 \\times 2020 \\times 2020$ cube is given, and a $2020 \\times 2020$ grid of square unit cells is drawn on each of its six faces. A beam is a $1 \\times 1 \\times 2020$ rectangular prism. Several beams are placed inside the cube subject to the following conditions:\n\n*The two $1 \\times 1$ faces of each beam coincide with unit cells lying on opposite faces of the cube. (Hence, there are $3 \\cdot 2020^2$ possible positions for a beam.)\n*No two beams have intersecting interiors.\n*The interiors of each of the four $1 \\times 2020$ faces of each beam touch either a face of the cube or the interior of the face of another beam.\n\nWhat is the smallest positive number of beams that can be placed to satisfy these conditions?","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_2"},{"id":"USAMO-2020-3","source":"USAMO","year":2020,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $p$ be an odd prime. An integer $x$ is called a \\emph{quadratic non-residue} if $p$ does not divide $x - t^2$ for any integer $t$.\n\nDenote by $A$ the set of all integers $a$ such that $1 \\le a < p$, and both $a$ and $4 - a$ are quadratic non-residues. Calculate the remainder when the product of the elements of $A$ is divided by $p$.","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_3"},{"id":"USAMO-2020-4","source":"USAMO","year":2020,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Suppose that $(a_1, b_1), (a_2, b_2), \\ldots , (a_{100}, b_{100})$ are distinct ordered pairs of nonnegative integers. Let $N$ denote the number of pairs of integers $(i, j)$ satisfying $1 \\le i < j \\le 100$ and $|a_ib_j - a_j b_i|=1$. Determine the largest possible value of $N$ over all possible choices of the $100$ ordered pairs.","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_4"},{"id":"USAMO-2020-5","source":"USAMO","year":2020,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"A finite set $S$ of points in the coordinate plane is called \\emph{overdetermined} if $|S| \\ge 2$ and there exists a nonzero polynomial $P(t)$, with real coefficients and of degree at most $|S| - 2$, satisfying $P(x) = y$ for every point $(x, y) \\in S$.\n\nFor each integer $n \\ge 2$, find the largest integer $k$ (in terms of $n$) such that there exists a set of $n$ distinct points that is not overdetermined, but has $k$ overdetermined subsets.","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_5"},{"id":"USAMO-2020-6","source":"USAMO","year":2020,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $n \\ge 2$ be an integer. Let $x_1 \\ge x_2 \\ge \\cdots \\ge x_n$ and $y_1 \\ge y_2 \\ge \\cdots \\ge y_n$ be $2n$ real numbers such that\n\\[ \\begin{align*}\n0 &= x_1 + x_2 + \\cdots + x_n = y_1 + y_2 + \\cdots + y_n\\\\\n\\text{and  }1 &= x_1^2+x_2^2+\\cdots+x_n^2=y_1^2+y_2^2+\\cdots+y_n^2.\n\\end{align*} \\]\nProve that\n\\[ \\sum_{i=1}^n(x_iy_i-x_iy_{n+1-i})\\ge\\frac{2}{\\sqrt{n-1}}. \\]\n\nSolution","url":"https://artofproblemsolving.com/wiki/index.php/2020_USAMO_Problems/Problem_6"},{"id":"USAMO-2021-1","source":"USAMO","year":2021,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Rectangles $BCC_{1}B_{2}$, $CAA_{1}C_{2}$, and $ABB_{1}A_{2}$ are erected outside an acute triangle $ABC$. Suppose that \\[ \\angle BC_{1}C + \\angle CA_{1}A + \\angle AB_{1}B = 180^{\\circ}. \\] Prove that lines $B_{1}C_{2}$, $C_{1}A_{2}$, and $A_{1}B_{2}$ are concurrent.","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_1"},{"id":"USAMO-2021-2","source":"USAMO","year":2021,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"The Planar National Park is an undirected 3-regular planar graph (i.e. all vertices have degree 3). That is: every trail has its two endpoints at two different junctions whereas each junction is the endpoint of exactly three trails. Trails only intersect at junctions (in particular, trails only meet at endpoints). Finally, no trails begin and end at the same two junctions. (An example of one possible layout of the park is shown to the left below, in which there are six junctions and nine trails.)\n\n<img src = \"https://services.artofproblemsolving.com/download.php?id=YXR0YWNobWVudHMvZS9mLzc1YmNjN2YxMWZhZTNhMTVkZTQ4NWE1ZDIyMDNhN2I5NzY0NTBlLnBuZw==&rn=Z3JhcGguUE5H\" alt = \"Diagram\"/>\n\nA visitor walks through the park as follows: she begins at a vertex and starts walking along an edge. When she reaches the other endpoint, she turns left. On the next vertex, she turns right, and so on, alternating left and right turns at each vertex. She does this until she gets back to the vertex where she started. What is the largest possible number of times she could have entered any vertex during her walk, over all possible layouts of the park?","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_2"},{"id":"USAMO-2021-3","source":"USAMO","year":2021,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n \\geq 2$ be an integer. An $n \\times n$ board is initially empty. Each minute, you may perform one of three moves:\n*If there is an L-shaped tromino region of three cells without stones on the board (see figure; rotations not allowed), you may place a stone in each of those cells.\n*If all cells in a column have a stone, you may remove all stones from that column.\n*If all cells in a row have a stone, you may remove all stones from that row.\n\nFor which $n$ is it possible that, after some non-zero number of moves, the board has no stones?","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_3"},{"id":"USAMO-2021-4","source":"USAMO","year":2021,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"A finite set $S$ of positive integers has the property that, for each $s\\in S$, and each positive integer divisor $d$ of $s$, there exists a unique element $t \\in S$ satisfying $\\gcd(s,t)=d$ (the elements $s$ and $t$ could be equal).\n\nGiven this information, find all possible values for the number of elements of $S$.","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_4"},{"id":"USAMO-2021-5","source":"USAMO","year":2021,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $n \\geq 4$ be an integer. Find all positive real solutions to the following system of $2n$ equations:\n\n\\[ \\begin{align*}\na_{1} &=\\frac{1}{a_{2 n}}+\\frac{1}{a_{2}}, & a_{2}&=a_{1}+a_{3}, \\\\\na_{3}&=\\frac{1}{a_{2}}+\\frac{1}{a_{4}}, & a_{4}&=a_{3}+a_{5}, \\\\\na_{5}&=\\frac{1}{a_{4}}+\\frac{1}{a_{6}}, & a_{6}&=a_{5}+a_{7} \\\\\n&\\vdots & &\\vdots \\\\\na_{2 n-1}&=\\frac{1}{a_{2 n-2}}+\\frac{1}{a_{2 n}}, & a_{2 n}&=a_{2 n-1}+a_{1}\n\\end{align*} \\]\n\nSolution","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_5"},{"id":"USAMO-2021-6","source":"USAMO","year":2021,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABCDEF$ be a convex hexagon satisfying $\\overline{AB} \\parallel \\overline{DE}$, $\\overline{BC} \\parallel \\overline{EF}$, $\\overline{CD} \\parallel \\overline{FA}$, and\\[ AB \\cdot DE = BC \\cdot EF = CD \\cdot FA. \\]Let $X$, $Y$, and $Z$ be the midpoints of $\\overline{AD}$, $\\overline{BE}$, and $\\overline{CF}$. Prove that the circumcenter of $\\triangle ACE$, the circumcenter of $\\triangle BDF$, and the orthocenter of $\\triangle XYZ$ are collinear.","url":"https://artofproblemsolving.com/wiki/index.php/2021_USAMO_Problems/Problem_6"},{"id":"USAMO-2022-1","source":"USAMO","year":2022,"code":"C1","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $a$ and $b$ be positive integers. The cells of an $(a+b+1)\\times (a+b+1)$ grid are colored amber and bronze such that there are at least $a^2+ab-b$ amber cells and at least $b^2+ab-a$ bronze cells. Prove that it is possible to choose $a$ amber cells and $b$ bronze cells such that no two of the $a+b$ chosen cells lie in the same row or column.","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_1"},{"id":"USAMO-2022-2","source":"USAMO","year":2022,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $b\\geq2$ and $w\\geq2$ be fixed integers, and $n=b+w$. Given are $2b$ identical black rods and $2w$ identical white rods, each of side length $1$.\n\nWe assemble a regular $2n$-gon using these rods so that parallel sides are the same color. Then, a convex $2b$-gon $B$ is formed by translating the black rods, and a convex $2w$-gon $W$ is formed by translating the white rods. An example of one way of doing the assembly when $b=3$ and $w=2$ is shown below, as well as the resulting polygons $B$ and $W$.\n\nProve that the difference of the areas of $B$ and $W$ depends only on the numbers $b$ and $w$, and not on how the $2n$-gon was assembled.","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_2"},{"id":"USAMO-2022-3","source":"USAMO","year":2022,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $\\mathbb{R}_{>0}$ be the set of all positive real numbers. Find all functions $f:\\mathbb{R}_{>0} \\to \\mathbb{R}_{>0}$ such that for all $x,y\\in \\mathbb{R}_{>0}$ we have\\[ f(x) = f(f(f(x)) + y) + f(xf(y)) f(x+y). \\]","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_3"},{"id":"USAMO-2022-4","source":"USAMO","year":2022,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Find all pairs of primes $(p, q)$ for which $p-q$ and $pq-q$ are both perfect squares.","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_4"},{"id":"USAMO-2022-5","source":"USAMO","year":2022,"code":"A5","subject":"Algebra","level":6,"country":"","format":"latex","body":"A function $f: \\mathbb{R}\\to \\mathbb{R}$ is $\\textit{essentially increasing}$ if $f(s)\\leq f(t)$ holds whenever $s\\leq t$ are real numbers such that $f(s)\\neq 0$ and $f(t)\\neq 0$.\n\nFind the smallest integer $k$ such that for any 2022 real numbers $x_1,x_2,\\ldots , x_{2022},$ there exist $k$ essentially increasing functions $f_1,\\ldots, f_k$ such that\\[ f_1(n) + f_2(n) + \\cdots + f_k(n) = x_n\\qquad \\text{for every } n= 1,2,\\ldots 2022. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_5"},{"id":"USAMO-2022-6","source":"USAMO","year":2022,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"There are $2022$ users on a social network called Mathbook, and some of them are Mathbook-friends. (On Mathbook, friendship is always mutual and permanent.)\n\nStarting now, Mathbook will only allow a new friendship to be formed between two users if they have at least two friends in common. What is the minimum number of friendships that must already exist so that every user could eventually become friends with every other user?","url":"https://artofproblemsolving.com/wiki/index.php/2022_USAMO_Problems/Problem_6"},{"id":"USAMO-2023-1","source":"USAMO","year":2023,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"In an acute triangle $ABC$, let $M$ be the midpoint of $\\overline{BC}$. Let $P$ be the foot of the perpendicular from $C$ to $AM$. Suppose that the circumcircle of triangle $ABP$ intersects line $BC$ at two distinct points $B$ and $Q$. Let $N$ be the midpoint of $\\overline{AQ}$. Prove that $NB=NC$.","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_1"},{"id":"USAMO-2023-2","source":"USAMO","year":2023,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $\\mathbb{R}^{+}$ be the set of positive real numbers. Find all functions $f:\\mathbb{R}^{+}\\rightarrow\\mathbb{R}^{+}$ such that, for all $x, y \\in \\mathbb{R}^{+}$,\\[ f(xy + f(x)) = xf(y) + 2 \\]","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_2"},{"id":"USAMO-2023-3","source":"USAMO","year":2023,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Consider an $n$-by-$n$ board of unit squares for some odd positive integer $n$. We say that a collection $C$ of identical dominoes is a maximal grid-aligned configuration on the board if $C$ consists of $(n^2-1)/2$ dominoes where each domino covers exactly two neighboring squares and the dominoes don't overlap: $C$ then covers all but one square on the board. We are allowed to slide (but not rotate) a domino on the board to cover the uncovered square, resulting in a new maximal grid-aligned configuration with another square uncovered. Let $k(C)$ be the number of distinct maximal grid-aligned configurations obtainable from $C$ by repeatedly sliding dominoes. Find all possible values of $k(C)$ as a function of $n$.","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_3"},{"id":"USAMO-2023-4","source":"USAMO","year":2023,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"A positive integer $a$ is selected, and some positive integers are written on a board. Alice and Bob play the following game. On Alice's turn, she must replace some integer $n$ on the board with $n+a$, and on Bob's turn he must replace some even integer $n$ on the board with $n/2$. Alice goes first and they alternate turns. If on his turn Bob has no valid moves, the game ends.\n\nAfter analyzing the integers on the board, Bob realizes that, regardless of what moves Alice makes, he will be able to force the game to end eventually. Show that, in fact, for this value of $a$ and these integers on the board, the game is guaranteed to end regardless of Alice's or Bob's moves.","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_4"},{"id":"USAMO-2023-5","source":"USAMO","year":2023,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n\\geq3$ be an integer. We say that an arrangement of the numbers $1$, $2$, $\\dots$, $n^2$ in a $n \\times n$ table is row-valid if the numbers in each row can be permuted to form an arithmetic progression, and column-valid if the numbers in each column can be permuted to form an arithmetic progression. For what values of $n$ is it possible to transform any row-valid arrangement into a column-valid arrangement by permuting the numbers in each row?","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_5"},{"id":"USAMO-2023-6","source":"USAMO","year":2023,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let ABC be a triangle with incenter $I$ and excenters $I_a$, $I_b$, $I_c$ opposite $A$, $B$, and $C$, respectively. Given an arbitrary point $D$ on the circumcircle of $\\triangle ABC$ that does not lie on any of the lines $II_{a}$, $I_{b}I_{c}$, or $BC$, suppose the circumcircles of $\\triangle DIIa$ and $\\triangle DI_bI_c$ intersect at two distinct points $D$ and $F$. If $E$ is the intersection of lines $DF$ and $BC$, prove that $\\angle BAD = \\angle EAC$.","url":"https://artofproblemsolving.com/wiki/index.php/2023_USAMO_Problems/Problem_6"},{"id":"USAMO-2024-1","source":"USAMO","year":2024,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Find all integers $n \\geq 3$ such that the following property holds: if we list the divisors of $n !$ in increasing order as $1=d_1<d_2<\\cdots<d_k=n!$, then we have\n\\[ d_2-d_1 \\leq d_3-d_2 \\leq \\cdots \\leq d_k-d_{k-1} . \\]","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_1"},{"id":"USAMO-2024-2","source":"USAMO","year":2024,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $S_1, S_2, \\ldots, S_{100}$ be finite sets of integers whose intersection is not empty. For each non-empty $T \\subseteq\\left\\{S_1, S_2, \\ldots, S_{100}\\right\\}$, the size of the intersection of the sets in $T$ is a multiple of the number of sets in $T$. What is the least possible number of elements that are in at least 50 sets?","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_2"},{"id":"USAMO-2024-3","source":"USAMO","year":2024,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $m$ be a positive integer. A triangulation of a polygon is $m$-balanced if its triangles can be colored with $m$ colors in such a way that the sum of the areas of all triangles of the same color is the same for each of the $m$ colors. Find all positive integers $n$ for which there exists an $m$-balanced triangulation of a regular $n$-gon.\nNote: A triangulation of a convex polygon $\\mathcal{P}$ with $n \\geq 3$ sides is any partitioning of $\\mathcal{P}$ into $n-2$ triangles by $n-3$ diagonals of $\\mathcal{P}$ that do not intersect in the polygon's interior.","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_3"},{"id":"USAMO-2024-4","source":"USAMO","year":2024,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $m$ and $n$ be positive integers. A circular necklace contains $m n$ beads, each either red or blue. It turned out that no matter how the necklace was cut into $m$ blocks of $n$ consecutive beads, each block had a distinct number of red beads. Determine, with proof, all possible values of the ordered pair $(m, n)$.","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_4"},{"id":"USAMO-2024-5","source":"USAMO","year":2024,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Point $D$ is selected inside acute triangle $ABC$ so that $\\angle DAC=\\angle ACB$ and $\\angle BDC=90^\\circ+\\angle BAC$. Point $E$ is chosen on ray $BD$ so that $AE=EC$. Let $M$ be the midpoint of $BC$. Show that line $AB$ is tangent to the circumcircle of triangle $BEM$.","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_5"},{"id":"USAMO-2024-6","source":"USAMO","year":2024,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"\\emph{Continued}\n\nLet $n>2$ be an integer and let $\\ell \\in\\{1,2, \\ldots, n\\}$. A collection $A_1, \\ldots, A_k$ of (not necessarily distinct) subsets of $\\{1,2, \\ldots, n\\}$ is called $\\ell$-large if $\\left|A_i\\right| \\geq \\ell$ for all $1 \\leq i \\leq k$. Find, in terms of $n$ and $\\ell$, the largest real number $c$ such that the inequality\n\\[ \\sum_{i=1}^k \\sum_{j=1}^k x_i x_j \\frac{\\left|A_i \\cap A_j\\right|^2}{\\left|A_i\\right| \\cdot\\left|A_j\\right|} \\geq c\\left(\\sum_{i=1}^k x_i\\right)^2 \\]\nholds for all positive integers $k$, all nonnegative real numbers $x_1, \\ldots, x_k$, and all $\\ell$-large collections $A_1, \\ldots, A_k$ of subsets of $\\{1,2, \\ldots, n\\}$.\nNote: For a finite set $S,|S|$ denotes the number of elements in $S$.","url":"https://artofproblemsolving.com/wiki/index.php/2024_USAMO_Problems/Problem_6"},{"id":"USAMO-2025-1","source":"USAMO","year":2025,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Let $k$ and $d$ be positive integers. Prove that there exists a positive integer $N$ such that for every odd integer $n>N$,  the digits in the base-$2n$ representation of $n^k$ are all greater than $d$.","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_1"},{"id":"USAMO-2025-2","source":"USAMO","year":2025,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $n$ and $k$ be positive integers with $k<n$. Let $P(x)$ be a polynomial of degree $n$ with real coefficients, nonzero constant term, and no repeated roots. Suppose that for any real numbers $a_0, a_1, \\dots, a_k$ such that the polynomial $a_kx^k+\\cdots+a_1x+a_0$ divides $P(x)$, the product $a_0a_1\\cdots a_k$ is zero. Prove that $P(x)$ has a nonreal root.","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_2"},{"id":"USAMO-2025-3","source":"USAMO","year":2025,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Alice the architect and Bob the builder play a game. First, Alice chooses two points $P$ and $Q$ in the plane and a subset $\\mathcal{S}$ of the plane, which are announced to Bob. Next, Bob marks infinitely many points in the plane, designating each a city. He may not place two cities within distance at most one unit of each other, and no three cities he places may be collinear. Finally, roads are constructed between the cities as follows: for each pair $A,\\,B$ of cities, they are connected with a road along the line segment $AB$ if and only if the following condition holds: For every city $C$ distinct from $A$ and $B$, there exists $R\\in\\mathcal{S}$ such that $\\triangle PQR$ is directly similar to either $\\triangle ABC$ or $\\triangle BAC$. Alice wins the game if (i) the resulting roads allow for travel between any pair of cities via a finite sequence of roads and (ii) no two roads cross. Otherwise, Bob wins. Determine, with proof, which player has a winning strategy.\n\nNote: $\\triangle UVW$ is directly similar to $\\triangle XYZ$ if there exists a sequence of rotations, translations, and dilations sending $U$ to $X$, $V$ to $Y$, and $W$ to $Z$.","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_3"},{"id":"USAMO-2025-4","source":"USAMO","year":2025,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $H$ be the orthocenter of acute triangle $ABC$, let $F$ be the foot of the altitude from $C$ to $AB$, and let $P$ be the reflection of $H$ across $BC$. Suppose that the circumcircle of triangle $FAP$ intersects line $BC$ at two distinct points $X$ and $Y$. Prove that $C$ is the midpoint of $XY$.","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_4"},{"id":"USAMO-2025-5","source":"USAMO","year":2025,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Determine, with proof, all positive integers $k$ such that\\[ \\frac{1}{n+1} \\sum_{i=0}^n \\binom{n}{i}^k \\]is an integer for every positive integer $n.$","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_5"},{"id":"USAMO-2025-6","source":"USAMO","year":2025,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $m$ and $n$ be positive integers with $m\\geq n$. There are $m$ cupcakes of different flavors arranged around a circle and $n$ people who like cupcakes. Each person assigns a nonnegative real number score to each cupcake, depending on how much they like the cupcake. Suppose that for each person $P$, it is possible to partition the circle of $m$ cupcakes into $n$ groups of consecutive cupcakes so that the sum of $P$'s scores of the cupcakes in each group is at least $1$. Prove that it is possible to distribute the $m$ cupcakes to the $n$ people so that each person $P$ receives cupcakes of total score at least $1$ with respect to $P$.","url":"https://artofproblemsolving.com/wiki/index.php/2025_USAMO_Problems/Problem_6"},{"id":"EGMO-2012-1","source":"EGMO","year":2012,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with circumcentre $O$. The points $D,E,F$ lie in the interiors of the sides $BC,CA,AB$ respectively, such that $DE$ is perpendicular to $CO$ and $DF$ is perpendicular to $BO$. (By interior we mean, for example, that the point $D$ lies on the line $BC$ and $D$ is between $B$ and $C$ on that line.)\nLet $K$ be the circumcentre of triangle $AFE$. Prove that the lines $DK$ and $BC$ are perpendicular.","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2012-2","source":"EGMO","year":2012,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. Find the greatest possible integer $m$, in terms of $n$, with the following property: a table with $m$ rows and $n$ columns can be filled with real numbers in such a manner that for any two different rows $\\left[ {{a_1},{a_2},\\ldots,{a_n}}\\right]$ and $\\left[ {{b_1},{b_2},\\ldots,{b_n}} \\right]$ the following holds:\\[ \\max\\left( {\\left| {{a_1} - {b_1}} \\right|,\\left| {{a_2} - {b_2}} \\right|,...,\\left| {{a_n} - {b_n}} \\right|} \\right) = 1 \\]","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2012-3","source":"EGMO","year":2012,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all functions $f:\\mathbb{R}\\to\\mathbb{R}$ such that\\[ f\\left( {yf(x + y) + f(x)} \\right) = 4x + 2yf(x + y) \\]for all $x,y\\in\\mathbb{R}$.","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2012-4","source":"EGMO","year":2012,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"A set $A$ of integers is called sum-full if $A \\subseteq A + A$, i.e. each element $a \\in A$ is the sum of some pair of (not necessarily different) elements $b,c \\in A$. A set $A$ of integers is said to be zero-sum-free if $0$ is the only integer that cannot be expressed as the sum of the elements of a finite nonempty subset of $A$.\nDoes there exist a sum-full zero-sum-free set of integers?","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2012-5","source":"EGMO","year":2012,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"The numbers $p$ and $q$ are prime and satisfy\n\\[ \\frac{p}{{p + 1}} + \\frac{{q + 1}}{q} = \\frac{{2n}}{{n + 2}} \\]\nfor some positive integer $n$. Find all possible values of $q-p$.","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2012-6","source":"EGMO","year":2012,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"There are infinitely many people registered on the social network Mugbook. Some pairs of (different) users are registered as friends, but each person has only finitely many friends. Every user has at least one friend. (Friendship is symmetric; that is, if $A$ is a friend of $B$, then $B$ is a friend of $A$.)\nEach person is required to designate one of their friends as their best friend. If $A$ designates $B$ as her best friend, then (unfortunately) it does not follow that $B$ necessarily designates $A$ as her best friend. Someone designated as a best friend is called a $1$-best friend. More generally, if $n> 1$ is a positive integer, then a user is an $n$-best friend provided that they have been designated the best friend of someone who is an $(n-1)$-best friend. Someone who is a $k$-best friend for every positive integer $k$ is called popular.\n\n(a) Prove that every popular person is the best friend of a popular person.\n\n(b) Show that if people can have infinitely many friends, then it is possible that a popular person is not the best friend of a popular person.","url":"https://artofproblemsolving.com/wiki/index.php/2012_EGMO_Problems"},{"id":"EGMO-2013-1","source":"EGMO","year":2013,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"The side $BC$ of the triangle $ABC$ is extended beyond $C$ to $D$ so that $CD = BC$. The side $CA$ is extended beyond $A$ to $E$ so that $AE = 2CA$. Prove that, if $AD=BE$, then the triangle $ABC$ is right-angled.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2013-2","source":"EGMO","year":2013,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Determine all integers $m$ for which the $m \\times m$ square can be dissected into five rectangles, the side lengths of which are the integers $1,2,3,\\ldots,10$ in some order.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2013-3","source":"EGMO","year":2013,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $n$ be a positive integer.\n\n(a) Prove that there exists a set $S$ of $6n$ pairwise different positive integers, such that the least common multiple of any two elements of $S$ is no larger than $32n^2$.\n\n(b) Prove that every set $T$ of $6n$ pairwise different positive integers contains two elements the least common multiple of which is larger than $9n^2$.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2013-4","source":"EGMO","year":2013,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Find all positive integers $a$ and $b$ for which there are three consecutive integers at which the polynomial\\[ P(n) = \\frac{n^5+a}{b} \\]takes integer values.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2013-5","source":"EGMO","year":2013,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $\\Omega$ be the circumcircle of the triangle $ABC$. The circle $\\omega$ is tangent to the sides $AC$ and $BC$, and it is internally tangent to the circle $\\Omega$ at the point $P$. A line parallel to $AB$ intersecting the interior of triangle $ABC$ is tangent to $\\omega$ at $Q$.\n\nProve that $\\angle ACP = \\angle QCB$.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2013-6","source":"EGMO","year":2013,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Snow White and the Seven Dwarves are living in their house in the forest. On each of $16$ consecutive days, some of the dwarves worked in the diamond mine while the remaining dwarves collected berries in the forest. No dwarf performed both types of work on the same day. On any two different (not necessarily consecutive) days, at least three dwarves each performed both types of work. Further, on the first day, all seven dwarves worked in the diamond mine.\n\nProve that, on one of these $16$ days, all seven dwarves were collecting berries.","url":"https://artofproblemsolving.com/wiki/index.php/2013_EGMO_Problems"},{"id":"EGMO-2014-1","source":"EGMO","year":2014,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Determine all real constants $t$ such that whenever $a$, $b$ and $c$ are the lengths of sides of a triangle, then so are $a^2+bct$, $b^2+cat$, $c^2+abt$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2014-2","source":"EGMO","year":2014,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $D$ and $E$ be points in the interiors of sides $AB$ and $AC$, respectively, of a triangle $ABC$, such that $DB = BC = CE$. Let the lines $CD$ and $BE$ meet at $F$. Prove that the incentre $I$ of triangle $ABC$, the orthocentre $H$ of triangle $DEF$ and the midpoint $M$ of the arc $BAC$ of the circumcircle of triangle $ABC$ are collinear.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2014-3","source":"EGMO","year":2014,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"We denote the number of positive divisors of a positive integer $m$ by $d(m)$ and the number of distinct prime divisors of $m$ by $\\omega(m)$. Let $k$ be a positive integer. Prove that there exist infinitely many positive integers $n$ such that $\\omega(n) = k$ and $d(n)$ does not divide $d(a^2+b^2)$ for any positive integers $a, b$ satisfying $a + b = n$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2014-4","source":"EGMO","year":2014,"code":"N4","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Determine all positive integers $n\\geq 2$ for which there exist integers $x_1,x_2,\\ldots ,x_{n-1}$ satisfying the condition that if $0<i<n,0<j<n, i\\neq j$ and $n$ divides $2i+j$, then $x_i<x_j$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2014-5","source":"EGMO","year":2014,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. We have $n$ boxes where each box contains a non-negative number of pebbles. In each move we are allowed to take two pebbles from a box we choose, throw away one of the pebbles and put the other pebble in another box we choose. An initial configuration of pebbles is called solvable if it is possible to reach a configuration with no empty box, in a finite (possibly zero) number of moves. Determine all initial configurations of pebbles which are not solvable, but become solvable when an additional pebble is added to a box, no matter which box is chosen.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2014-6","source":"EGMO","year":2014,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Determine all functions $f:\\mathbb R\\rightarrow\\mathbb R$ satisfying the condition\n\\[ f(y^2+2xf(y)+f(x)^2)=(y+f(x))(x+f(y)) \\]\nfor all real numbers $x$ and $y$.","url":"https://artofproblemsolving.com/wiki/index.php/2014_EGMO_Problems"},{"id":"EGMO-2015-1","source":"EGMO","year":2015,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $\\triangle ABC$ be an acute-angled triangle, and let $D$ be the foot of the altitude from $C.$ The angle bisector of $\\angle ABC$ intersects $CD$ at $E$ and meets the circumcircle $\\omega$ of triangle $\\triangle ADE$ again at $F.$\nIf $\\angle ADF = 45^{\\circ}$, show that $CF$ is tangent to $\\omega .$","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2015-2","source":"EGMO","year":2015,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"A domino is a $2 \\times 1$ or $1 \\times  2$ tile. Determine in how many ways exactly $n^2$ dominoes can be placed without overlapping on a $2n \\times  2n$ chessboard so that every $2 \\times  2$ square contains at least two uncovered unit squares which lie in the same row or column.","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2015-3","source":"EGMO","year":2015,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $n, m$ be integers greater than $1$, and let $a_1, a_2, \\dots, a_m$ be positive integers not greater than $n^m$. Prove that there exist positive integers $b_1, b_2, \\dots, b_m$ not greater than $n$, such that\\[ \\gcd(a_1 + b_1, a_2 + b_2, \\dots, a_m + b_m) < n, \\]where $\\gcd(x_1, x_2, \\dots, x_m)$ denotes the greatest common divisor of $x_1, x_2, \\dots, x_m$.","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2015-4","source":"EGMO","year":2015,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Determine whether there exists an infinite sequence $a_1, a_2, a_3, \\dots$ of positive integers\nwhich satisfies the equality\\[ a_{n+2}=a_{n+1}+\\sqrt{a_{n+1}+a_{n}} \\]for every positive integer $n$.","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2015-5","source":"EGMO","year":2015,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $m, n$ be positive integers with $m > 1$. Anastasia partitions the integers $1, 2, \\dots , 2m$ into $m$ pairs. Boris then chooses one integer from each pair and finds the sum of these chosen integers.\nProve that Anastasia can select the pairs so that Boris cannot make his sum equal to $n$.","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2015-6","source":"EGMO","year":2015,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $H$ be the orthocentre and $G$ be the centroid of acute-angled triangle $ABC$ with $AB\\ne AC$. The line $AG$ intersects the circumcircle of $ABC$ at $A$ and $P$. Let $P'$ be the reflection of $P$ in the line $BC$. Prove that $\\angle CAB = 60$ if and only if $HG = GP'$","url":"https://artofproblemsolving.com/wiki/index.php/2015_EGMO_Problems"},{"id":"EGMO-2016-1","source":"EGMO","year":2016,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $n$ be an odd positive integer, and let $x_1,x_2,\\cdots ,x_n$ be non-negative real numbers. Show that\\[ \\min_{i=1,\\ldots,n} (x_i^2+x_{i+1}^2) \\leq \\max_{j=1,\\ldots,n} (2x_jx_{j+1}) \\]where $x_{n+1}=x_1$.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2016-2","source":"EGMO","year":2016,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic quadrilateral, and let diagonals $AC$ and $BD$ intersect at $X$.Let $C_1,D_1$ and $M$ be the midpoints of segments $CX,DX$ and $CD$, respecctively. Lines $AD_1$ and $BC_1$ intersect at $Y$, and line $MY$ intersects diagonals $AC$ and $BD$ at different points $E$ and $F$, respectively. Prove that line $XY$ is tangent to the circle through $E,F$ and $X$.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2016-3","source":"EGMO","year":2016,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $m$ be a positive integer. Consider a $4m\\times 4m$ array of square unit cells. Two different cells are related to each other if they are in either the same row or in the same column.No cell is related to itself.Some cells are coloured blue, such that every cell is related to at lest two blue cells.Determine the minimum number of blue cells.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2016-4","source":"EGMO","year":2016,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Two circles $\\omega_1$ and $\\omega_2$, of equal radius intersect at different points $X_1$ and $X_2$. Consider a circle $\\omega$ externally tangent to $\\omega_1$ at $T_1$ and internally tangent to $\\omega_2$ at point $T_2$. Prove that lines $X_1T_1$ and $X_2T_2$ intersect at a point lying on $\\omega$.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2016-5","source":"EGMO","year":2016,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $k$ and $n$ be integers such that $k\\ge 2$ and $k \\le n \\le 2k-1$. Place rectangular tiles, each of size $1 \\times k$, or $k \\times 1$ on a $n \\times n$ chessboard so that each tile covers exactly $k$ cells and no two tiles overlap. Do this until no further tile can be placed in this way. For each such $k$ and $n$, determine the minimum number of tiles that such an arrangement may contain.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2016-6","source":"EGMO","year":2016,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $S$ be the set of all positive integers $n$ such that $n^4$ has a divisor in the range $n^2 +1, n^2 + 2,...,n^2 + 2n$. Prove that there are infinitely many elements of $S$ of each of the forms $7m, 7m+1, 7m+2, 7m+5, 7m+6$ and no elements of $S$ of the form $7m+3$ and $7m+4$, where $m$ is an integer.","url":"https://artofproblemsolving.com/wiki/index.php/2016_EGMO_Problems"},{"id":"EGMO-2017-1","source":"EGMO","year":2017,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABCD$ be a convex quadrilateral with $\\angle DAB=\\angle BCD=90^{\\circ}$ and $\\angle ABC> \\angle CDA$. Let $Q$ and $R$ be points on segments $BC$ and $CD$, respectively, such that line $QR$ intersects lines $AB$ and $AD$ at points $P$ and $S$, respectively. It is given that $PQ=RS$.Let the midpoint of $BD$ be $M$ and the midpoint of $QR$ be $N$.Prove that the points $M,N,A$ and $C$ lie on a circle.","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2017-2","source":"EGMO","year":2017,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Find the smallest positive integer $k$ for which there exists a colouring of the positive integers $\\mathbb{Z}_{>0}$ with $k$ colours and a function $f:\\mathbb{Z}_{>0}\\to \\mathbb{Z}_{>0}$ with the following two properties:\n\n(i) For all positive integers $m,n$ of the same colour, $f(m+n)=f(m)+f(n).$\n\n(ii) There are positive integers $m,n$ such that $f(m+n)\\ne f(m)+f(n).$\n\nIn a colouring of $\\mathbb{Z}_{>0}$ with $k$ colours, every integer is coloured in exactly one of the $k$ colours. In both (i) and (ii) the positive integers $m,n$ are not necessarily distinct.","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2017-3","source":"EGMO","year":2017,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"There are $2017$ lines in the plane such that no three of them go through the same point. Turbo the snail sits on a point on exactly one of the lines and starts sliding along the lines in the following fashion: she moves on a given line until she reaches an intersection of two lines. At the intersection, she follows her journey on the other line turning left or right, alternating her choice at each intersection point she reaches. She can only change direction at an intersection point. Can there exist a line segment through which she passes in both directions during her journey?","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2017-4","source":"EGMO","year":2017,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $n\\geq1$ be an integer and let $t_1<t_2<\\dots<t_n$ be positive integers. In a group of $t_n+1$ people, some games of chess are played. Two people can play each other at most once. Prove that it is possible for the following two conditions to hold at the same time:\n\n(i) The number of games played by each person is one of $t_1,t_2,\\dots,t_n$.\n\n(ii) For every $i$ with $1\\leq i\\leq n$, there is someone who has played exactly $t_i$ games of chess.","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2017-5","source":"EGMO","year":2017,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $n\\geq2$ be an integer. An $n$-tuple $(a_1,a_2,\\dots,a_n)$ of not necessarily different positive integers is expensive if there exists a positive integer $k$ such that\\[ (a_1+a_2)(a_2+a_3)\\dots(a_{n-1}+a_n)(a_n+a_1)=2^{2k-1}. \\]\n(a) Find all integers $n\\geq2$ for which there exists an expensive $n$-tuple.\n\n(b) Prove that for every odd positive integer $m$ there exists an integer $n\\geq2$ such that $m$ belongs to an expensive $n$-tuple.\n\nThere are exactly $n$ factors in the product on the left hand side.","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2017-6","source":"EGMO","year":2017,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute-angled triangle in which no two sides have the same length. The reflections of the centroid $G$ and the circumcentre $O$ of $ABC$ in its sides $BC,CA,AB$ are denoted by $G_1,G_2,G_3$ and $O_1,O_2,O_3$, respectively. Show that the circumcircles of triangles $G_1G_2C$, $G_1G_3B$, $G_2G_3A$, $O_1O_2C$, $O_1O_3B$, $O_2O_3A$ and $ABC$ have a common point.\n\nThe centroid of a triangle is the intersection point of the three medians. A median is a line connecting a vertex of the triangle to the midpoint of the opposite side.","url":"https://artofproblemsolving.com/wiki/index.php/2017_EGMO_Problems"},{"id":"EGMO-2018-1","source":"EGMO","year":2018,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with $CA=CB$ and $\\angle{ACB}=120^\\circ$, and let $M$ be the midpoint of $AB$. Let $P$ be a variable point of the circumcircle of $ABC$, and let $Q$ be the point on the segment $CP$ such that $QP = 2QC$. It is given that the line through $P$ and perpendicular to $AB$ intersects the line $MQ$ at a unique point $N$.\nProve that there exists a fixed circle such that $N$ lies on this circle for all possible positions of $P$.","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2018-2","source":"EGMO","year":2018,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Consider the set\n\\[ A = \\left\\{1+\\frac{1}{k} : k=1,2,3,4,\\cdots \\right\\}. \\]\n\n(a) Prove that every integer $x \\geq 2$ can be written as the product of one or more elements of $A$, which are not necessarily different.\n\n(b) For every integer $x \\geq 2$ let $f(x)$ denote the minimum integer such that $x$ can be written as the\nproduct of $f(x)$ elements of $A$, which are not necessarily different.\n\nProve that there exist infinitely many pairs $(x,y)$ of integers with $x\\geq 2$, $y \\geq 2$, and \\[ f(xy)<f(x)+f(y). \\] (Pairs $(x_1,y_1)$ and $(x_2,y_2)$ are different if $x_1 \\neq x_2$ or $y_1 \\neq y_2$).\n[/list]","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2018-3","source":"EGMO","year":2018,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"The $n$ contestant of EGMO are named $C_1, C_2, \\cdots C_n$. After the competition, they queue in front of the restaurant according to the following rules.\n\n(i) The Jury chooses the initial order of the contestants in the queue.\n\n(ii) Every minute, the Jury chooses an integer $i$ with $1 \\leq i \\leq n$.\n\n(iii) If contestant $C_i$ has at least $i$ other contestants in front of her, she pays one euro to the Jury and moves forward in the queue by exactly $i$ positions.\n\n(iv) If contestant $C_i$ has fewer than $i$ other contestants in front of her, the restaurant opens and process ends.\n\n(a) Prove that the process cannot continue indefinitely, regardless of the Jury’s choices.\n\n(b) Determine for every $n$ the maximum number of euros that the Jury can collect by cunningly choosing the initial order and the sequence of moves.","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2018-4","source":"EGMO","year":2018,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"A domino is a $1 \\times 2$ or $2 \\times 1$ tile.\nLet $n \\ge 3$ be an integer. Dominoes are placed on an $n \\times n$ board in such a way that each domino covers exactly two cells of the board, and dominoes do not overlap. The value of a row or column is the number of dominoes that cover at least one cell of this row or column. The configuration is called balanced if there exists some $k \\ge 1$ such that each row and each column has a value of $k$. Prove that a balanced configuration exists for every $n \\ge 3$, and find the minimum number of dominoes needed in such a configuration.","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2018-5","source":"EGMO","year":2018,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $\\Gamma$ be the circumcircle of triangle $ABC$. A circle $\\Omega$ is tangent to the line segment $AB$ and is tangent to $\\Gamma$ at a point lying on the same side of the line $AB$ as $C$. The angle bisector of $\\angle BCA$ intersects $\\Omega$ at two different points $P$ and $Q$.\nProve that $\\angle ABP = \\angle QBC$.","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2018-6","source":"EGMO","year":2018,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"(a) Prove that for every real number $t$ such that $0 < t < \\tfrac{1}{2}$ there exists a positive integer $n$ with the following property: for every set $S$ of $n$ positive integers there exist two different elements $x$ and $y$ of $S$, and a non-negative integer $m$ (i.e. $m \\ge 0$), such that \\[ |x-my|\\leq ty. \\]\n\n(b) Determine whether for every real number $t$ such that $0 < t < \\tfrac{1}{2}$ there exists an infinite set $S$ of positive integers such that \\[ |x-my| > ty \\] for every pair of different elements $x$ and $y$ of $S$ and every positive integer $m$ (i.e. $m > 0$).","url":"https://artofproblemsolving.com/wiki/index.php/2018_EGMO_Problems"},{"id":"EGMO-2019-1","source":"EGMO","year":2019,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"Find all triples $(a, b, c)$ of real numbers such that $ab + bc + ca = 1$ and\n\n\\[ a^2b + c = b^2c + a = c^2a + b. \\]","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2019-2","source":"EGMO","year":2019,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. Dominoes are placed on a $2n \\times 2n$ board in such a way that every cell of the board is adjacent to exactly one cell covered by a domino. For each $n$, determine the largest number of dominoes that can be placed in this way.\n(A domino is a tile of size $2 \\times 1$ or $1 \\times 2$. Dominoes are placed on the board in such a way that each domino covers exactly two cells of the board, and dominoes do not overlap. Two cells are said to be adjacent if they are different and share a common side.)","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2019-3","source":"EGMO","year":2019,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle such that $\\angle CAB > \\angle ABC$, and let $I$ be its incentre. Let $D$ be the point on segment $BC$ such that $\\angle CAD = \\angle ABC$. Let $\\omega$ be the circle tangent to $AC$ at $A$ and passing through $I$. Let $X$ be the second point of intersection of $\\omega$ and the circumcircle of $ABC$. Prove that the angle bisectors of $\\angle DAB$ and $\\angle CXB$ intersect at a point on line $BC$.","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2019-4","source":"EGMO","year":2019,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incentre $I$. The circle through $B$ tangent to $AI$ at $I$ meets side $AB$ again at $P$. The circle through $C$ tangent to $AI$ at $I$ meets side $AC$ again at $Q$. Prove that $PQ$ is tangent to the incircle of $ABC.$","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2019-5","source":"EGMO","year":2019,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $n\\ge 2$ be an integer, and let $a_1, a_2, \\cdots , a_n$ be positive integers. Show that there exist positive integers $b_1, b_2, \\cdots, b_n$ satisfying the following three conditions:\n\n(a) $a_i\\le b_i$ for $i=1, 2, \\cdots , n;$\n\n(b) the remainders of $b_1, b_2, \\cdots, b_n$ on division by $n$ are pairwise different; and\n\n(c) $b_1+b_2+\\cdots b_n \\le n\\left(\\frac{n-1}{2}+\\left\\lfloor \\frac{a_1+a_2+\\cdots a_n}{n}\\right \\rfloor \\right)$\n\n(Here, $\\lfloor x \\rfloor$ denotes the integer part of real number $x$, that is, the largest integer that does not exceed $x$.)","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2019-6","source":"EGMO","year":2019,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"On a circle, Alina draws $2019$ chords, the endpoints of which are all different. A point is considered marked if it is either\n\n(i) one of the $4038$ endpoints of a chord; or\n\n(ii) an intersection point of at least two chords.\n\nAlina labels each marked point. Of the $4038$ points meeting criterion (i), Alina labels $2019$ points with a $0$ and the other $2019$ points with a $1$. She labels each point meeting criterion (ii) with an arbitrary integer (not necessarily positive).\nAlong each chord, Alina considers the segments connecting two consecutive marked points. (A chord with $k$ marked points has $k-1$ such segments.) She labels each such segment in yellow with the sum of the labels of its two endpoints and in blue with the absolute value of their difference.\nAlina finds that the $N + 1$ yellow labels take each value $0, 1, . . . , N$ exactly once. Show that at least one blue label is a multiple of $3$.\n(A chord is a line segment joining two different points on a circle.)","url":"https://artofproblemsolving.com/wiki/index.php/2019_EGMO_Problems"},{"id":"EGMO-2020-1","source":"EGMO","year":2020,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"The positive integers $a_0, a_1, a_2, \\ldots, a_{3030}$ satisfy\\[ 2a_{n + 2} = a_{n + 1} + 4a_n \\text{ for } n = 0, 1, 2, \\ldots, 3028. \\]\nProve that at least one of the numbers $a_0, a_1, a_2, \\ldots, a_{3030}$ is divisible by $2^{2020}$.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2020-2","source":"EGMO","year":2020,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all lists $(x_1, x_2, \\ldots, x_{2020})$ of non-negative real numbers such that the following three conditions are all satisfied:\n\n(i) $x_1 \\le x_2 \\le \\ldots \\le x_{2020}$\n\n(ii) $x_{2020} \\le x_1  + 1$\n\n(iii) there is a permutation $(y_1, y_2, \\ldots, y_{2020})$ of $(x_1, x_2, \\ldots, x_{2020})$ such that\\[ \\sum_{i = 1}^{2020} ((x_i + 1)(y_i + 1))^2 = 8 \\sum_{i = 1}^{2020} x_i^3. \\]\n\nA permutation of a list is a list of the same length, with the same entries, but the entries are allowed to be in any order. For example, $(2, 1, 2)$ is a permutation of $(1, 2, 2)$, and they are both permutations of $(2, 2, 1)$. Note that any list is a permutation of itself.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2020-3","source":"EGMO","year":2020,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABCDEF$ be a convex hexagon such that $\\angle A = \\angle C = \\angle E$ and $\\angle B = \\angle D = \\angle F$ and the (interior) angle bisectors of $\\angle A, ~\\angle C,$ and $\\angle E$ are concurrent.\n\nProve that the (interior) angle bisectors of $\\angle B, ~\\angle D,$ and $\\angle F$ must also be concurrent.\n\nNote that $\\angle A = \\angle FAB$. The other interior angles of the hexagon are similarly described.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2020-4","source":"EGMO","year":2020,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"A permutation of the integers $1, 2, \\ldots, m$ is called fresh if there exists no positive integer $k < m$ such that the first $k$ numbers in the permutation are $1, 2, \\ldots, k$ in some order. Let $f_m$ be the number of fresh permutations of the integers $1, 2, \\ldots, m$.\n\nProve that $f_n \\ge n \\cdot f_{n - 1}$ for all $n \\ge 3$.\n\nFor example, if $m = 4$, then the permutation $(3, 1, 4, 2)$ is fresh, whereas the permutation $(2, 3, 1, 4)$ is not.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2020-5","source":"EGMO","year":2020,"code":"G5","subject":"Geometry","level":6,"country":"","format":"latex","body":"Consider the triangle $ABC$ with $\\angle BCA > 90^{\\circ}$. The circumcircle $\\Gamma$ of $ABC$ has radius $R$. There is a point $P$ in the interior of the line segment $AB$ such that $PB = PC$ and the length of $PA$ is $R$. The perpendicular bisector of $PB$ intersects $\\Gamma$ at the points $D$ and $E$.\n\nProve $P$ is the incentre of triangle $CDE$.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2020-6","source":"EGMO","year":2020,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $m > 1$ be an integer. A sequence $a_1, a_2, a_3, \\ldots$ is defined by $a_1 = a_2 = 1$, $a_3 = 4$, and for all $n \\ge 4$,\\[ a_n = m(a_{n - 1} + a_{n - 2}) - a_{n - 3}. \\]\nDetermine all integers $m$ such that every term of the sequence is a square.","url":"https://artofproblemsolving.com/wiki/index.php/2020_EGMO_Problems"},{"id":"EGMO-2021-1","source":"EGMO","year":2021,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"The number 2021 is fantabulous. For any positive integer $m$, if any element of the set $\\{m, 2m+1, 3m\\}$ is fantabulous, then all the elements are fantabulous. Does it follow that the number $2021^{2021}$ is fantabulous?","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2021-2","source":"EGMO","year":2021,"code":"A2","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all functions $f:\\mathbb{Q}\\to\\mathbb{Q}$ such that the equation\n\\[ f(xf(x)+y) = f(y) + x^2 \\]holds for all rational numbers $x$ and $y$.\n\nHere, $\\mathbb{Q}$ denotes the set of rational numbers.","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2021-3","source":"EGMO","year":2021,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle with an obtuse angle at $A$. Let $E$ and $F$ be the intersections of the external bisector of angle $A$ with the altitudes of $ABC$ through $B$ and $C$ respectively. Let $M$ and $N$ be the points on the segments $EC$ and $FB$ respectively such that $\\angle EMA = \\angle BCA$ and $\\angle ANF = \\angle ABC$. Prove that the points $E, F, N, M$ lie on a circle.","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2021-4","source":"EGMO","year":2021,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$ and let $D$ be an arbitrary point on the side $BC$. Let the line through $D$ perpendicular to $BI$ intersect $CI$ at $E$. Let the line through $D$ perpendicular to $CI$ intersect $BI$ at $F$. Prove that the reflection of $A$ across the line $EF$ lies on the line $BC$.","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2021-5","source":"EGMO","year":2021,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"A plane has a special point $O$ called the origin. Let $P$ be a set of 2021 points in the plane such that\n\n(i) no three points in $P$ lie on a line and\n\n(ii) no two points in $P$ lie on a line through the origin.\n\nA triangle with vertices in $P$ is fat if $O$ is strictly inside the triangle. Find the maximum number of fat triangles.","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2021-6","source":"EGMO","year":2021,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Does there exist a nonnegative integer $a$ for which the equation\n\\[ \\left\\lfloor\\frac{m}{1}\\right\\rfloor + \\left\\lfloor\\frac{m}{2}\\right\\rfloor + \\left\\lfloor\\frac{m}{3}\\right\\rfloor + \\cdots + \\left\\lfloor\\frac{m}{m}\\right\\rfloor = n^2 + a \\]has more than one million different solutions $(m, n)$ where $m$ and $n$ are positive integers?\n\nThe expression $\\lfloor x\\rfloor$ denotes the integer part (or floor) of the real number $x$. Thus $\\lfloor\\sqrt{2}\\rfloor = 1, \\lfloor\\pi\\rfloor =\\lfloor 22/7 \\rfloor = 3, \\lfloor 42\\rfloor = 42,$ and $\\lfloor 0 \\rfloor = 0$.","url":"https://artofproblemsolving.com/wiki/index.php/2021_EGMO_Problems"},{"id":"EGMO-2022-1","source":"EGMO","year":2022,"code":"G1","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be an acute-angled triangle in which $BC<AB$ and $BC<CA$. Let point $P$ lie on segment $AB$ and point $Q$ lie on segment $AC$ such that $P \\neq B$, $Q \\neq C$ and $BQ = BC = CP$. Let $T$ be the circumcenter of triangle $APQ$, $H$ the orthocenter of triangle $ABC$, and $S$ the point of intersection of the lines $BQ$ and $CP$. Prove that $T$, $H$, and $S$ are collinear.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2022-2","source":"EGMO","year":2022,"code":"N2","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $\\mathbb{N}=\\{1, 2, 3, \\dots\\}$ be the set of all positive integers. Find all functions $f : \\mathbb{N} \\rightarrow \\mathbb{N}$ such that for any positive integers $a$ and $b$, the following two conditions hold:\n(i) $f(ab) = f(a)f(b)$, and\n\n(ii) at least two of the numbers $f(a)$, $f(b)$, and $f(a+b)$ are equal.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2022-3","source":"EGMO","year":2022,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"An infinite sequence of positive integers $a_1, a_2, \\dots$ is called $good$ if\n\n(i) $a_1$ is a perfect square, and\n\n(ii) for any integer $n \\ge 2$, $a_n$ is the smallest positive integer such that\\[ na_1 + (n-1)a_2 + \\dots + 2a_{n-1} + a_n \\]is a perfect square.\n\nProve that for any good sequence $a_1, a_2, \\dots$, there exists a positive integer $k$ such that $a_n=a_k$ for all integers $n \\ge k$.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2022-4","source":"EGMO","year":2022,"code":"A4","subject":"Algebra","level":4,"country":"","format":"latex","body":"Given a positive integer $n \\ge 2$, determine the largest positive integer $N$ for which there exist $N+1$ real numbers $a_0, a_1, \\dots, a_N$ such that\n$(1) \\$ $a_0+a_1 = -\\frac{1}{n},$ and\n$(2) \\$ $(a_k+a_{k-1})(a_k+a_{k+1})=a_{k-1}-a_{k+1}$ for $1 \\le k \\le N-1$.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2022-5","source":"EGMO","year":2022,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"For all positive integers $n$, $k$, let $f(n, 2k)$ be the number of ways an $n \\times 2k$ board can be fully covered by $nk$ dominoes of size $2 \\times 1$. (For example, $f(2, 2)=2$ and $f(3, 2)=3$.) Find all positive integers $n$ such that for every positive integer $k$, the number $f(n, 2k)$ is odd.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2022-6","source":"EGMO","year":2022,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic quadrilateral with circumcenter $O$. Let the internal angle bisectors at $A$ and $B$ meet at $X$, the internal angle bisectors at $B$ and $C$ meet at $Y$, the internal angle bisectors at $C$ and $D$ meet at $Z$, and the internal angle bisectors at $D$ and $A$ meet at $W$. Further, let $AC$ and $BD$ meet at $P$. Suppose that the points $X$, $Y$, $Z$, $W$, $O$, and $P$ are distinct.\n\nProve that $O$, $X$, $Y$ $Z$, $W$ lie on the same circle if and only if $P$, $X$, $Y$, $Z$, and $W$ lie on the same circle.","url":"https://artofproblemsolving.com/wiki/index.php/2022_EGMO_Problems"},{"id":"EGMO-2023-1","source":"EGMO","year":2023,"code":"A1","subject":"Algebra","level":4,"country":"","format":"latex","body":"There are $n \\geqslant 3$ positive real numbers $a_1, a_2, \\ldots, a_n$. For each $1 \\leqslant i \\leqslant n$ we let\n\\[ b_i = \\frac{a_{i-1} + a_{i+1}}{a_i} \\]\n(here we define $a_0$ to be $a_n$ and $a_{n+1}$ to be $a_1$). Assume that for all $i$ and $j$ in the range $1$ to $n$, we have $a_i \\leqslant a_j$ if and only if $b_i \\leqslant b_j$.\n\nProve that $a_1 = a_2 = \\cdots = a_n$.","url":"https://www.egmo.org/"},{"id":"EGMO-2023-2","source":"EGMO","year":2023,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"We are given an acute triangle $ABC$. Let $D$ be the point on its circumcircle such that $AD$ is a diameter. Suppose that points $K$ and $L$ lie on segments $AB$ and $AC$, respectively, and that $DK$ and $DL$ are tangent to circle $AKL$.\n\nShow that line $KL$ passes through the orthocentre of $ABC$.\n\nThe orthocentre of a triangle is the point of intersection of its altitudes.","url":"https://www.egmo.org/"},{"id":"EGMO-2023-3","source":"EGMO","year":2023,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $k$ be a positive integer. Lexi has a dictionary $\\mathcal{D}$ consisting of some $k$-letter strings containing only the letters $A$ and $B$. Lexi would like to write either the letter $A$ or the letter $B$ in each cell of a $k \\times k$ grid so that each column contains a string from $\\mathcal{D}$ when read from top-to-bottom and each row contains a string from $\\mathcal{D}$ when read from left-to-right.\n\nWhat is the smallest integer $m$ such that if $\\mathcal{D}$ contains at least $m$ different strings, then Lexi can fill her grid in this manner, no matter what strings are in $\\mathcal{D}$?","url":"https://www.egmo.org/"},{"id":"EGMO-2023-4","source":"EGMO","year":2023,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Turbo the snail sits on a point on a circle with circumference $1$. Given an infinite sequence of positive real numbers $c_1, c_2, c_3, \\ldots$, Turbo successively crawls distances $c_1, c_2, c_3, \\ldots$ around the circle, each time choosing to crawl either clockwise or counterclockwise.\n\nFor example, if the sequence $c_1, c_2, c_3, \\ldots$ is $0.4, 0.6, 0.3, \\ldots$, then Turbo may start crawling as follows:\n\nDetermine the largest constant $C > 0$ with the following property: for every sequence of positive real numbers $c_1, c_2, c_3, \\ldots$ with $c_i < C$ for all $i$, Turbo can (after studying the sequence) ensure that there is some point on the circle that it will never visit or crawl across.","url":"https://www.egmo.org/"},{"id":"EGMO-2023-5","source":"EGMO","year":2023,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"We are given a positive integer $s \\geqslant 2$. For each positive integer $k$, we define its \\emph{twist} $k'$ as follows: write $k$ as $as + b$, where $a, b$ are non-negative integers and $b < s$, then $k' = bs + a$. For the positive integer $n$, consider the infinite sequence $d_1, d_2, \\ldots$ where $d_1 = n$ and $d_{i+1}$ is the twist of $d_i$ for each positive integer $i$.\n\nProve that this sequence contains $1$ if and only if the remainder when $n$ is divided by $s^2 - 1$ is either $1$ or $s$.","url":"https://www.egmo.org/"},{"id":"EGMO-2023-6","source":"EGMO","year":2023,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle with circumcircle $\\Omega$. Let $S_b$ and $S_c$ respectively denote the midpoints of the arcs $AC$ and $AB$ that do not contain the third vertex. Let $N_a$ denote the midpoint of arc $BAC$ (the arc $BC$ containing $A$). Let $I$ be the incentre of $ABC$. Let $\\omega_b$ be the circle that is tangent to $AB$ and internally tangent to $\\Omega$ at $S_b$, and let $\\omega_c$ be the circle that is tangent to $AC$ and internally tangent to $\\Omega$ at $S_c$. Show that the line $IN_a$, and the line through the intersections of $\\omega_b$ and $\\omega_c$, meet on $\\Omega$.\n\nThe incentre of a triangle is the centre of its incircle, the circle inside the triangle that is tangent to all three sides.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-1","source":"EGMO","year":2024,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Two different integers $u$ and $v$ are written on a board. We perform a sequence of steps. At each step we do one of the following two operations:\n\n(i) If $a$ and $b$ are different integers on the board, then we can write $a + b$ on the board, if it is not already there.\n\n(ii) If $a$, $b$ and $c$ are three different integers on the board, and if an integer $x$ satisfies $ax^2 + bx + c = 0$, then we can write $x$ on the board, if it is not already there.\n\nDetermine all pairs of starting numbers $(u, v)$ from which any integer can eventually be written on the board after a finite sequence of steps.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-2","source":"EGMO","year":2024,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle with $AC > AB$, and denote its circumcircle by $\\Omega$ and incentre by $I$. Let its incircle meet sides $BC, CA, AB$ at $D, E, F$ respectively. Let $X$ and $Y$ be two points on minor arcs $\\widehat{DF}$ and $\\widehat{DE}$ of the incircle, respectively, such that $\\angle BXD = \\angle DYC$. Let line $XY$ meet line $BC$ at $K$. Let $T$ be the point on $\\Omega$ such that $KT$ is tangent to $\\Omega$ and $T$ is on the same side of line $BC$ as $A$. Prove that lines $TD$ and $AI$ meet on $\\Omega$.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-3","source":"EGMO","year":2024,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"We call a positive integer $n$ \\emph{peculiar} if, for any positive divisor $d$ of $n$, the integer $d(d + 1)$ divides $n(n + 1)$. Prove that for any four different peculiar positive integers $A, B, C$ and $D$, the following holds:\n\\[ \\gcd(A, B, C, D) = 1. \\]\nHere $\\gcd(A, B, C, D)$ is the largest positive integer that divides all of $A, B, C$ and $D$.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-4","source":"EGMO","year":2024,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"For a sequence $a_1 < a_2 < \\cdots < a_n$ of integers, a pair $(a_i, a_j)$ with $1 \\leq i < j \\leq n$ is called \\emph{interesting} if there exists a pair $(a_k, a_\\ell)$ of integers with $1 \\leq k < \\ell \\leq n$ such that\n\\[ \\frac{a_\\ell - a_k}{a_j - a_i} = 2. \\]\nFor each $n \\geq 3$, find the largest possible number of interesting pairs in a sequence of length $n$.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-5","source":"EGMO","year":2024,"code":"N5","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $\\mathbb{N}$ denote the set of positive integers. Find all functions $f : \\mathbb{N} \\to \\mathbb{N}$ such that the following conditions are true for every pair of positive integers $(x, y)$:\n\n(i) $x$ and $f(x)$ have the same number of positive divisors.\n\n(ii) If $x$ does not divide $y$ and $y$ does not divide $x$, then\n\\[ \\gcd(f(x), f(y)) > f(\\gcd(x, y)). \\]\nHere $\\gcd(m, n)$ is the largest positive integer that divides both $m$ and $n$.","url":"https://www.egmo.org/"},{"id":"EGMO-2024-6","source":"EGMO","year":2024,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all positive integers $d$ for which there exists a degree $d$ polynomial $P$ with real coefficients such that there are at most $d$ different values among $P(0), P(1), P(2), \\ldots, P(d^2 - d)$.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-1","source":"EGMO","year":2025,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"For a positive integer $N$, let $c_1 < c_2 < \\cdots < c_m$ be all the positive integers smaller than $N$ that are coprime to $N$. Find all $N \\geq 3$ such that\n\\[ \\gcd(N, c_i + c_{i+1}) \\neq 1 \\]\nfor all $1 \\leq i \\leq m - 1$.\n\nHere $\\gcd(a, b)$ is the largest positive integer that divides both $a$ and $b$. Integers $a$ and $b$ are coprime if $\\gcd(a, b) = 1$.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-2","source":"EGMO","year":2025,"code":"C2","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"An infinite increasing sequence $a_1 < a_2 < a_3 < \\cdots$ of positive integers is called \\emph{central} if for every positive integer $n$, the arithmetic mean of the first $a_n$ terms of the sequence is equal to $a_n$.\n\nShow that there exists an infinite sequence $b_1, b_2, b_3, \\ldots$ of positive integers such that for every central sequence $a_1, a_2, a_3, \\ldots$, there are infinitely many positive integers $n$ with $a_n = b_n$.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-3","source":"EGMO","year":2025,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle. Points $B, D, E,$ and $C$ lie on a line in this order and satisfy $BD = DE = EC$. Let $M$ and $N$ be the midpoints of $AD$ and $AE$, respectively. Suppose triangle $ADE$ is acute, and let $H$ be its orthocentre. Points $P$ and $Q$ lie on lines $BM$ and $CN$, respectively, such that $D, H, M,$ and $P$ are concyclic and pairwise different, and $E, H, N,$ and $Q$ are concyclic and pairwise different. Prove that $P, Q, N,$ and $M$ are concyclic.\n\nThe orthocentre of a triangle is the point of intersection of its altitudes.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-4","source":"EGMO","year":2025,"code":"G4","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with incentre $I$ and $AB \\neq AC$. Let lines $BI$ and $CI$ intersect the circumcircle of $ABC$ at $P \\neq B$ and $Q \\neq C$, respectively. Consider points $R$ and $S$ such that $AQRB$ and $ACSP$ are parallelograms (with $AQ \\parallel RB$, $AB \\parallel QR$, $AC \\parallel SP$, and $AP \\parallel CS$). Let $T$ be the point of intersection of lines $RB$ and $SC$. Prove that points $R, S, T,$ and $I$ are concyclic.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-5","source":"EGMO","year":2025,"code":"C5","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n > 1$ be an integer. In a \\emph{configuration} of an $n \\times n$ board, each of the $n^2$ cells contains an arrow, either pointing up, down, left, or right. Given a starting configuration, Turbo the snail starts in one of the cells of the board and travels from cell to cell. In each move, Turbo moves one square unit in the direction indicated by the arrow in her cell (possibly leaving the board). After each move, the arrows in all of the cells rotate $90^\\circ$ counterclockwise. We call a cell \\emph{good} if, starting from that cell, Turbo visits each cell of the board exactly once, without leaving the board, and returns to her initial cell at the end. Determine, in terms of $n$, the maximum number of good cells over all possible starting configurations.","url":"https://www.egmo.org/"},{"id":"EGMO-2025-6","source":"EGMO","year":2025,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"In each cell of a $2025 \\times 2025$ board, a nonnegative real number is written in such a way that the sum of the numbers in each row is equal to $1$, and the sum of the numbers in each column is equal to $1$. Define $r_i$ to be the largest value in row $i$, and let $R = r_1 + r_2 + \\cdots + r_{2025}$. Similarly, define $c_i$ to be the largest value in column $i$, and let $C = c_1 + c_2 + \\cdots + c_{2025}$.\n\nWhat is the largest possible value of $\\frac{R}{C}$?","url":"https://www.egmo.org/"},{"id":"RMM-2012-1","source":"RMM","year":2012,"code":"C1","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Given a finite number of boys and girls, a \\emph{sociable set of boys} is a set of boys such that every girl knows at least one boy in that set; and a \\emph{sociable set of girls} is a set of girls such that every boy knows at least one girl in that set. Prove that the number of sociable sets of boys and the number of sociable sets of girls have the same parity. (Acquaintance is assumed to be mutual.)","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2012-2","source":"RMM","year":2012,"code":"G2","subject":"Geometry","level":8,"country":"","format":"latex","body":"Given a non-isosceles triangle $ABC$, let $D$, $E$, and $F$ denote the midpoints of the sides $BC$, $CA$, and $AB$ respectively. The circle $BCF$ and the line $BE$ meet again at $P$, and the circle $ABE$ and the line $AD$ meet again at $Q$. Finally, the lines $DP$ and $FQ$ meet at $R$. Prove that the centroid $G$ of the triangle $ABC$ lies on the circle $PQR$.","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2012-3","source":"RMM","year":2012,"code":"A3","subject":"Algebra","level":9,"country":"","format":"latex","body":"Each positive integer is coloured red or blue. A function $f$ from the set of positive integers to itself has the following two properties:\n\\begin{enumerate}\n\\item[(a)] if $x \\le y$, then $f(x) \\le f(y)$; and\n\\item[(b)] if $x$, $y$ and $z$ are (not necessarily distinct) positive integers of the same colour and $x + y = z$, then $f(x) + f(y) = f(z)$.\n\\end{enumerate}\nProve that there exists a positive number $a$ such that $f(x) \\le ax$ for all positive integers $x$.","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2012-4","source":"RMM","year":2012,"code":"N4","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Prove that there are infinitely many positive integers $n$ such that $2^{2^{n}+1} + 1$ is divisible by $n$ but $2^{n} + 1$ is not.","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2012-5","source":"RMM","year":2012,"code":"C5","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Given a positive integer $n \\ge 3$, colour each cell of an $n \\times n$ square array with one of $\\lfloor (n+2)^2/3 \\rfloor$ colours, each colour being used at least once. Prove that there is some $1 \\times 3$ or $3 \\times 1$ rectangular subarray whose three cells are coloured with three different colours.","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2012-6","source":"RMM","year":2012,"code":"G6","subject":"Geometry","level":9,"country":"","format":"latex","body":"Let $ABC$ be a triangle and let $I$ and $O$ denote its incentre and circumcentre respectively. Let $\\omega_A$ be the circle through $B$ and $C$ which is tangent to the incircle of the triangle $ABC$; the circles $\\omega_B$ and $\\omega_C$ are defined similarly. The circles $\\omega_B$ and $\\omega_C$ meet at a point $A'$ distinct from $A$; the points $B'$ and $C'$ are defined similarly. Prove that the lines $AA'$, $BB'$ and $CC'$ are concurrent at a point on the line $IO$.","url":"https://rmms.lbi.ro/rmm2012/index.php?id=problems_math"},{"id":"RMM-2013-1","source":"RMM","year":2013,"code":"N1","subject":"Number Theory","level":7,"country":"","format":"latex","body":"For a positive integer $a$, define a sequence of integers $x_1, x_2, \\ldots$ by letting $x_1 = a$ and $x_{n+1} = 2x_n + 1$ for $n \\ge 1$. Let $y_n = 2^{x_n} - 1$. Determine the largest possible $k$ such that, for some positive integer $a$, the numbers $y_1, \\ldots, y_k$ are all prime.","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2013-2","source":"RMM","year":2013,"code":"A2","subject":"Algebra","level":8,"country":"","format":"latex","body":"Does there exist a pair $(g, h)$ of functions $g, h \\colon \\mathbb{R} \\to \\mathbb{R}$ such that the only function $f \\colon \\mathbb{R} \\to \\mathbb{R}$ satisfying $f(g(x)) = g(f(x))$ and $f(h(x)) = h(f(x))$ for all $x \\in \\mathbb{R}$ is the identity function $f(x) \\equiv x$?","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2013-3","source":"RMM","year":2013,"code":"G3","subject":"Geometry","level":9,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral inscribed in a circle $\\omega$. The lines $AB$ and $CD$ meet at $P$, the lines $AD$ and $BC$ meet at $Q$, and the diagonals $AC$ and $BD$ meet at $R$. Let $M$ be the midpoint of the segment $PQ$, and let $K$ be the common point of the segment $MR$ and the circle $\\omega$. Prove that the circumcircle of the triangle $KPQ$ and $\\omega$ are tangent to one another.","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2013-4","source":"RMM","year":2013,"code":"G4","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $P$ and $P'$ be two convex quadrilateral regions in the plane (regions contain their boundary). Let them intersect, with $O$ a point in the intersection. Suppose that for every line $\\ell$ through $O$ the segment $\\ell \\cap P$ is strictly longer than the segment $\\ell \\cap P'$. Is it possible that the ratio of the area of $P'$ to the area of $P$ is greater than $1.9$?","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2013-5","source":"RMM","year":2013,"code":"N5","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Given an integer $k \\ge 2$, set $a_1 = 1$ and, for every integer $n \\ge 2$, let $a_n$ be the smallest $x > a_{n-1}$ such that:\n\\[ x = 1 + \\sum_{i=1}^{n-1} \\left\\lfloor \\sqrt[k]{\\frac{x}{a_i}} \\right\\rfloor. \\]\nProve that every prime occurs in the sequence $a_1, a_2, \\ldots$.","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2013-6","source":"RMM","year":2013,"code":"C6","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"$2n$ distinct tokens are placed at the vertices of a regular $2n$-gon, with one token placed at each vertex. A \\emph{move} consists of choosing an edge of the $2n$-gon and interchanging the two tokens at the endpoints of that edge. Suppose that after a finite number of moves, every pair of tokens have been interchanged exactly once. Prove that some edge has never been chosen.","url":"https://rmms.lbi.ro/rmm2013/index.php?id=problems_math"},{"id":"RMM-2015-1","source":"RMM","year":2015,"code":"N1","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Does there exist an infinite sequence of positive integers $a_1, a_2, a_3, \\ldots$ such that $a_m$ and $a_n$ are coprime if and only if $|m - n| = 1$?","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2015-2","source":"RMM","year":2015,"code":"C2","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"For an integer $n \\ge 5$, two players play the following game on a regular $n$-gon. Initially, three consecutive vertices are chosen, and one counter is placed on each. A move consists of one player sliding one counter along any number of edges to another vertex of the $n$-gon without jumping over another counter. A move is \\emph{legal} if the area of the triangle formed by the counters is strictly greater after the move than before. The players take turns to make legal moves, and if a player cannot make a legal move, that player loses. For which values of $n$ does the player making the first move have a winning strategy?","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2015-3","source":"RMM","year":2015,"code":"N3","subject":"Number Theory","level":9,"country":"","format":"latex","body":"A finite list of rational numbers is written on a blackboard. In an \\emph{operation}, we choose any two numbers $a, b$, erase them, and write down one of the numbers\n\\[ a + b,\\ a - b,\\ b - a,\\ a \\times b,\\ a/b \\ (\\text{if } b \\ne 0),\\ b/a \\ (\\text{if } a \\ne 0). \\]\nProve that, for every integer $n > 100$, there are only finitely many integers $k \\ge 0$, such that, starting from the list\n\\[ k + 1,\\ k + 2,\\ \\ldots,\\ k + n, \\]\nit is possible to obtain, after $n - 1$ operations, the value $n!$.","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2015-4","source":"RMM","year":2015,"code":"G4","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle, and let $D$ be the point where the incircle meets side $BC$. Let $J_b$ and $J_c$ be the incentres of the triangles $ABD$ and $ACD$, respectively. Prove that the circumcentre of the triangle $AJ_bJ_c$ lies on the angle bisector of $\\angle BAC$.","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2015-5","source":"RMM","year":2015,"code":"N5","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $p \\ge 5$ be a prime number. For a positive integer $k$, let $R(k)$ be the remainder when $k$ is divided by $p$, with $0 \\le R(k) \\le p - 1$. Determine all positive integers $a < p$ such that, for every $m = 1, 2, \\ldots, p - 1$,\n\\[ m + R(ma) > a. \\]","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2015-6","source":"RMM","year":2015,"code":"C6","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Given a positive integer $n$, determine the largest real number $\\mu$ satisfying the following condition: for every set $C$ of $4n$ points in the interior of the unit square $U$, there exists a rectangle $T$ contained in $U$ such that\n\\begin{itemize}\n\\item the sides of $T$ are parallel to the sides of $U$;\n\\item the interior of $T$ contains exactly one point of $C$;\n\\item the area of $T$ is at least $\\mu$.\n\\end{itemize}","url":"https://rmms.lbi.ro/rmm2015/index.php?id=problems_math"},{"id":"RMM-2016-1","source":"RMM","year":2016,"code":"G1","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle and let $D$ be a point on the segment $BC$, $D \\neq B$ and $D \\neq C$. The circle $ABD$ meets the segment $AC$ again at an interior point $E$. The circle $ACD$ meets the segment $AB$ again at an interior point $F$. Let $A'$ be the reflection of $A$ in the line $BC$. The lines $A'C$ and $DE$ meet at $P$, and the lines $A'B$ and $DF$ meet at $Q$. Prove that the lines $AD$, $BP$ and $CQ$ are concurrent (or all parallel).","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2016-2","source":"RMM","year":2016,"code":"C2","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Given positive integers $m$ and $n \\ge m$, determine the largest number of dominoes ($1 \\times 2$ or $2 \\times 1$ rectangles) that can be placed on a rectangular board with $m$ rows and $2n$ columns consisting of cells ($1 \\times 1$ squares) so that:\n\n(i) each domino covers exactly two adjacent cells of the board;\n\n(ii) no two dominoes overlap;\n\n(iii) no two form a $2 \\times 2$ square; and\n\n(iv) the bottom row of the board is completely covered by $n$ dominoes.","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2016-3","source":"RMM","year":2016,"code":"N3","subject":"Number Theory","level":9,"country":"","format":"latex","body":"A \\emph{cubic sequence} is a sequence of integers given by $a_n = n^3 + bn^2 + cn + d$, where $b$, $c$ and $d$ are integer constants and $n$ ranges over all integers, including negative integers.\n\n(a) Show that there exists a cubic sequence such that the only terms of the sequence which are squares of integers are $a_{2015}$ and $a_{2016}$.\n\n(b) Determine the possible values of $a_{2015} \\cdot a_{2016}$ for a cubic sequence satisfying the condition in part (a).","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2016-4","source":"RMM","year":2016,"code":"A4","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $x$ and $y$ be positive real numbers such that $x + y^{2016} \\ge 1$. Prove that $x^{2016} + y > 1 - 1/100$.","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2016-5","source":"RMM","year":2016,"code":"G5","subject":"Geometry","level":8,"country":"","format":"latex","body":"A convex hexagon $A_1B_1A_2B_2A_3B_3$ is inscribed in a circle $\\Omega$ of radius $R$. The diagonals $A_1B_2$, $A_2B_3$, and $A_3B_1$ concur at $X$. For $i = 1, 2, 3$, let $\\omega_i$ be the circle tangent to the segments $XA_i$ and $XB_i$, and to the arc $A_iB_i$ of $\\Omega$ not containing other vertices of the hexagon; let $r_i$ be the radius of $\\omega_i$.\n\n(a) Prove that $R \\ge r_1 + r_2 + r_3$.\n\n(b) If $R = r_1 + r_2 + r_3$, prove that the six points where the circles $\\omega_i$ touch the diagonals $A_1B_2$, $A_2B_3$, $A_3B_1$ are concyclic.","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2016-6","source":"RMM","year":2016,"code":"C6","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"A set of $n$ points in Euclidean 3-dimensional space, no four of which are coplanar, is partitioned into two subsets $\\mathcal{A}$ and $\\mathcal{B}$. An $\\mathcal{AB}$-tree is a configuration of $n - 1$ segments, each of which has an endpoint in $\\mathcal{A}$ and the other in $\\mathcal{B}$, and such that no segments form a closed polyline. An $\\mathcal{AB}$-tree is transformed into another as follows: choose three distinct segments $A_1B_1$, $B_1A_2$ and $A_2B_2$ in the $\\mathcal{AB}$-tree such that $A_1$ is in $\\mathcal{A}$ and $A_1B_1 + A_2B_2 > A_1B_2 + A_2B_1$, and remove the segment $A_1B_1$ to replace it by the segment $A_1B_2$. Given any $\\mathcal{AB}$-tree, prove that every sequence of successive transformations comes to an end (no further transformation is possible) after finitely many steps.","url":"https://rmms.lbi.ro/rmm2016/index.php?id=problems_math"},{"id":"RMM-2017-1","source":"RMM","year":2017,"code":"N1","subject":"Number Theory","level":7,"country":"","format":"latex","body":"(a) Prove that every positive integer $n$ can be written uniquely in the form\n\\[ n = \\sum_{j=1}^{2k+1} (-1)^{j-1} 2^{m_j}, \\]\nwhere $k \\ge 0$ and $0 \\le m_1 < m_2 < \\cdots < m_{2k+1}$ are integers.\n\nThis number $k$ is called the \\emph{weight} of $n$.\n\n(b) Find (in closed form) the difference between the number of positive integers at most $2^{2017}$ with even weight and the number of positive integers at most $2^{2017}$ with odd weight.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2017-2","source":"RMM","year":2017,"code":"A2","subject":"Algebra","level":8,"country":"","format":"latex","body":"Determine all positive integers $n$ satisfying the following condition: for every monic polynomial $P$ of degree at most $n$ with integer coefficients, there exists a positive integer $k \\le n$, and $k + 1$ distinct integers $x_1, x_2, \\ldots, x_{k+1}$ such that\n\\[ P(x_1) + P(x_2) + \\cdots + P(x_k) = P(x_{k+1}). \\]\n\n\\emph{Note.} A polynomial is \\emph{monic} if the coefficient of the highest power is one.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2017-3","source":"RMM","year":2017,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Let $n$ be an integer greater than $1$ and let $X$ be an $n$-element set. A non-empty collection of subsets $A_1, \\ldots, A_k$ of $X$ is \\emph{tight} if the union $A_1 \\cup \\cdots \\cup A_k$ is a proper subset of $X$ and no element of $X$ lies in exactly one of the $A_i$s. Find the largest cardinality of a collection of proper non-empty subsets of $X$, no non-empty subcollection of which is tight.\n\n\\emph{Note.} A subset $A$ of $X$ is \\emph{proper} if $A \\neq X$. The sets in a collection are assumed to be distinct. The whole collection is assumed to be a subcollection.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2017-4","source":"RMM","year":2017,"code":"G4","subject":"Geometry","level":7,"country":"","format":"latex","body":"In the Cartesian plane, let $\\mathcal{G}_1$ and $\\mathcal{G}_2$ be the graphs of the quadratic functions $f_1(x) = p_1x^2 + q_1x + r_1$ and $f_2(x) = p_2x^2 + q_2x + r_2$, where $p_1 > 0 > p_2$. The graphs $\\mathcal{G}_1$ and $\\mathcal{G}_2$ cross at distinct points $A$ and $B$. The four tangents to $\\mathcal{G}_1$ and $\\mathcal{G}_2$ at $A$ and $B$ form a convex quadrilateral which has an inscribed circle. Prove that the graphs $\\mathcal{G}_1$ and $\\mathcal{G}_2$ have the same axis of symmetry.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2017-5","source":"RMM","year":2017,"code":"C5","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Fix an integer $n \\ge 2$. An $n \\times n$ \\emph{sieve} is an $n \\times n$ array with $n$ cells removed so that exactly one cell is removed from every row and every column. A \\emph{stick} is a $1 \\times k$ or $k \\times 1$ array for any positive integer $k$. For any sieve $A$, let $m(A)$ be the minimal number of sticks required to partition $A$. Find all possible values of $m(A)$, as $A$ varies over all possible $n \\times n$ sieves.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2017-6","source":"RMM","year":2017,"code":"G6","subject":"Geometry","level":9,"country":"","format":"latex","body":"Let $ABCD$ be any convex quadrilateral and let $P, Q, R, S$ be points on the segments $AB$, $BC$, $CD$, and $DA$, respectively. It is given that the segments $PR$ and $QS$ dissect $ABCD$ into four quadrilaterals, each of which has perpendicular diagonals. Show that the points $P, Q, R, S$ are concyclic.","url":"https://rmms.lbi.ro/rmm2017/index.php?id=problems_math"},{"id":"RMM-2018-1","source":"RMM","year":2018,"code":"G1","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic quadrangle and let $P$ be a point on the side $AB$. The diagonal $AC$ crosses the segment $DP$ at $Q$. The parallel through $P$ to $CD$ crosses the extension of the side $BC$ beyond $B$ at $K$, and the parallel through $Q$ to $BD$ crosses the extension of the side $BC$ beyond $B$ at $L$. Prove that the circumcircles of the triangles $BKP$ and $CLQ$ are tangent.","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2018-2","source":"RMM","year":2018,"code":"A2","subject":"Algebra","level":8,"country":"","format":"latex","body":"Determine whether there exist non-constant polynomials $P(x)$ and $Q(x)$ with real coefficients satisfying\n\\[ P(x)^{10} + P(x)^9 = Q(x)^{21} + Q(x)^{20}. \\]","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2018-3","source":"RMM","year":2018,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Ann and Bob play a game on an infinite checkered plane making moves in turn; Ann makes the first move. A move consists in orienting any unit grid-segment that has not been oriented before. If at some stage some oriented segments form an oriented cycle, Bob wins. Does Bob have a strategy that guarantees him to win?","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2018-4","source":"RMM","year":2018,"code":"N4","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Let $a, b, c, d$ be positive integers such that $ad \\neq bc$ and $\\gcd(a, b, c, d) = 1$. Prove that, as $n$ runs through the positive integers, the values $\\gcd(an+b, cn+d)$ may achieve form the set of all positive divisors of some integer.","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2018-5","source":"RMM","year":2018,"code":"C5","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n$ be a positive integer and fix $2n$ distinct points on a circumference. Split these points into $n$ pairs and join the points in each pair by an arrow (i.e., an oriented line segment). The resulting configuration is \\emph{good} if no two arrows cross, and there are no arrows $\\overrightarrow{AB}$ and $\\overrightarrow{CD}$ such that $ABCD$ is a convex quadrangle oriented clockwise. Determine the number of good configurations.","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2018-6","source":"RMM","year":2018,"code":"G6","subject":"Geometry","level":9,"country":"","format":"latex","body":"Fix a circle $\\Gamma$, a line $\\ell$ tangent to $\\Gamma$, and another circle $\\Omega$ disjoint from $\\ell$ such that $\\Gamma$ and $\\Omega$ lie on opposite sides of $\\ell$. The tangents to $\\Gamma$ from a variable point $X$ on $\\Omega$ cross $\\ell$ at $Y$ and $Z$. Prove that, as $X$ traces $\\Omega$, the circle $XYZ$ is tangent to two fixed circles.","url":"https://rmms.lbi.ro/rmm2018/index.php?id=problems_math"},{"id":"RMM-2019-1","source":"RMM","year":2019,"code":"C1","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Amy and Bob play the game. At the beginning, Amy writes down a positive integer on the board. Then the players take moves in turn, Bob moves first. On any move of his, Bob replaces the number $n$ on the blackboard with a number of the form $n - a^2$, where $a$ is a positive integer. On any move of hers, Amy replaces the number $n$ on the blackboard with a number of the form $n^k$, where $k$ is a positive integer. Bob wins if the number on the board becomes zero. Can Amy prevent Bob's win?","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2019-2","source":"RMM","year":2019,"code":"G2","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABCD$ be an isosceles trapezoid with $AB \\parallel CD$. Let $E$ be the midpoint of $AC$. Denote by $\\omega$ and $\\Omega$ the circumcircles of the triangles $ABE$ and $CDE$, respectively. Let $P$ be the crossing point of the tangent to $\\omega$ at $A$ with the tangent to $\\Omega$ at $D$. Prove that $PE$ is tangent to $\\Omega$.","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2019-3","source":"RMM","year":2019,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Given any positive real number $\\varepsilon$, prove that, for all but finitely many positive integers $v$, any graph on $v$ vertices with at least $(1 + \\varepsilon)v$ edges has two distinct simple cycles of equal lengths.\n\n(Recall that the notion of a simple cycle does not allow repetition of vertices in a cycle.)","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2019-4","source":"RMM","year":2019,"code":"C4","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Prove that for every positive integer $n$ there exists a (not necessarily convex) polygon with no three collinear vertices, which admits exactly $n$ different triangulations.\n\n(A triangulation is a dissection of the polygon into triangles by interior diagonals which have no common interior points with each other nor with the sides of the polygon.)","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2019-5","source":"RMM","year":2019,"code":"A5","subject":"Algebra","level":8,"country":"","format":"latex","body":"Determine all functions $f : \\mathbb{R} \\to \\mathbb{R}$ satisfying\n\\[ f(x + yf(x)) + f(xy) = f(x) + f(2019y), \\]\nfor all real numbers $x$ and $y$.","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2019-6","source":"RMM","year":2019,"code":"N6","subject":"Number Theory","level":9,"country":"","format":"latex","body":"Find all pairs of integers $(c, d)$, both greater than $1$, such that the following holds:\n\nFor any monic polynomial $Q$ of degree $d$ with integer coefficients and for any prime $p > c(2c + 1)$, there exists a set $S$ of at most $\\left(\\frac{2c-1}{2c+1}\\right)p$ integers, such that\n\\[ \\bigcup_{s \\in S} \\{s, Q(s), Q(Q(s)), Q(Q(Q(s))), \\ldots\\} \\]\nis a complete residue system modulo $p$ (i.e., intersects with every residue class modulo $p$).","url":"https://rmms.lbi.ro/rmm2019/index.php?id=problems_math"},{"id":"RMM-2021-1","source":"RMM","year":2021,"code":"G1","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $T_1, T_2, T_3, T_4$ be pairwise distinct collinear points such that $T_2$ lies between $T_1$ and $T_3$, and $T_3$ lies between $T_2$ and $T_4$. Let $\\omega_1$ be a circle through $T_1$ and $T_4$; let $\\omega_2$ be the circle through $T_2$ and internally tangent to $\\omega_1$ at $T_1$; let $\\omega_3$ be the circle through $T_3$ and externally tangent to $\\omega_2$ at $T_2$; and let $\\omega_4$ be the circle through $T_4$ and externally tangent to $\\omega_3$ at $T_3$. A line crosses $\\omega_1$ at $P$ and $W$, $\\omega_2$ at $Q$ and $R$, $\\omega_3$ at $S$ and $T$, and $\\omega_4$ at $U$ and $V$, the order of these points along the line being $P, Q, R, S, T, U, V, W$. Prove that $PQ + TU = RS + VW$.","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2021-2","source":"RMM","year":2021,"code":"N2","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Xenia and Sergey play the following game. Xenia thinks of a positive integer $N$ not exceeding $5000$. Then she fixes $20$ distinct positive integers $a_1, a_2, \\ldots, a_{20}$ such that, for each $k = 1, 2, \\ldots, 20$, the numbers $N$ and $a_k$ are congruent modulo $k$. By a move, Sergey tells Xenia a set $S$ of positive integers not exceeding $20$, and she tells him back the set $\\{a_k : k \\in S\\}$ without spelling out which number corresponds to which index. How many moves does Sergey need to determine for sure the number Xenia thought of?","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2021-3","source":"RMM","year":2021,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"A number of $17$ workers stand in a row. Every contiguous group of at least $2$ workers is a brigade. The chief wants to assign each brigade a leader (which is a member of the brigade) so that each worker's number of assignments is divisible by $4$. Prove that the number of such ways to assign the leaders is divisible by $17$.","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2021-4","source":"RMM","year":2021,"code":"C4","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Consider an integer $n \\ge 2$ and write the numbers $1, 2, \\ldots, n$ down on a board. A move consists in erasing any two numbers $a$ and $b$, then writing down the numbers $a + b$ and $|a - b|$ on the board, and then removing repetitions (e.g., if the board contained the numbers $2, 5, 7, 8$, then one could choose the numbers $a = 5$ and $b = 7$, obtaining the board with numbers $2, 8, 12$). For all integers $n \\ge 2$, determine whether it is possible to be left with exactly two numbers on the board after a finite number of moves.","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2021-5","source":"RMM","year":2021,"code":"C5","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n$ be a positive integer. The kingdom of Zoomtopia is a convex polygon with integer sides, perimeter $6n$, and $60^\\circ$ rotational symmetry (that is, there is a point $O$ such that a $60^\\circ$ rotation about $O$ maps the polygon to itself). In light of the pandemic, the government of Zoomtopia would like to relocate its $3n^2 + 3n + 1$ citizens at $3n^2 + 3n + 1$ points in the kingdom so that every two citizens have a distance of at least $1$ for proper social distancing. Prove that this is possible. (The kingdom is assumed to contain its boundary.)","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2021-6","source":"RMM","year":2021,"code":"A6","subject":"Algebra","level":9,"country":"","format":"latex","body":"Initially, a non-constant polynomial $S(x)$ with real coefficients is written down on a board. Whenever the board contains a polynomial $P(x)$, not necessarily alone, one can write down on the board any polynomial of the form $P(C + x)$ or $C + P(x)$, where $C$ is a real constant. Moreover, if the board contains two (not necessarily distinct) polynomials $P(x)$ and $Q(x)$, one can write $P(Q(x))$ and $P(x) + Q(x)$ down on the board. No polynomial is ever erased from the board.\n\nGiven two sets of real numbers, $A = \\{a_1, a_2, \\ldots, a_n\\}$ and $B = \\{b_1, b_2, \\ldots, b_n\\}$, a polynomial $f(x)$ with real coefficients is $(A, B)$-nice if $f(A) = B$, where $f(A) = \\{f(a_i) : i = 1, 2, \\ldots, n\\}$.\n\nDetermine all polynomials $S(x)$ that can initially be written down on the board such that, for any two finite sets $A$ and $B$ of real numbers, with $|A| = |B|$, one can produce an $(A, B)$-nice polynomial in a finite number of steps.","url":"https://rmms.lbi.ro/rmm2021/index.php?id=problems_math"},{"id":"RMM-2023-1","source":"RMM","year":2023,"code":"N1","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Determine all prime numbers $p$ and all positive integers $x$ and $y$ satisfying\n\\[ x^3 + y^3 = p(xy + p). \\]","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2023-2","source":"RMM","year":2023,"code":"C2","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Fix an integer $n \\ge 3$. Let $\\mathcal{S}$ be a set of $n$ points in the plane, no three of which are collinear. Given different points $A, B, C$ in $\\mathcal{S}$, the triangle $ABC$ is nice for $AB$ if $\\operatorname{Area}(ABC) \\le \\operatorname{Area}(ABX)$ for all $X$ in $\\mathcal{S}$ different from $A$ and $B$. (Note that for a segment $AB$ there could be several nice triangles.) A triangle is beautiful if its vertices are all in $\\mathcal{S}$ and it is nice for at least two of its sides.\n\nProve that there are at least $\\frac{1}{2}(n - 1)$ beautiful triangles.","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2023-3","source":"RMM","year":2023,"code":"A3","subject":"Algebra","level":9,"country":"","format":"latex","body":"Let $n \\ge 2$ be an integer, and let $f$ be a $4n$-variable polynomial with real coefficients. Assume that, for any $2n$ points $(x_1, y_1), \\ldots, (x_{2n}, y_{2n})$ in the Cartesian plane, $f(x_1, y_1, \\ldots, x_{2n}, y_{2n}) = 0$ if and only if the points form the vertices of a regular $2n$-gon in some order, or are all equal.\n\nDetermine the smallest possible degree of $f$.\n\n(Note, for example, that the degree of the polynomial\n\\[ g(x, y) = 4x^3 y^4 + yx + x - 2 \\]\nis $7$ because $7 = 3 + 4$.)","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2023-4","source":"RMM","year":2023,"code":"G4","subject":"Geometry","level":7,"country":"","format":"latex","body":"Given an acute triangle $ABC$, let $H$ and $O$ be its orthocentre and circumcentre, respectively. Let $K$ be the midpoint of the line segment $AH$. Also let $\\ell$ be a line through $O$, and let $P$ and $Q$ be the orthogonal projections of $B$ and $C$ onto $\\ell$, respectively.\n\nProve that $KP + KQ \\ge BC$.","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2023-5","source":"RMM","year":2023,"code":"A5","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $P(x), Q(x), R(x)$ and $S(x)$ be non-constant polynomials with real coefficients such that $P(Q(x)) = R(S(x))$. Suppose that the degree of $P(x)$ is divisible by the degree of $R(x)$.\n\nProve that there is a polynomial $T(x)$ with real coefficients such that\n\\[ P(x) = R(T(x)). \\]","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2023-6","source":"RMM","year":2023,"code":"C6","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Let $r, g, b$ be non-negative integers. Let $\\Gamma$ be a connected graph on $r + g + b + 1$ vertices. The edges of $\\Gamma$ are each coloured red, green or blue. It turns out that $\\Gamma$ has\n\\begin{itemize}\n\\item a spanning tree in which exactly $r$ of the edges are red,\n\\item a spanning tree in which exactly $g$ of the edges are green and\n\\item a spanning tree in which exactly $b$ of the edges are blue.\n\\end{itemize}\nProve that $\\Gamma$ has a spanning tree in which exactly $r$ of the edges are red, exactly $g$ of the edges are green and exactly $b$ of the edges are blue.\n\n(A spanning tree of $\\Gamma$ is a graph which has the same vertices as $\\Gamma$, with edges which are also edges of $\\Gamma$, for which there is exactly one path between each pair of different vertices.)","url":"https://rmms.lbi.ro/rmm2023/index.php?id=problems_math"},{"id":"RMM-2024-1","source":"RMM","year":2024,"code":"C1","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $n$ be a positive integer. Initially, a bishop is placed in each square of the top row of a $2^n \\times 2^n$ chessboard; those bishops are numbered from $1$ to $2^n$, from left to right. A jump is a simultaneous move made by all bishops such that the following conditions are satisfied:\n\\begin{itemize}\n\\item each bishop moves diagonally, in a straight line, some number of squares, and\n\\item at the end of the jump, the bishops all stand in different squares of the same row.\n\\end{itemize}\nFind the total number of permutations $\\sigma$ of the numbers $1, 2, \\ldots, 2^n$ with the following property: There exists a sequence of jumps such that all bishops end up on the bottom row arranged in the order $\\sigma(1), \\sigma(2), \\ldots, \\sigma(2^n)$, from left to right.","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2024-2","source":"RMM","year":2024,"code":"C2","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Consider an odd prime $p$ and a positive integer $N < 50p$. Let $a_1, a_2, \\ldots, a_N$ be a list of positive integers less than $p$ such that any specific value occurs at most $\\frac{51}{100}N$ times and $a_1 + a_2 + \\cdots + a_N$ is not divisible by $p$. Prove that there exists a permutation $b_1, b_2, \\ldots, b_N$ of the $a_i$ such that, for all $k = 1, 2, \\ldots, N$, the sum $b_1 + b_2 + \\cdots + b_k$ is not divisible by $p$.","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2024-3","source":"RMM","year":2024,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Given a positive integer $n$, a set $S$ is $n$-admissible if\n\\begin{itemize}\n\\item each element of $S$ is an unordered triple of integers in $\\{1, 2, \\ldots, n\\}$,\n\\item $|S| = n - 2$, and\n\\item for each $1 \\le k \\le n - 2$ and each choice of $k$ distinct $A_1, A_2, \\ldots, A_k \\in S$,\n\\[ |A_1 \\cup A_2 \\cup \\cdots \\cup A_k| \\ge k + 2. \\]\n\\end{itemize}\nIs it true that, for all $n > 3$ and for each $n$-admissible set $S$, there exist pairwise distinct points $P_1, \\ldots, P_n$ in the plane such that the angles of the triangle $P_i P_j P_k$ are all less than $61^\\circ$ for any triple $\\{i, j, k\\}$ in $S$?","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2024-4","source":"RMM","year":2024,"code":"N4","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Fix integers $a$ and $b$ greater than $1$. For any positive integer $n$, let $r_n$ be the (non-negative) remainder that $b^n$ leaves upon division by $a^n$. Assume there exists a positive integer $N$ such that $r_n < 2^n/n$ for all integers $n \\ge N$. Prove that $a$ divides $b$.","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2024-5","source":"RMM","year":2024,"code":"G5","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $BC$ be a fixed segment in the plane, and let $A$ be a variable point in the plane not on the line $BC$. Distinct points $X$ and $Y$ are chosen on the rays $\\overrightarrow{CA}$ and $\\overrightarrow{BA}$, respectively, such that $\\angle CBX = \\angle YCB = \\angle BAC$. Assume that the tangents to the circumcircle of $ABC$ at $B$ and $C$ meet line $XY$ at $P$ and $Q$, respectively, such that the points $X, P, Y,$ and $Q$ are pairwise distinct and lie on the same side of $BC$. Let $\\Omega_1$ be the circle through $X$ and $P$ centred on $BC$. Similarly, let $\\Omega_2$ be the circle through $Y$ and $Q$ centred on $BC$. Prove that $\\Omega_1$ and $\\Omega_2$ intersect at two fixed points as $A$ varies.","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2024-6","source":"RMM","year":2024,"code":"N6","subject":"Number Theory","level":9,"country":"","format":"latex","body":"A polynomial $P$ with integer coefficients is square-free if it is not expressible in the form $P = Q^2 R$, where $Q$ and $R$ are polynomials with integer coefficients and $Q$ is not constant. For a positive integer $n$, let $\\mathcal{P}_n$ be the set of polynomials of the form\n\\[ 1 + a_1 x + a_2 x^2 + \\cdots + a_n x^n \\]\nwith $a_1, a_2, \\ldots, a_n \\in \\{0, 1\\}$. Prove that there exists an integer $N$ so that, for all integers $n \\ge N$, more than $99\\%$ of the polynomials in $\\mathcal{P}_n$ are square-free.","url":"https://rmms.lbi.ro/rmm2024/index.php?id=problems_math"},{"id":"RMM-2025-1","source":"RMM","year":2025,"code":"C1","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $n > 10$ be an integer, and let $A_1, A_2, \\ldots, A_n$ be distinct points in the plane such that the distances between the points are pairwise different. Define $f_{10}(j, k)$ to be the $10$th smallest of the distances from $A_j$ to $A_1, A_2, \\ldots, A_k$, excluding $A_j$ if $k \\ge j$. Suppose that for all $j$ and $k$ satisfying $11 \\le j \\le k \\le n$, we have $f_{10}(j, j - 1) \\ge f_{10}(k, j - 1)$. Prove that $f_{10}(j, n) \\ge \\frac{1}{2} f_{10}(n, n)$ for all $j$ in the range $1 \\le j \\le n - 1$.","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"RMM-2025-2","source":"RMM","year":2025,"code":"N2","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Consider an infinite sequence of positive integers $a_1, a_2, a_3, \\ldots$ such that $a_1 > 1$ and $(2a_n - 1)a_{n+1}$ is a square for all positive integers $n$. Is it possible for two terms of such a sequence to be equal?","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"RMM-2025-3","source":"RMM","year":2025,"code":"C3","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Fix an integer $n \\ge 3$. Determine the smallest positive integer $k$ satisfying the following condition:\n\\begin{quote}\nFor any tree $T$ with vertices $v_1, v_2, \\ldots, v_n$ and any pairwise distinct complex numbers $z_1, z_2, \\ldots, z_n$, there is a polynomial $P(X, Y)$ with complex coefficients of total degree at most $k$ such that for all $i \\ne j$ satisfying $1 \\le i, j \\le n$, we have $P(z_i, z_j) = 0$ if and only if there is an edge in $T$ joining $v_i$ to $v_j$.\n\\end{quote}\nNote, for example, that the total degree of the polynomial\n\\[ 9X^3 Y^4 + XY^5 + X^6 - 2 \\]\nis $7$ because $7 = 3 + 4$.","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"RMM-2025-4","source":"RMM","year":2025,"code":"A4","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $\\mathbb{Z}$ denote the set of integers, and let $S \\subset \\mathbb{Z}$ be the set of integers that are at least $10^{100}$. Fix a positive integer $c$. Determine all functions $f : S \\to \\mathbb{Z}$ satisfying $f(xy + c) = f(x) + f(y)$ for all $x, y \\in S$.","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"RMM-2025-5","source":"RMM","year":2025,"code":"G5","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with $AB < AC$, and let $H$ and $O$ be its orthocentre and circumcentre, respectively. Let $\\Gamma$ be the circumcircle of triangle $BOC$. Circle $\\Gamma$ intersects line $AO$ at points $O$ and $A'$, and $\\Gamma$ intersects the circle of radius $AO$ with centre $A$ at points $O$ and $F$. Prove that the circle which has diameter $AA'$, the circumcircle of triangle $AFH$, and $\\Gamma$ pass through a common point.","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"RMM-2025-6","source":"RMM","year":2025,"code":"C6","subject":"Combinatorics","level":9,"country":"","format":"latex","body":"Let $k$ and $m$ be integers greater than $1$. Consider $k$ pairwise disjoint sets $S_1, S_2, \\ldots, S_k$, each of which has exactly $m + 1$ elements: one red and $m$ blue. Let $\\mathcal{F}$ be the family of all subsets $T$ of $S_1 \\cup S_2 \\cup \\cdots \\cup S_k$ such that, for every $i$, the intersection $T \\cap S_i$ is monochromatic. Determine the largest possible number of sets in a subfamily $\\mathcal{G} \\subseteq \\mathcal{F}$ such that no two sets in $\\mathcal{G}$ are disjoint.\n\nA set is monochromatic if all of its elements have the same colour. In particular, the empty set is monochromatic.","url":"https://rmms.lbi.ro/rmm2025/index.php?id=problems_math"},{"id":"USATST-2012-1","source":"USA TST","year":2012,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"In acute triangle $ABC$, $\\angle A < \\angle B$ and $\\angle A < \\angle C$. Let $P$ be a variable point on side $BC$. Points $D$ and $E$ lie on sides $AB$ and $AC$, respectively, such that $BP = PD$ and $CP = PE$. Prove that as $P$ moves along side $BC$, the circumcircle of triangle $ADE$ passes through a fixed point other than $A$.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-2","source":"USA TST","year":2012,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Determine all functions $f : \\mathbb{R} \\to \\mathbb{R}$ such that for every pair of real numbers $x$ and $y$,\n\\[ f(x + y^2) = f(x) + |yf(y)|. \\]","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-3","source":"USA TST","year":2012,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Determine, with proof, whether or not there exist integers $a, b, c > 2010$ satisfying the equation\n\\[ a^3 + 2b^3 + 4c^3 = 6abc + 1. \\]","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-4","source":"USA TST","year":2012,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"There are 2010 students and 100 classrooms in the Olympiad High School. At the beginning, each of the students is in one of the classrooms. Each minute, as long as not everyone is in the same classroom, somebody walks from one classroom into a different classroom with at least as many students in it (prior to his move). This process will terminate in $M$ minutes. Determine the maximum value of $M$.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-5","source":"USA TST","year":2012,"code":"A5","subject":"Algebra","level":7,"country":"","format":"latex","body":"Consider (3-variable) polynomials\n\\[ P_n(x, y, z) = (x - y)^{2n}(y - z)^{2n} + (y - z)^{2n}(z - x)^{2n} + (z - x)^{2n}(x - y)^{2n} \\]\nand\n\\[ Q_n(x, y, z) = \\left[ (x - y)^{2n} + (y - z)^{2n} + (z - x)^{2n} \\right]^{2n}. \\]\nDetermine all positive integers $n$ such that the quotient $Q_n(x, y, z)/P_n(x, y, z)$ is a (3-variable) polynomial with rational coefficients.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-6","source":"USA TST","year":2012,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"In cyclic quadrilateral $ABCD$, diagonals $AC$ and $BD$ intersect at $P$. Let $E$ and $F$ be the respective feet of the perpendiculars from $P$ to lines $AB$ and $CD$. Segments $BF$ and $CE$ meet at $Q$. Prove that lines $PQ$ and $EF$ are perpendicular to each other.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-7","source":"USA TST","year":2012,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Determine all positive integers $n$, $n \\ge 2$, such that the following statement is true:\nIf $(a_1, a_2, \\ldots, a_n)$ is a sequence of positive integers with $a_1 + a_2 + \\cdots + a_n = 2n - 1$, then there is block of (at least two) consecutive terms in the sequence with their (arithmetic) mean being an integer.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2012-8","source":"USA TST","year":2012,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Find all positive integers $a, n \\ge 1$ such that for all primes $p$ dividing $a^n - 1$, there exists a positive integer $m < n$ such that $p \\mid a^m - 1$.","url":"https://web.evanchen.cc/exams/TST-IMO-2012.pdf"},{"id":"USATST-2013-1","source":"USA TST","year":2013,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"A social club has $2k + 1$ members, each of whom is fluent in the same $k$ languages. Any pair of members always talk to each other in only one language. Suppose that there were no three members such that they use only one language among them. Let $A$ be the number of three-member subsets such that the three distinct pairs among them use different languages. Find the maximum possible value of $A$.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-2","source":"USA TST","year":2013,"code":"N2","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Find all triples $(x, y, z)$ of positive integers such that $x \\le y \\le z$ and\n\\[ x^3(y^3 + z^3) = 2012(xyz + 2). \\]","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-3","source":"USA TST","year":2013,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with $\\angle BCA = 90^\\circ$, and let $D$ be the foot of the altitude from $C$. Let $X$ be a point in the interior of the segment $CD$. Let $K$ be the point on the segment $AX$ such that $BK = BC$. Similarly, let $L$ be the point on the segment $BX$ such that $AL = AC$. The circumcircle of triangle $DKL$ intersects segment $AB$ at a second point $T$ (other than $D$). Prove that $\\angle ACT = \\angle BCT$.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-4","source":"USA TST","year":2013,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $f$ be a function from positive integers to positive integers, and let $f^m$ be $f$ applied $m$ times. Suppose that for every positive integer $n$ there exists a positive integer $k$ such that $f^{2k}(n) = n + k$, and let $k_n$ be the smallest such $k$. Prove that the sequence $k_1, k_2, \\ldots$ is unbounded.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-5","source":"USA TST","year":2013,"code":"N5","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Two incongruent triangles $ABC$ and $XYZ$ are called a pair of \\emph{pals} if they satisfy the following conditions:\n(a) the two triangles have the same area;\n(b) let $M$ and $W$ be the respective midpoints of sides $BC$ and $YZ$. The two sets of lengths $\\{AB, AM, AC\\}$ and $\\{XY, XW, XZ\\}$ are identical 3-element sets of pairwise relatively prime integers.\nDetermine if there are infinitely many pairs of triangles that are pals of each other.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-6","source":"USA TST","year":2013,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle. Circle $\\omega_1$, with diameter $AC$, intersects side $BC$ at $F$ (other than $C$). Circle $\\omega_2$, with diameter $BC$, intersects side $AC$ at $E$ (other than $C$). Ray $AF$ intersects $\\omega_2$ at $K$ and $M$ with $AK < AM$. Ray $BE$ intersects $\\omega_1$ at $L$ and $N$ with $BL < BN$. Prove that lines $AB$, $ML$, $NK$ are concurrent.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-7","source":"USA TST","year":2013,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"In a table with $n$ rows and $2n$ columns where $n$ is a fixed positive integer, we write either zero or one into each cell so that each row has $n$ zeros and $n$ ones. For $1 \\le k \\le n$ and $1 \\le i \\le n$, we define $a_{k,i}$ so that the $i^{\\text{th}}$ zero in the $k^{\\text{th}}$ row is the $a_{k,i}^{\\text{th}}$ column. Let $\\mathcal{F}$ be the set of such tables with $a_{1,i} \\ge a_{2,i} \\ge \\cdots \\ge a_{n,i}$ for every $i$ with $1 \\le i \\le n$. We associate another $n \\times 2n$ table $f(C)$ from $C \\in \\mathcal{F}$ as follows: for the $k^{\\text{th}}$ row of $f(C)$, we write $n$ ones in the columns $a_{n,k} - k + 1, a_{n-1,k} - k + 2, \\ldots, a_{1,k} - k + n$ (and we write zeros in the other cells in the row).\n(a) Show that $f(C) \\in \\mathcal{F}$.\n(b) Show that $f(f(f(f(f(f(C)))))) = C$ for any $C \\in \\mathcal{F}$.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2013-8","source":"USA TST","year":2013,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Determine if there exists a (three-variable) polynomial $P(x, y, z)$ with integer coefficients satisfying the following property: a positive integer $n$ is not a perfect square if and only if there is a triple $(x, y, z)$ of positive integers such that $P(x, y, z) = n$.","url":"https://web.evanchen.cc/exams/TST-IMO-2013.pdf"},{"id":"USATST-2014-1","source":"USA TST","year":2014,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle, and let $X$ be a variable interior point on the minor arc $BC$ of its circumcircle. Let $P$ and $Q$ be the feet of the perpendiculars from $X$ to lines $CA$ and $CB$, respectively. Let $R$ be the intersection of line $PQ$ and the perpendicular from $B$ to $AC$. Let $\\ell$ be the line through $P$ parallel to $XR$. Prove that as $X$ varies along minor arc $BC$, the line $\\ell$ always passes through a fixed point.","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2014-2","source":"USA TST","year":2014,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $a_1, a_2, a_3, \\ldots$ be a sequence of integers, with the property that every consecutive group of $a_i$'s averages to a perfect square. More precisely, for all positive integers $n$ and $k$, the quantity\n\\[ \\frac{a_n + a_{n+1} + \\cdots + a_{n+k-1}}{k} \\]\nis always the square of an integer. Prove that the sequence must be constant (all $a_i$ are equal to the same perfect square).","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2014-3","source":"USA TST","year":2014,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n$ be an even positive integer, and let $G$ be an $n$-vertex (simple) graph with exactly $\\frac{n^2}{4}$ edges. An unordered pair of distinct vertices $\\{x, y\\}$ is said to be amicable if they have a common neighbor (there is a vertex $z$ such that $xz$ and $yz$ are both edges). Prove that $G$ has at least $2\\binom{n/2}{2}$ pairs of vertices which are amicable.","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2014-4","source":"USA TST","year":2014,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $n$ be a positive even integer, and let $c_1, c_2, \\ldots, c_{n-1}$ be real numbers satisfying\n\\[ \\sum_{i=1}^{n-1} |c_i - 1| < 1. \\]\nProve that\n\\[ 2x^n - c_{n-1}x^{n-1} + c_{n-2}x^{n-2} - \\cdots - c_1 x^1 + 2 \\]\nhas no real roots.","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2014-5","source":"USA TST","year":2014,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic quadrilateral, and let $E$, $F$, $G$, and $H$ be the midpoints of $AB$, $BC$, $CD$, and $DA$ respectively. Let $W$, $X$, $Y$ and $Z$ be the orthocenters of triangles $AHE$, $BEF$, $CFG$ and $DGH$, respectively. Prove that the quadrilaterals $ABCD$ and $WXYZ$ have the same area.","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2014-6","source":"USA TST","year":2014,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"For a prime $p$, a subset $S$ of residues modulo $p$ is called a sum-free multiplicative subgroup of $\\mathbb{F}_p$ if\n\\begin{itemize}\n\\item there is a nonzero residue $\\alpha$ modulo $p$ such that $S = \\{1, \\alpha^1, \\alpha^2, \\ldots\\}$ (all considered mod $p$), and\n\\item there are no $a, b, c \\in S$ (not necessarily distinct) such that $a + b \\equiv c \\pmod{p}$.\n\\end{itemize}\nProve that for every integer $N$, there is a prime $p$ and a sum-free multiplicative subgroup $S$ of $\\mathbb{F}_p$ such that $|S| \\ge N$.","url":"https://web.evanchen.cc/exams/IMO-2014-TST.pdf"},{"id":"USATST-2015-1","source":"USA TST","year":2015,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with incenter $I$ whose incircle is tangent to $\\overline{BC}$, $\\overline{CA}$, $\\overline{AB}$ at $D$, $E$, $F$, respectively. Denote by $M$ the midpoint of $\\overline{BC}$ and let $P$ be a point in the interior of $\\triangle ABC$ so that $MD = MP$ and $\\angle PAB = \\angle PAC$. Let $Q$ be a point on the incircle such that $\\angle AQD = 90^\\circ$. Prove that either $\\angle PQE = 90^\\circ$ or $\\angle PQF = 90^\\circ$.","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2015-2","source":"USA TST","year":2015,"code":"N2","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Prove that for every positive integer $n$, there exists a set $S$ of $n$ positive integers such that for any two distinct $a, b \\in S$, $a - b$ divides $a$ and $b$ but none of the other elements of $S$.","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2015-3","source":"USA TST","year":2015,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A physicist encounters 2015 atoms called usamons. Each usamon either has one electron or zero electrons, and the physicist can't tell the difference. The physicist's only tool is a diode. The physicist may connect the diode from any usamon $A$ to any other usamon $B$. (This connection is directed.) When she does so, if usamon $A$ has an electron and usamon $B$ does not, then the electron jumps from $A$ to $B$. In any other case, nothing happens. In addition, the physicist cannot tell whether an electron jumps during any given step. The physicist's goal is to isolate two usamons that she is 100% sure are currently in the same state. Is there any series of diode usage that makes this possible?","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2015-4","source":"USA TST","year":2015,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $f : \\mathbb{Q} \\to \\mathbb{Q}$ be a function such that for any $x, y \\in \\mathbb{Q}$, the number $f(x + y) - f(x) - f(y)$ is an integer. Decide whether there must exist a constant $c$ such that $f(x) - cx$ is an integer for every rational number $x$.","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2015-5","source":"USA TST","year":2015,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Fix a positive integer $n$. A tournament on $n$ vertices has all its edges colored by $\\chi$ colors, so that any two directed edges $u \\to v$ and $v \\to w$ have different colors. Over all possible tournaments on $n$ vertices, determine the minimum possible value of $\\chi$.","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2015-6","source":"USA TST","year":2015,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a non-equilateral triangle and let $M_a$, $M_b$, $M_c$ be the midpoints of the sides $BC$, $CA$, $AB$, respectively. Let $S$ be a point lying on the Euler line. Denote by $X$, $Y$, $Z$ the second intersections of $M_aS$, $M_bS$, $M_cS$ with the nine-point circle. Prove that $AX$, $BY$, $CZ$ are concurrent.","url":"https://web.evanchen.cc/exams/IMO-2015-TST.pdf"},{"id":"USATST-2016-1","source":"USA TST","year":2016,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $S = \\{1, \\ldots, n\\}$. Given a bijection $f : S \\to S$ an \\emph{orbit} of $f$ is a set of the form $\\{x, f(x), f(f(x)), \\ldots\\}$ for some $x \\in S$. We denote by $c(f)$ the number of distinct orbits of $f$. For example, if $n = 3$ and $f(1) = 2$, $f(2) = 1$, $f(3) = 3$, the two orbits are $\\{1, 2\\}$ and $\\{3\\}$, hence $c(f) = 2$.\n\nGiven $k$ bijections $f_1, \\ldots, f_k$ from $S$ to itself, prove that\n\\[ c(f_1) + \\cdots + c(f_k) \\le n(k - 1) + c(f) \\]\nwhere $f : S \\to S$ is the composed function $f_1 \\circ \\cdots \\circ f_k$.","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2016-2","source":"USA TST","year":2016,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with circumcircle $\\Omega$, and suppose the incircle of $ABC$ touches $BC$ at $D$. The angle bisector of $\\angle A$ meets $BC$ and $\\Omega$ at $K$ and $M$. The circumcircle of $\\triangle DKM$ intersects the $A$-excircle at $S_1$, $S_2$, and $\\Omega$ at $T \\ne M$. Prove that line $AT$ passes through either $S_1$ or $S_2$.","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2016-3","source":"USA TST","year":2016,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $p$ be a prime number. Let $\\mathbb{F}_p$ denote the integers modulo $p$, and let $\\mathbb{F}_p[x]$ be the set of polynomials with coefficients in $\\mathbb{F}_p$. Define $\\Psi : \\mathbb{F}_p[x] \\to \\mathbb{F}_p[x]$ by\n\\[ \\Psi\\left( \\sum_{i=0}^{n} a_i x^i \\right) = \\sum_{i=0}^{n} a_i x^{p^i}. \\]\nProve that for nonzero polynomials $F, G \\in \\mathbb{F}_p[x]$,\n\\[ \\Psi(\\gcd(F, G)) = \\gcd(\\Psi(F), \\Psi(G)). \\]","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2016-4","source":"USA TST","year":2016,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $\\sqrt{3} = 1.b_1 b_2 b_3 \\ldots_{(2)}$ be the binary representation of $\\sqrt{3}$. Prove that for any positive integer $n$, at least one of the digits $b_n, b_{n+1}, \\ldots, b_{2n}$ equals $1$.","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2016-5","source":"USA TST","year":2016,"code":"A5","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $n \\ge 4$ be an integer. Find all functions $W : \\{1, \\ldots, n\\}^2 \\to \\mathbb{R}$ such that for every partition $[n] = A \\cup B \\cup C$ into disjoint sets,\n\\[ \\sum_{a \\in A} \\sum_{b \\in B} \\sum_{c \\in C} W(a, b) W(b, c) = |A||B||C|. \\]","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2016-6","source":"USA TST","year":2016,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute scalene triangle and let $P$ be a point in its interior. Let $A_1$, $B_1$, $C_1$ be projections of $P$ onto triangle sides $BC$, $CA$, $AB$, respectively. Find the locus of points $P$ such that $AA_1$, $BB_1$, $CC_1$ are concurrent and $\\angle PAB + \\angle PBC + \\angle PCA = 90^\\circ$.","url":"https://web.evanchen.cc/exams/IMO-2016-TST.pdf"},{"id":"USATST-2017-1","source":"USA TST","year":2017,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"In a sports league, each team uses a set of at most $t$ signature colors. A set $S$ of teams is \\emph{color-identifiable} if one can assign each team in $S$ one of their signature colors, such that no team in $S$ is assigned any signature color of a different team in $S$. For all positive integers $n$ and $t$, determine the maximum integer $g(n, t)$ such that: In any sports league with exactly $n$ distinct colors present over all teams, one can always find a color-identifiable set of size at least $g(n, t)$.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2017-2","source":"USA TST","year":2017,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an acute scalene triangle with circumcenter $O$, and let $T$ be on line $BC$ such that $\\angle TAO = 90^\\circ$. The circle with diameter $\\overline{AT}$ intersects the circumcircle of $\\triangle BOC$ at two points $A_1$ and $A_2$, where $OA_1 < OA_2$. Points $B_1$, $B_2$, $C_1$, $C_2$ are defined analogously.\n\n(a) Prove that $\\overline{AA_1}$, $\\overline{BB_1}$, $\\overline{CC_1}$ are concurrent.\n\n(b) Prove that $\\overline{AA_2}$, $\\overline{BB_2}$, $\\overline{CC_2}$ are concurrent on the Euler line of triangle $ABC$.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2017-3","source":"USA TST","year":2017,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $P, Q \\in \\mathbb{R}[x]$ be relatively prime nonconstant polynomials. Show that there can be at most three real numbers $\\lambda$ such that $P + \\lambda Q$ is the square of a polynomial.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2017-4","source":"USA TST","year":2017,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"You are cheating at a trivia contest. For each question, you can peek at each of the $n > 1$ other contestant's guesses before writing your own. For each question, after all guesses are submitted, the emcee announces the correct answer. A correct guess is worth $0$ points. An incorrect guess is worth $-2$ points for other contestants, but only $-1$ point for you, because you hacked the scoring system. After announcing the correct answer, the emcee proceeds to read out the next question. Show that if you are leading by $2^{n-1}$ points at any time, then you can surely win first place.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2017-5","source":"USA TST","year":2017,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle with altitude $\\overline{AE}$. The $A$-excircle touches $\\overline{BC}$ at $D$, and intersects the circumcircle at two points $F$ and $G$. Prove that one can select points $V$ and $N$ on lines $DG$ and $DF$ such that quadrilateral $EVAN$ is a rhombus.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2017-6","source":"USA TST","year":2017,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Prove that there are infinitely many triples $(a, b, p)$ of integers, with $p$ prime and $0 < a \\le b < p$, for which $p^3$ divides $(a + b)^p - a^p - b^p$.","url":"https://web.evanchen.cc/exams/IMO-2017-TST.pdf"},{"id":"USATST-2018-1","source":"USA TST","year":2018,"code":"N1","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $n \\ge 2$ be a positive integer, and let $\\sigma(n)$ denote the sum of the positive divisors of $n$. Prove that the $n$th smallest positive integer relatively prime to $n$ is at least $\\sigma(n)$, and determine for which $n$ equality holds.","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2018-2","source":"USA TST","year":2018,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Find all functions $f : \\mathbb{Z}^2 \\to [0, 1]$ such that for any integers $x$ and $y$,\n\\[ f(x, y) = \\frac{f(x - 1, y) + f(x, y - 1)}{2}. \\]","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2018-3","source":"USA TST","year":2018,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"At a university dinner, there are $2017$ mathematicians who each order two distinct entrées, with no two mathematicians ordering the same pair of entrées. The cost of each entrée is equal to the number of mathematicians who ordered it, and the university pays for each mathematician's less expensive entrée (ties broken arbitrarily). Over all possible sets of orders, what is the maximum total amount the university could have paid?","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2018-4","source":"USA TST","year":2018,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer and let $S \\subseteq \\{0, 1\\}^n$ be a set of binary strings of length $n$. Given an odd number $x_1, \\ldots, x_{2k+1} \\in S$ of binary strings (not necessarily distinct), their \\emph{majority} is defined as the binary string $y \\in \\{0, 1\\}^n$ for which the $i$th bit of $y$ is the most common bit among the $i$th bits of $x_1, \\ldots, x_{2k+1}$. (For example, if $n = 4$ the majority of $0000, 0000, 1101, 1100, 0101$ is $0100$.)\n\nSuppose that for some positive integer $k$, $S$ has the property $P_k$ that the majority of any $2k + 1$ binary strings in $S$ (possibly with repetition) is also in $S$. Prove that $S$ has the same property $P_k$ for all positive integers $k$.","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2018-5","source":"USA TST","year":2018,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABCD$ be a convex cyclic quadrilateral which is not a kite, but whose diagonals are perpendicular and meet at $H$. Denote by $M$ and $N$ the midpoints of $\\overline{BC}$ and $\\overline{CD}$. Rays $MH$ and $NH$ meet $\\overline{AD}$ and $\\overline{AB}$ at $S$ and $T$, respectively. Prove there exists a point $E$, lying outside quadrilateral $ABCD$, such that\n\\begin{itemize}\n\\item ray $EH$ bisects both angles $\\angle BES$, $\\angle TED$, and\n\\item $\\angle BEN = \\angle MED$.\n\\end{itemize}","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2018-6","source":"USA TST","year":2018,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Alice and Bob play a game. First, Alice secretly picks a finite set $S$ of lattice points in the Cartesian plane. Then, for every line $\\ell$ in the plane which is horizontal, vertical, or has slope $+1$ or $-1$, she tells Bob the number of points of $S$ that lie on $\\ell$. Bob wins if he can then determine the set $S$.\n\nProve that if Alice picks $S$ to be of the form\n\\[ S = \\left\\{ (x, y) \\in \\mathbb{Z}^2 \\mid m \\le x^2 + y^2 \\le n \\right\\} \\]\nfor some positive integers $m$ and $n$, then Bob can win. (Bob does not know in advance that $S$ is of this form.)","url":"https://web.evanchen.cc/exams/IMO-2018-TST.pdf"},{"id":"USATST-2019-1","source":"USA TST","year":2019,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle and let $M$ and $N$ denote the midpoints of $\\overline{AB}$ and $\\overline{AC}$, respectively. Let $X$ be a point such that $\\overline{AX}$ is tangent to the circumcircle of triangle $ABC$. Denote by $\\omega_B$ the circle through $M$ and $B$ tangent to $\\overline{MX}$, and by $\\omega_C$ the circle through $N$ and $C$ tangent to $\\overline{NX}$. Show that $\\omega_B$ and $\\omega_C$ intersect on line $BC$.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2019-2","source":"USA TST","year":2019,"code":"N2","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Let $\\mathbb{Z}/n\\mathbb{Z}$ denote the set of integers considered modulo $n$ (hence $\\mathbb{Z}/n\\mathbb{Z}$ has $n$ elements). Find all positive integers $n$ for which there exists a bijective function $g : \\mathbb{Z}/n\\mathbb{Z} \\to \\mathbb{Z}/n\\mathbb{Z}$, such that the $101$ functions\n\\[ g(x), \\quad g(x) + x, \\quad g(x) + 2x, \\quad \\ldots, \\quad g(x) + 100x \\]\nare all bijections on $\\mathbb{Z}/n\\mathbb{Z}$.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2019-3","source":"USA TST","year":2019,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A snake of length $k$ is an animal which occupies an ordered $k$-tuple $(s_1, \\ldots, s_k)$ of cells in an $n \\times n$ grid of square unit cells. These cells must be pairwise distinct, and $s_i$ and $s_{i+1}$ must share a side for $i = 1, \\ldots, k - 1$. If the snake is currently occupying $(s_1, \\ldots, s_k)$ and $s$ is an unoccupied cell sharing a side with $s_1$, the snake can move to occupy $(s, s_1, \\ldots, s_{k-1})$ instead. The snake has turned around if it occupied $(s_1, s_2, \\ldots, s_k)$ at the beginning, but after a finite number of moves occupies $(s_k, s_{k-1}, \\ldots, s_1)$ instead.\n\nDetermine whether there exists an integer $n > 1$ such that one can place some snake of length at least $0.9n^2$ in an $n \\times n$ grid which can turn around.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2019-4","source":"USA TST","year":2019,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"We say a function $f : \\mathbb{Z}_{\\ge 0} \\times \\mathbb{Z}_{\\ge 0} \\to \\mathbb{Z}$ is \\emph{great} if for any nonnegative integers $m$ and $n$,\n\\[ f(m + 1, n + 1)f(m, n) - f(m + 1, n)f(m, n + 1) = 1. \\]\nIf $A = (a_0, a_1, \\ldots)$ and $B = (b_0, b_1, \\ldots)$ are two sequences of integers, we write $A \\sim B$ if there exists a great function $f$ satisfying $f(n, 0) = a_n$ and $f(0, n) = b_n$ for every nonnegative integer $n$ (in particular, $a_0 = b_0$).\n\nProve that if $A$, $B$, $C$, and $D$ are four sequences of integers satisfying $A \\sim B$, $B \\sim C$, and $C \\sim D$, then $D \\sim A$.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2019-5","source":"USA TST","year":2019,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $n$ be a positive integer. Tasty and Stacy are given a circular necklace with $3n$ sapphire beads and $3n$ turquoise beads, such that no three consecutive beads have the same color. They play a cooperative game where they alternate turns removing three consecutive beads, subject to the following conditions:\n\\begin{itemize}\n\\item Tasty must remove three consecutive beads which are turquoise, sapphire, and turquoise, in that order, on each of his turns.\n\\item Stacy must remove three consecutive beads which are sapphire, turquoise, and sapphire, in that order, on each of her turns.\n\\end{itemize}\nThey win if all the beads are removed in $2n$ turns. Prove that if they can win with Tasty going first, they can also win with Stacy going first.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2019-6","source":"USA TST","year":2019,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$, and let $D$ be a point on line $BC$ satisfying $\\angle AID = 90^\\circ$. Let the excircle of triangle $ABC$ opposite the vertex $A$ be tangent to $\\overline{BC}$ at point $A_1$. Define points $B_1$ on $\\overline{CA}$ and $C_1$ on $\\overline{AB}$ analogously, using the excircles opposite $B$ and $C$, respectively.\n\nProve that if quadrilateral $AB_1A_1C_1$ is cyclic, then $\\overline{AD}$ is tangent to the circumcircle of $\\triangle DB_1C_1$.","url":"https://web.evanchen.cc/exams/IMO-2019-TST.pdf"},{"id":"USATST-2020-1","source":"USA TST","year":2020,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Choose positive integers $b_1, b_2, \\ldots$ satisfying\n\\[ 1 = \\frac{b_1}{1^2} > \\frac{b_2}{2^2} > \\frac{b_3}{3^2} > \\frac{b_4}{4^2} > \\cdots \\]\nand let $r$ denote the largest real number satisfying $\\frac{b_n}{n^2} \\ge r$ for all positive integers $n$. What are the possible values of $r$ across all possible choices of the sequence $(b_n)$?","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2020-2","source":"USA TST","year":2020,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Two circles $\\Gamma_1$ and $\\Gamma_2$ have common external tangents $\\ell_1$ and $\\ell_2$ meeting at $T$. Suppose $\\ell_1$ touches $\\Gamma_1$ at $A$ and $\\ell_2$ touches $\\Gamma_2$ at $B$. A circle $\\Omega$ through $A$ and $B$ intersects $\\Gamma_1$ again at $C$ and $\\Gamma_2$ again at $D$, such that quadrilateral $ABCD$ is convex.\n\nSuppose lines $AC$ and $BD$ meet at point $X$, while lines $AD$ and $BC$ meet at point $Y$. Show that $T, X, Y$ are collinear.","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2020-3","source":"USA TST","year":2020,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $\\alpha \\ge 1$ be a real number. Hephaestus and Poseidon play a turn-based game on an infinite grid of unit squares. Before the game starts, Poseidon chooses a finite number of cells to be \\emph{flooded}. Hephaestus is building a \\emph{levee}, which is a subset of unit edges of the grid (called \\emph{walls}) forming a connected, non-self-intersecting path or loop.\n\nThe game then begins with Hephaestus moving first. On each of Hephaestus's turns, he adds one or more walls to the levee, as long as the total length of the levee is at most $\\alpha n$ after his $n$th turn. On each of Poseidon's turns, every cell which is adjacent to an already flooded cell and with no wall between them becomes flooded as well.\n\nHephaestus wins if the levee forms a closed loop such that all flooded cells are contained in the interior of the loop — hence stopping the flood and saving the world. For which $\\alpha$ can Hephaestus guarantee victory in a finite number of turns no matter how Poseidon chooses the initial cells to flood?","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2020-4","source":"USA TST","year":2020,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"For a finite simple graph $G$, we define $G'$ to be the graph on the same vertex set as $G$, where for any two vertices $u \\ne v$, the pair $\\{u, v\\}$ is an edge of $G'$ if and only if $u$ and $v$ have a common neighbor in $G$.\n\nProve that if $G$ is a finite simple graph which is isomorphic to $(G')'$, then $G$ is also isomorphic to $G'$.","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2020-5","source":"USA TST","year":2020,"code":"N5","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Find all integers $n \\ge 2$ for which there exists an integer $m$ and a polynomial $P(x)$ with integer coefficients satisfying the following three conditions:\n\\begin{itemize}\n\\item $m > 1$ and $\\gcd(m, n) = 1$;\n\\item the numbers $P(0), P^2(0), \\ldots, P^{m-1}(0)$ are not divisible by $n$; and\n\\item $P^m(0)$ is divisible by $n$.\n\\end{itemize}\nHere $P^k$ means $P$ applied $k$ times, so $P^1(0) = P(0)$, $P^2(0) = P(P(0))$, etc.","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2020-6","source":"USA TST","year":2020,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $P_1 P_2 \\cdots P_{100}$ be a cyclic $100$-gon, and let $P_i = P_{i+100}$ for all $i$. Define $Q_i$ as the intersection of diagonals $\\overline{P_{i-2}P_{i+1}}$ and $\\overline{P_{i-1}P_{i+2}}$ for all integers $i$.\n\nSuppose there exists a point $P$ satisfying $\\overline{PP_i} \\perp \\overline{P_{i-1}P_{i+1}}$ for all integers $i$. Prove that the points $Q_1, Q_2, \\ldots, Q_{100}$ are concyclic.","url":"https://web.evanchen.cc/exams/IMO-2020-TST.pdf"},{"id":"USATST-2021-1","source":"USA TST","year":2021,"code":"N1","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Determine all integers $s \\ge 4$ for which there exist positive integers $a$, $b$, $c$, $d$ such that $s = a + b + c + d$ and $s$ divides $abc + abd + acd + bcd$.","url":"https://web.evanchen.cc/exams/IMO-2021-TST.pdf"},{"id":"USATST-2021-2","source":"USA TST","year":2021,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Points $A, V_1, V_2, B, U_2, U_1$ lie fixed on a circle $\\Gamma$, in that order, and such that $BU_2 > AU_1 > BV_2 > AV_1$.\n\nLet $X$ be a variable point on the arc $V_1V_2$ of $\\Gamma$ not containing $A$ or $B$. Line $XA$ meets line $U_1V_1$ at $C$, while line $XB$ meets line $U_2V_2$ at $D$. Let $O$ and $\\rho$ denote the circumcenter and circumradius of $\\triangle XCD$, respectively.\n\nProve there exists a fixed point $K$ and a real number $c$, independent of $X$, for which $OK^2 - \\rho^2 = c$ always holds regardless of the choice of $X$.","url":"https://web.evanchen.cc/exams/IMO-2021-TST.pdf"},{"id":"USATST-2021-3","source":"USA TST","year":2021,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all functions $f : \\mathbb{R} \\to \\mathbb{R}$ that satisfy the inequality\n\\[ f(y) - \\left( \\frac{z - y}{z - x} f(x) + \\frac{y - x}{z - x} f(z) \\right) \\le f\\left( \\frac{x + z}{2} \\right) - \\frac{f(x) + f(z)}{2} \\]\nfor all real numbers $x < y < z$.","url":"https://web.evanchen.cc/exams/IMO-2021-TST.pdf"},{"id":"USATST-2023-1","source":"USA TST","year":2023,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"There are 2022 equally spaced points on a circular track $\\gamma$ of circumference 2022. The points are labeled $A_1, A_2, \\ldots, A_{2022}$ in some order, each label used once. Initially, Bunbun the Bunny begins at $A_1$. She hops along $\\gamma$ from $A_1$ to $A_2$, then from $A_2$ to $A_3$, until she reaches $A_{2022}$, after which she hops back to $A_1$. When hopping from $P$ to $Q$, she always hops along the shorter of the two arcs $\\widehat{PQ}$ of $\\gamma$; if $PQ$ is a diameter of $\\gamma$, she moves along either semicircle.\n\nDetermine the maximal possible sum of the lengths of the 2022 arcs which Bunbun traveled, over all possible labellings of the 2022 points.","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2023-2","source":"USA TST","year":2023,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle. Let $M$ be the midpoint of side $BC$, and let $E$ and $F$ be the feet of the altitudes from $B$ and $C$, respectively. Suppose that the common external tangents to the circumcircles of triangles $BME$ and $CMF$ intersect at a point $K$, and that $K$ lies on the circumcircle of $ABC$. Prove that line $AK$ is perpendicular to line $BC$.","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2023-3","source":"USA TST","year":2023,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Consider pairs $(f, g)$ of functions from the set of nonnegative integers to itself such that\n\\begin{itemize}\n\\item $f(0) \\ge f(1) \\ge f(2) \\ge \\cdots \\ge f(300) \\ge 0$;\n\\item $f(0) + f(1) + f(2) + \\cdots + f(300) \\le 300$;\n\\item for any 20 nonnegative integers $n_1, n_2, \\ldots, n_{20}$, not necessarily distinct, we have\n\\[ g(n_1 + n_2 + \\cdots + n_{20}) \\le f(n_1) + f(n_2) + \\cdots + f(n_{20}). \\]\n\\end{itemize}\nDetermine the maximum possible value of $g(0) + g(1) + \\cdots + g(6000)$ over all such pairs of functions.","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2023-4","source":"USA TST","year":2023,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $\\lfloor \\bullet \\rfloor$ denote the floor function. For nonnegative integers $a$ and $b$, their bitwise xor, denoted $a \\oplus b$, is the unique nonnegative integer such that\n\\[ \\left\\lfloor \\frac{a}{2^k} \\right\\rfloor + \\left\\lfloor \\frac{b}{2^k} \\right\\rfloor - \\left\\lfloor \\frac{a \\oplus b}{2^k} \\right\\rfloor \\]\nis even for every integer $k \\ge 0$. (For example, $9 \\oplus 10 = 1001_2 \\oplus 1010_2 = 0011_2 = 3$.)\n\nFind all positive integers $a$ such that for any integers $x > y \\ge 0$, we have\n\\[ x \\oplus ax \\ne y \\oplus ay. \\]","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2023-5","source":"USA TST","year":2023,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $m$ and $n$ be fixed positive integers. Tsvety and Freyja play a game on an infinite grid of unit square cells. Tsvety has secretly written a real number inside of each cell so that the sum of the numbers within every rectangle of size either $m \\times n$ or $n \\times m$ is zero. Freyja wants to learn all of these numbers.\n\nOne by one, Freyja asks Tsvety about some cell in the grid, and Tsvety truthfully reveals what number is written in it. Freyja wins if, at any point, Freyja can simultaneously deduce the number written in every cell of the entire infinite grid. (If this never occurs, Freyja has lost the game and Tsvety wins.)\n\nIn terms of $m$ and $n$, find the smallest number of questions that Freyja must ask to win, or show that no finite number of questions can suffice.","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2023-6","source":"USA TST","year":2023,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $\\mathbb{N}$ denote the set of positive integers. Fix a function $f : \\mathbb{N} \\to \\mathbb{N}$ and for any $m, n \\in \\mathbb{N}$ define\n\\[ \\Delta(m, n) = \\underbrace{f(f(\\ldots f}_{f(n) \\text{ times}}(m) \\ldots)) - \\underbrace{f(f(\\ldots f}_{f(m) \\text{ times}}(n) \\ldots)). \\]\nSuppose $\\Delta(m, n) \\ne 0$ for any distinct $m, n \\in \\mathbb{N}$. Show that $\\Delta$ is unbounded, meaning that for any constant $C$ there exist $m, n \\in \\mathbb{N}$ with $|\\Delta(m, n)| > C$.","url":"https://web.evanchen.cc/exams/IMO-2023-TST.pdf"},{"id":"USATST-2024-1","source":"USA TST","year":2024,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find the smallest constant $C > 1$ such that the following statement holds: for every integer $n \\ge 2$ and sequence of non-integer positive real numbers $a_1, a_2, \\ldots, a_n$ satisfying\n\\[ \\frac{1}{a_1} + \\frac{1}{a_2} + \\cdots + \\frac{1}{a_n} = 1, \\]\nit's possible to choose positive integers $b_i$ such that\n(i) for each $i = 1, 2, \\ldots, n$, either $b_i = \\lfloor a_i \\rfloor$ or $b_i = \\lfloor a_i \\rfloor + 1$; and\n(ii) we have\n\\[ 1 < \\frac{1}{b_1} + \\frac{1}{b_2} + \\cdots + \\frac{1}{b_n} \\le C. \\]\n(Here $\\lfloor \\bullet \\rfloor$ denotes the floor function, as usual.)","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2024-2","source":"USA TST","year":2024,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$. Let segment $AI$ intersect the incircle of triangle $ABC$ at point $D$. Suppose that line $BD$ is perpendicular to line $AC$. Let $P$ be a point such that $\\angle BPA = \\angle PAI = 90^\\circ$. Point $Q$ lies on segment $BD$ such that the circumcircle of triangle $ABQ$ is tangent to line $BI$. Point $X$ lies on line $PQ$ such that $\\angle IAX = \\angle XAC$. Prove that $\\angle AXP = 45^\\circ$.","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2024-3","source":"USA TST","year":2024,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n > k \\ge 1$ be integers and let $p$ be a prime dividing $\\binom{n}{k}$. Prove that the $k$-element subsets of $\\{1, \\ldots, n\\}$ can be split into $p$ classes of equal size, such that any two subsets with the same sum of elements belong to the same class.","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2024-4","source":"USA TST","year":2024,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Find all integers $n \\ge 2$ for which there exists a sequence of $2n$ pairwise distinct points $(P_1, \\ldots, P_n, Q_1, \\ldots, Q_n)$ in the plane satisfying the following four conditions:\n(i) no three of the $2n$ points are collinear;\n(ii) $P_iP_{i+1} \\ge 1$ for all $i = 1, 2, \\ldots, n$, where $P_{n+1} = P_1$;\n(iii) $Q_iQ_{i+1} \\ge 1$ for all $i = 1, 2, \\ldots, n$, where $Q_{n+1} = Q_1$; and\n(iv) $P_iQ_j \\le 1$ for all $i = 1, 2, \\ldots, n$ and $j = 1, 2, \\ldots, n$.","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2024-5","source":"USA TST","year":2024,"code":"N5","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Suppose $a_1 < a_2 < \\cdots < a_{2024}$ is an arithmetic sequence of positive integers, and $b_1 < b_2 < \\cdots < b_{2024}$ is a geometric sequence of positive integers. Find the maximum possible number of integers that could appear in both sequences, over all possible choices of the two sequences.","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2024-6","source":"USA TST","year":2024,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all functions $f : \\mathbb{R} \\to \\mathbb{R}$ such that for all real numbers $x$ and $y$,\n\\[ f(xf(y)) + f(y) = f(x + y) + f(xy). \\]","url":"https://web.evanchen.cc/exams/IMO-2024-TST.pdf"},{"id":"USATST-2025-1","source":"USA TST","year":2025,"code":"N1","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. Ana and Banana play a game. Banana thinks of a function $f : \\mathbb{Z} \\to \\mathbb{Z}$ and a prime number $p$. He tells Ana that $f$ is nonconstant, $p < 100$, and $f(x+p) = f(x)$ for all integers $x$. Ana's goal is to determine the value of $p$. She writes down $n$ integers $x_1, \\ldots, x_n$. After seeing this list, Banana writes down $f(x_1), \\ldots, f(x_n)$ in order. Ana wins if she can determine the value of $p$ from this information. Find the smallest value of $n$ for which Ana has a winning strategy.","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATST-2025-2","source":"USA TST","year":2025,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $a_1, a_2, \\ldots$ and $b_1, b_2, \\ldots$ be sequences of real numbers for which $a_1 > b_1$ and\n\\[ \\begin{aligned} a_{n+1} &= a_n^2 - 2b_n \\\\ b_{n+1} &= b_n^2 - 2a_n \\end{aligned} \\]\nfor all positive integers $n$. Prove that $a_1, a_2, \\ldots$ is eventually increasing (that is, there exists a positive integer $N$ for which $a_k < a_{k+1}$ for all $k > N$).","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATST-2025-3","source":"USA TST","year":2025,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $A_1A_2 \\cdots A_{2025}$ be a convex 2025-gon, and let $A_i = A_{i+2025}$ for all integers $i$. Distinct points $P$ and $Q$ lie in its interior such that $\\angle A_{i-1}A_iP = \\angle QA_iA_{i+1}$ for all $i$. Define points $P_i^j$ and $Q_i^j$ for integers $i$ and positive integers $j$ as follows:\n\\begin{itemize}\n\\item For all $i$, $P_i^1 = Q_i^1 = A_i$.\n\\item For all $i$ and $j$, $P_i^{j+1}$ and $Q_i^{j+1}$ are the circumcenters of $PP_i^jP_{i+1}^j$ and $QQ_i^jQ_{i+1}^j$, respectively.\n\\end{itemize}\nLet $\\mathcal{P}$ and $\\mathcal{Q}$ be the polygons $P_1^{2025}P_2^{2025} \\cdots P_{2025}^{2025}$ and $Q_1^{2025}Q_2^{2025} \\cdots Q_{2025}^{2025}$, respectively.\n(a) Prove that $\\mathcal{P}$ and $\\mathcal{Q}$ are cyclic.\n(b) Let $O_P$ and $O_Q$ be the circumcenters of $\\mathcal{P}$ and $\\mathcal{Q}$, respectively. Assuming that $O_P \\ne O_Q$, show that $O_PO_Q$ is parallel to $PQ$.","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATST-2025-4","source":"USA TST","year":2025,"code":"G4","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle, and let $X$, $Y$, and $Z$ be collinear points such that $AY = AZ$, $BZ = BX$, and $CX = CY$. Points $X'$, $Y'$, and $Z'$ are the reflections of $X$, $Y$, and $Z$ over $BC$, $CA$, and $AB$, respectively. Prove that if $X'Y'Z'$ is a nondegenerate triangle, then its circumcenter lies on the circumcircle of $ABC$.","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATST-2025-5","source":"USA TST","year":2025,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"A pond has 2025 lily pads arranged in a circle. Two frogs, Alice and Bob, begin on different lily pads. A frog jump is a jump which travels 2, 3, or 5 positions clockwise. Alice and Bob each make a series of frog jumps, and each frog ends on the same lily pad that it started from. Given that each lily pad is the destination of exactly one jump, prove that each frog completes exactly two laps around the pond (i.e. travels 4050 positions in total).","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATST-2025-6","source":"USA TST","year":2025,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Prove that there exists a real number $\\varepsilon > 0$ such that there are infinitely many sequences of integers $0 < a_1 < a_2 < \\ldots < a_{2025}$ satisfying\n\\[ \\gcd(a_1^2 + 1, a_2^2 + 1, \\ldots, a_{2025}^2 + 1) > a_{2025}^{1+\\varepsilon}. \\]","url":"https://web.evanchen.cc/exams/IMO-2025-TST.pdf"},{"id":"USATSTST-2011-1","source":"USA TSTST","year":2011,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all real-valued functions $f$ defined on pairs of real numbers, having the following property: for all real numbers $a, b, c$, the median of $f(a, b), f(b, c), f(c, a)$ equals the median of $a, b, c$.\n\n(The median of three real numbers, not necessarily distinct, is the number that is in the middle when the three numbers are arranged in nondecreasing order.)","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-2","source":"USA TSTST","year":2011,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Two circles $\\omega_1$ and $\\omega_2$ intersect at points $A$ and $B$. Line $\\ell$ is tangent to $\\omega_1$ at $P$ and to $\\omega_2$ at $Q$ so that $A$ is closer to $\\ell$ than $B$. Let $X$ and $Y$ be points on major arcs $PA$ (on $\\omega_1$) and $AQ$ (on $\\omega_2$), respectively, such that $AX/PX = AY/QY = c$. Extend segments $PA$ and $QA$ through $A$ to $R$ and $S$, respectively, such that $AR = AS = c \\cdot PQ$. Given that the circumcenter of triangle $ARS$ lies on line $XY$, prove that $\\angle XPA = \\angle AQY$.","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-3","source":"USA TSTST","year":2011,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Prove that there exists a real constant $c$ such that for any pair $(x, y)$ of real numbers, there exist relatively prime integers $m$ and $n$ satisfying the relation\n\\[ \\sqrt{(x - m)^2 + (y - n)^2} < c \\log(x^2 + y^2 + 2). \\]","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-4","source":"USA TSTST","year":2011,"code":"G4","subject":"Geometry","level":6,"country":"","format":"latex","body":"Acute triangle $ABC$ is inscribed in circle $\\omega$. Let $H$ and $O$ denote its orthocenter and circumcenter, respectively. Let $M$ and $N$ be the midpoints of sides $AB$ and $AC$, respectively. Rays $MH$ and $NH$ meet $\\omega$ at $P$ and $Q$, respectively. Lines $MN$ and $PQ$ meet at $R$. Prove that $OA \\perp RA$.","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-5","source":"USA TSTST","year":2011,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"At a certain orphanage, every pair of orphans are either friends or enemies. For every three of an orphan's friends, an even number of pairs of them are enemies. Prove that it's possible to assign each orphan two parents such that every pair of friends shares exactly one parent, but no pair of enemies does, and no three parents are in a love triangle (where each pair of them has a child).","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-6","source":"USA TSTST","year":2011,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $a, b, c$ be positive real numbers in the interval $[0, 1]$ with $a + b, b + c, c + a \\ge 1$, prove that\n\\[ 1 \\le (1 - a)^2 + (1 - b)^2 + (1 - c)^2 + \\frac{2\\sqrt{2}\\,abc}{\\sqrt{a^2 + b^2 + c^2}}. \\]","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-7","source":"USA TSTST","year":2011,"code":"G7","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle. Its excircles touch sides $BC$, $CA$, $AB$ at $D$, $E$, $F$, respectively. Prove that the perimeter of triangle $ABC$ is at most twice that of triangle $DEF$.","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-8","source":"USA TSTST","year":2011,"code":"A8","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $x_0, x_1, \\ldots, x_{n_0-1}$ be integers, and let $d_1, d_2, \\ldots, d_k$ be positive integers with $n_0 = d_1 > d_2 > \\cdots > d_k$ and $\\gcd(d_1, d_2, \\ldots, d_k) = 1$. For every integer $n \\ge n_0$, define\n\\[ x_n = \\left\\lfloor \\frac{x_{n-d_1} + x_{n-d_2} + \\cdots + x_{n-d_k}}{k} \\right\\rfloor. \\]\nShow that the sequence $\\{x_n\\}$ is eventually constant.","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2011-9","source":"USA TSTST","year":2011,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n$ be a positive integer. Suppose we are given $2^n + 1$ distinct sets, each containing finitely many objects. Place each set into one of two categories, the red sets and the blue sets, so that there is at least one set in each category. We define the symmetric difference of two sets as the set of objects belonging to exactly one of the two sets. Prove that there are at least $2^n$ different sets which can be obtained as the symmetric difference of a red set and a blue set.","url":"https://web.evanchen.cc/exams/TSTST-2011.pdf"},{"id":"USATSTST-2012-1","source":"USA TSTST","year":2012,"code":"N1","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Find all infinite sequences $a_1, a_2, \\ldots$ of positive integers satisfying the following properties:\n(a) $a_1 < a_2 < a_3 < \\cdots$,\n(b) there are no positive integers $i, j, k$, not necessarily distinct, such that $a_i + a_j = a_k$,\n(c) there are infinitely many $k$ such that $a_k = 2k - 1$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-2","source":"USA TSTST","year":2012,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral with $AC = BD$. Diagonals $AC$ and $BD$ meet at $P$. Let $\\omega_1$ and $O_1$ denote the circumcircle and the circumcenter of triangle $ABP$. Let $\\omega_2$ and $O_2$ denote the circumcircle and circumcenter of triangle $CDP$. Segment $BC$ meets $\\omega_1$ and $\\omega_2$ again at $S$ and $T$ (other than $B$ and $C$), respectively. Let $M$ and $N$ be the midpoints of minor arcs $\\widehat{SP}$ (not including $B$) and $\\widehat{TP}$ (not including $C$). Prove that $MN \\parallel O_1O_2$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-3","source":"USA TSTST","year":2012,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $\\mathbb{N}$ be the set of positive integers. Let $f : \\mathbb{N} \\to \\mathbb{N}$ be a function satisfying the following two conditions:\n(a) $f(m)$ and $f(n)$ are relatively prime whenever $m$ and $n$ are relatively prime.\n(b) $n \\le f(n) \\le n + 2012$ for all $n$.\nProve that for any natural number $n$ and any prime $p$, if $p$ divides $f(n)$ then $p$ divides $n$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-4","source":"USA TSTST","year":2012,"code":"G4","subject":"Geometry","level":6,"country":"","format":"latex","body":"In scalene triangle $ABC$, let the feet of the perpendiculars from $A$ to $BC$, $B$ to $CA$, $C$ to $AB$ be $A_1, B_1, C_1$, respectively. Denote by $A_2$ the intersection of lines $BC$ and $B_1C_1$. Define $B_2$ and $C_2$ analogously. Let $D, E, F$ be the respective midpoints of sides $BC, CA, AB$. Show that the perpendiculars from $D$ to $AA_2$, $E$ to $BB_2$ and $F$ to $CC_2$ are concurrent.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-5","source":"USA TSTST","year":2012,"code":"A5","subject":"Algebra","level":7,"country":"","format":"latex","body":"A rational number $x$ is given. Prove that there exists a sequence $x_0, x_1, x_2, \\ldots$ of rational numbers with the following properties:\n(a) $x_0 = x$;\n(b) for every $n \\ge 1$, either $x_n = 2x_{n-1}$ or $x_n = 2x_{n-1} + \\frac{1}{n}$;\n(c) $x_n$ is an integer for some $n$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-6","source":"USA TSTST","year":2012,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Positive real numbers $x, y, z$ satisfy $xyz + xy + yz + zx = x + y + z + 1$. Prove that\n\\[ \\frac{1}{3}\\left( \\sqrt{\\frac{1 + x^2}{1 + x}} + \\sqrt{\\frac{1 + y^2}{1 + y}} + \\sqrt{\\frac{1 + z^2}{1 + z}} \\right) \\le \\left( \\frac{x + y + z}{3} \\right)^{5/8}. \\]","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-7","source":"USA TSTST","year":2012,"code":"G7","subject":"Geometry","level":6,"country":"","format":"latex","body":"Triangle $ABC$ is inscribed in circle $\\Omega$. The interior angle bisector of angle $A$ intersects side $BC$ and $\\Omega$ at $D$ and $L$ (other than $A$), respectively. Let $M$ be the midpoint of side $BC$. The circumcircle of triangle $ADM$ intersects sides $AB$ and $AC$ again at $Q$ and $P$ (other than $A$), respectively. Let $N$ be the midpoint of segment $PQ$, and let $H$ be the foot of the perpendicular from $L$ to line $ND$. Prove that line $ML$ is tangent to the circumcircle of triangle $HMN$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-8","source":"USA TSTST","year":2012,"code":"C8","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $n$ be a positive integer. Consider a triangular array of nonnegative integers as follows:\n\\begin{align*}\n&\\text{Row } 1: && a_{0,1} \\\\\n&\\text{Row } 2: && a_{0,2} \\quad a_{1,2} \\\\\n&\\ \\vdots \\\\\n&\\text{Row } n-1: && a_{0,n-1} \\quad a_{1,n-1} \\quad \\cdots \\quad a_{n-2,n-1} \\\\\n&\\text{Row } n: && a_{0,n} \\quad a_{1,n} \\quad a_{2,n} \\quad \\cdots \\quad a_{n-1,n}.\n\\end{align*}\nCall such a triangular array stable if for every $0 \\le i < j < k \\le n$ we have\n\\[ a_{i,j} + a_{j,k} \\le a_{i,k} \\le a_{i,j} + a_{j,k} + 1. \\]\nFor $s_1, \\ldots, s_n$ any nondecreasing sequence of nonnegative integers, prove that there exists a unique stable triangular array such that the sum of all of the entries in row $k$ is equal to $s_k$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2012-9","source":"USA TSTST","year":2012,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Given a set $S$ of $n$ variables, a binary operation $\\times$ on $S$ is called simple if it satisfies $(x \\times y) \\times z = x \\times (y \\times z)$ for all $x, y, z \\in S$ and $x \\times y \\in \\{x, y\\}$ for all $x, y \\in S$. Given a simple operation $\\times$ on $S$, any string of elements in $S$ can be reduced to a single element, such as $xyz \\to x \\times (y \\times z)$. A string of variables in $S$ is called full if it contains each variable in $S$ at least once, and two strings are equivalent if they evaluate to the same variable regardless of which simple $\\times$ is chosen. For example $xxx$, $xx$, and $x$ are equivalent, but these are only full if $n = 1$. Suppose $T$ is a set of strings such that any full string is equivalent to exactly one element of $T$. Determine the number of elements of $T$.","url":"https://web.evanchen.cc/exams/TSTST-2012.pdf"},{"id":"USATSTST-2013-1","source":"USA TSTST","year":2013,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle and $D, E, F$ be the midpoints of arcs $BC, CA, AB$ on the circumcircle. Line $\\ell_a$ passes through the feet of the perpendiculars from $A$ to $DB$ and $DC$. Line $m_a$ passes through the feet of the perpendiculars from $D$ to $AB$ and $AC$. Let $A_1$ denote the intersection of lines $\\ell_a$ and $m_a$. Define points $B_1$ and $C_1$ similarly. Prove that triangles $DEF$ and $A_1B_1C_1$ are similar to each other.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-2","source":"USA TSTST","year":2013,"code":"N2","subject":"Number Theory","level":7,"country":"","format":"latex","body":"A finite sequence of integers $a_1, a_2, \\ldots, a_n$ is called regular if there exists a real number $x$ satisfying\n\\[ \\lfloor kx \\rfloor = a_k \\quad \\text{for } 1 \\le k \\le n. \\]\nGiven a regular sequence $a_1, a_2, \\ldots, a_n$, for $1 \\le k \\le n$ we say that the term $a_k$ is forced if the following condition is satisfied: the sequence\n\\[ a_1, a_2, \\ldots, a_{k-1}, b \\]\nis regular if and only if $b = a_k$. Find the maximum possible number of forced terms in a regular sequence with 1000 terms.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-3","source":"USA TSTST","year":2013,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Divide the plane into an infinite square grid by drawing all the lines $x = m$ and $y = n$ for $m, n \\in \\mathbb{Z}$. Next, if a square's upper-right corner has both coordinates even, color it black; otherwise, color it white (in this way, exactly $1/4$ of the squares are black and no two black squares are adjacent). Let $r$ and $s$ be odd integers, and let $(x, y)$ be a point in the interior of any white square such that $rx - sy$ is irrational. Shoot a laser out of this point with slope $r/s$; lasers pass through white squares and reflect off black squares. Prove that the path of this laser will form a closed loop.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-4","source":"USA TSTST","year":2013,"code":"G4","subject":"Geometry","level":6,"country":"","format":"latex","body":"Circle $\\omega$, centered at $X$, is internally tangent to circle $\\Omega$, centered at $Y$, at $T$. Let $P$ and $S$ be variable points on $\\Omega$ and $\\omega$, respectively, such that line $PS$ is tangent to $\\omega$ (at $S$). Determine the locus of $O$ -- the circumcenter of triangle $PST$.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-5","source":"USA TSTST","year":2013,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $p$ be a prime. Prove that any complete graph with $1000p$ vertices, whose edges are labelled with integers, has a cycle whose sum of labels is divisible by $p$.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-6","source":"USA TSTST","year":2013,"code":"A6","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $\\mathbb{N}$ be the set of positive integers. Find all functions $f : \\mathbb{N} \\to \\mathbb{N}$ that satisfy the equation\n\\[ f^{abc-a}(abc) + f^{abc-b}(abc) + f^{abc-c}(abc) = a + b + c \\]\nfor all $a, b, c \\ge 2$.\n(Here $f^1(n) = f(n)$ and $f^k(n) = f(f^{k-1}(n))$ for every integer $k$ greater than 1.)","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-7","source":"USA TSTST","year":2013,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"A country has $n$ cities, labelled $1, 2, 3, \\ldots, n$. It wants to build exactly $n - 1$ roads between certain pairs of cities so that every city is reachable from every other city via some sequence of roads. However, it is not permitted to put roads between pairs of cities that have labels differing by exactly 1, and it is also not permitted to put a road between cities 1 and $n$. Let $T_n$ be the total number of possible ways to build these roads.\n(a) For all odd $n$, prove that $T_n$ is divisible by $n$.\n(b) For all even $n$, prove that $T_n$ is divisible by $n/2$.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-8","source":"USA TSTST","year":2013,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Define a function $f : \\mathbb{N} \\to \\mathbb{N}$ by $f(1) = 1$, $f(n + 1) = f(n) + 2^{f(n)}$ for every positive integer $n$. Prove that $f(1), f(2), \\ldots, f(3^{2013})$ leave distinct remainders when divided by $3^{2013}$.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2013-9","source":"USA TSTST","year":2013,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $r$ be a rational number in the interval $[-1, 1]$ and let $\\theta = \\cos^{-1} r$. Call a subset $S$ of the plane good if $S$ is unchanged upon rotation by $\\theta$ around any point of $S$ (in both clockwise and counterclockwise directions). Determine all values of $r$ satisfying the following property: The midpoint of any two points in a good set also lies in the set.","url":"https://web.evanchen.cc/exams/TSTST-2013.pdf"},{"id":"USATSTST-2014-1","source":"USA TSTST","year":2014,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $\\leftarrow$ denote the left arrow key on a standard keyboard. If one opens a text editor and types the keys “ab$\\leftarrow$cd$\\leftarrow\\leftarrow$e$\\leftarrow\\leftarrow$f”, the result is “faecdb”. We say that a string $B$ is \\emph{reachable} from a string $A$ if it is possible to insert some amount of $\\leftarrow$'s into $A$, such that typing the resulting characters produces $B$. So, our example shows that “faecdb” is reachable from “abcdef”.\n\nProve that for any two strings $A$ and $B$, $A$ is reachable from $B$ if and only if $B$ is reachable from $A$.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2014-2","source":"USA TSTST","year":2014,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Consider a convex pentagon circumscribed about a circle. We name the lines that connect vertices of the pentagon with the opposite points of tangency with the circle \\emph{gergonnians}.\n\n(a) Prove that if four gergonnians are concurrent, then all five of them are concurrent.\n\n(b) Prove that if there is a triple of gergonnians that are concurrent, then you can find another triple of gergonnians that are concurrent.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2014-3","source":"USA TSTST","year":2014,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Find all polynomial functions $P(x)$ with real coefficients that satisfy\n\\[ P(x\\sqrt{2}) = P(x + \\sqrt{1 - x^2}) \\]\nfor all real $x$ with $|x| \\le 1$.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2014-4","source":"USA TSTST","year":2014,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $P(x)$ and $Q(x)$ be arbitrary polynomials with real coefficients, and let $d$ be the degree of $P(x)$. Assume that $P(x)$ is not the zero polynomial. Prove that there exist polynomials $A(x)$ and $B(x)$ with real coefficients, such that:\n\n(i) both $A$ and $B$ have degree at most $d/2$, and\n\n(ii) at most one of $A$ and $B$ is the zero polynomial, and\n\n(iii) $\\dfrac{A(x) + Q(x)B(x)}{P(x)}$ is a polynomial with real coefficients. That is, there is some polynomial $C(x)$ with real coefficients such that $A(x) + Q(x)B(x) = P(x)C(x)$.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2014-5","source":"USA TSTST","year":2014,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Find the maximum number $E$ such that the following holds: there is an edge-colored graph with 60 vertices and $E$ edges, with each edge colored either red or blue, such that in that coloring, there are no monochromatic cycles of length 3 and no monochromatic cycles of length 5.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2014-6","source":"USA TSTST","year":2014,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Suppose we have distinct positive integers $a, b, c, d$, and an odd prime $p$ not dividing any of them, and an integer $M$ such that if one considers the infinite sequence\n\\[ ca - db \\]\n\\[ ca^2 - db^2 \\]\n\\[ ca^3 - db^3 \\]\n\\[ ca^4 - db^4 \\]\n\\[ \\ldots \\]\nand looks at the highest power of $p$ that divides each of them, these powers are not all zero, and are all at most $M$. Prove that there exists some $T$ (which may depend on $a, b, c, d, p, M$) such that whenever $p$ divides an element of this sequence, the maximum power of $p$ that divides that element is exactly $p^T$.","url":"https://web.evanchen.cc/exams/TSTST-2014.pdf"},{"id":"USATSTST-2015-1","source":"USA TSTST","year":2015,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $a_1, a_2, \\ldots, a_n$ be a sequence of real numbers, and let $m$ be a fixed positive integer less than $n$. We say an index $k$ with $1 \\le k \\le n$ is \\emph{good} if there exists some $\\ell$ with $1 \\le \\ell \\le m$ such that\n\\[ a_k + a_{k+1} + \\cdots + a_{k+\\ell-1} \\ge 0, \\]\nwhere the indices are taken modulo $n$. Let $T$ be the set of all good indices. Prove that\n\\[ \\sum_{k \\in T} a_k \\ge 0. \\]","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2015-2","source":"USA TSTST","year":2015,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle. Let $K_a$, $L_a$, and $M_a$ be the respective intersections with $BC$ of the internal angle bisector, external angle bisector, and the median from $A$. The circumcircle of $AK_aL_a$ intersects $AM_a$ a second time at a point $X_a$ different from $A$. Define $X_b$ and $X_c$ analogously. Prove that the circumcenter of $X_aX_bX_c$ lies on the Euler line of $ABC$.\n\n(The Euler line of $ABC$ is the line passing through the circumcenter, centroid, and orthocenter of $ABC$.)","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2015-3","source":"USA TSTST","year":2015,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $P$ be the set of all primes, and let $M$ be a non-empty subset of $P$. Suppose that for any non-empty subset $\\{p_1, p_2, \\ldots, p_k\\}$ of $M$, all prime factors of $p_1 p_2 \\cdots p_k + 1$ are also in $M$. Prove that $M = P$.","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2015-4","source":"USA TSTST","year":2015,"code":"A4","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $x$, $y$, and $z$ be real numbers (not necessarily positive) such that $x^4 + y^4 + z^4 + xyz = 4$. Show that\n\\[ x \\le 2 \\quad \\text{and} \\quad \\sqrt{2 - x} \\ge \\frac{y + z}{2}. \\]","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2015-5","source":"USA TSTST","year":2015,"code":"N5","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Let $\\varphi(n)$ denote the number of positive integers less than $n$ that are relatively prime to $n$. Prove that there exists a positive integer $m$ for which the equation $\\varphi(n) = m$ has at least 2015 solutions in $n$.","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2015-6","source":"USA TSTST","year":2015,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A \\emph{Nim-style game} is defined as follows. Two positive integers $k$ and $n$ are specified, along with a finite set $S$ of $k$-tuples of integers (not necessarily positive). At the start of the game, the $k$-tuple $(n, 0, 0, \\ldots, 0)$ is written on the blackboard.\n\nA legal move consists of erasing the tuple $(a_1, a_2, \\ldots, a_k)$ which is written on the blackboard and replacing it with $(a_1 + b_1, a_2 + b_2, \\ldots, a_k + b_k)$, where $(b_1, b_2, \\ldots, b_k)$ is an element of the set $S$. Two players take turns making legal moves, and the first to write a negative integer loses. In the event that neither player is ever forced to write a negative integer, the game is a draw.\n\nProve that there is a choice of $k$ and $S$ with the following property: the first player has a winning strategy if $n$ is a power of 2, and otherwise the second player has a winning strategy.","url":"https://web.evanchen.cc/exams/TSTST-2015.pdf"},{"id":"USATSTST-2016-1","source":"USA TSTST","year":2016,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $A = A(x, y)$ and $B = B(x, y)$ be two-variable polynomials with real coefficients. Suppose that $A(x, y)/B(x, y)$ is a polynomial in $x$ for infinitely many values of $y$, and a polynomial in $y$ for infinitely many values of $x$. Prove that $B$ divides $A$, meaning there exists a third polynomial $C$ with real coefficients such that $A = B \\cdot C$.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2016-2","source":"USA TSTST","year":2016,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with orthocenter $H$ and circumcenter $O$. Denote by $M, N$ the midpoints of $\\overline{AH}, \\overline{BC}$. Suppose the circle $\\gamma$ with diameter $\\overline{AH}$ meets the circumcircle of $ABC$ at $G \\ne A$, and meets line $AN$ at a point $Q \\ne A$. The tangent to $\\gamma$ at $G$ meets line $OM$ at $P$. Show that the circumcircles of $\\triangle GNQ$ and $\\triangle MBC$ intersect at a point $T$ on $\\overline{PN}$.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2016-3","source":"USA TSTST","year":2016,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Decide whether or not there exists a nonconstant polynomial $Q(x)$ with integer coefficients with the following property: for every positive integer $n > 2$, the numbers\n\\[ Q(0), Q(1), Q(2), \\ldots, Q(n - 1) \\]\nproduce at most $0.499n$ distinct residues when taken modulo $n$.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2016-4","source":"USA TSTST","year":2016,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Suppose that $n$ and $k$ are positive integers such that\n\\[ 1 = \\underbrace{\\varphi(\\varphi(\\ldots \\varphi(}_{k \\text{ times}} n) \\ldots)). \\]\nProve that $n \\le 3^k$.\n\nHere $\\varphi(n)$ denotes Euler's totient function, i.e. $\\varphi(n)$ denotes the number of elements of $\\{1, \\ldots, n\\}$ which are relatively prime to $n$. In particular, $\\varphi(1) = 1$.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2016-5","source":"USA TSTST","year":2016,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"In the coordinate plane are finitely many \\emph{walls}, which are disjoint line segments, none of which are parallel to either axis. A bulldozer starts at an arbitrary point and moves in the $+x$ direction. Every time it hits a wall, it turns at a right angle to its path, away from the wall, and continues moving. (Thus the bulldozer always moves parallel to the axes.)\n\nProve that it is impossible for the bulldozer to hit both sides of every wall.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2016-6","source":"USA TSTST","year":2016,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$, and whose incircle is tangent to $\\overline{BC}, \\overline{CA}, \\overline{AB}$ at $D, E, F$, respectively. Let $K$ be the foot of the altitude from $D$ to $\\overline{EF}$. Suppose that the circumcircle of $\\triangle AIB$ meets the incircle at two distinct points $C_1$ and $C_2$, while the circumcircle of $\\triangle AIC$ meets the incircle at two distinct points $B_1$ and $B_2$. Prove that the radical axis of the circumcircles of $\\triangle BB_1B_2$ and $\\triangle CC_1C_2$ passes through the midpoint $M$ of $\\overline{DK}$.","url":"https://web.evanchen.cc/exams/TSTST-2016.pdf"},{"id":"USATSTST-2017-1","source":"USA TSTST","year":2017,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle with circumcircle $\\Gamma$, circumcenter $O$, and orthocenter $H$. Assume that $AB \\neq AC$ and $\\angle A \\neq 90^\\circ$. Let $M$ and $N$ be the midpoints of $\\overline{AB}$ and $\\overline{AC}$, respectively, and let $E$ and $F$ be the feet of the altitudes from $B$ and $C$ in $\\triangle ABC$, respectively. Let $P$ be the intersection point of line $MN$ with the tangent line to $\\Gamma$ at $A$. Let $Q$ be the intersection point, other than $A$, of $\\Gamma$ with the circumcircle of $\\triangle AEF$. Let $R$ be the intersection point of lines $AQ$ and $EF$. Prove that $\\overline{PR} \\perp \\overline{OH}$.","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2017-2","source":"USA TSTST","year":2017,"code":"C2","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Ana and Banana are playing a game. First Ana picks a word, which is defined to be a nonempty sequence of capital English letters. Then Banana picks a nonnegative integer $k$ and challenges Ana to supply a word with exactly $k$ subsequences which are equal to Ana's word. Ana wins if she is able to supply such a word, otherwise she loses. For example, if Ana picks the word \"TST\", and Banana chooses $k = 4$, then Ana can supply the word \"TSTST\" which has 4 subsequences which are equal to Ana's word. Which words can Ana pick so that she can win no matter what value of $k$ Banana chooses?","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2017-3","source":"USA TSTST","year":2017,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Consider solutions to the equation\n\\[ x^2 - cx + 1 = \\frac{f(x)}{g(x)} \\]\nwhere $f$ and $g$ are nonzero polynomials with nonnegative real coefficients. For each $c > 0$, determine the minimum possible degree of $f$, or show that no such $f$, $g$ exist.","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2017-4","source":"USA TSTST","year":2017,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Find all nonnegative integer solutions to $2^a + 3^b + 5^c = n!$.","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2017-5","source":"USA TSTST","year":2017,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$. Let $D$ be a point on side $BC$ and let $\\omega_B$ and $\\omega_C$ be the incircles of $\\triangle ABD$ and $\\triangle ACD$, respectively. Suppose that $\\omega_B$ and $\\omega_C$ are tangent to segment $BC$ at points $E$ and $F$, respectively. Let $P$ be the intersection of segment $AD$ with the line joining the centers of $\\omega_B$ and $\\omega_C$. Let $X$ be the intersection point of lines $BI$ and $CP$ and let $Y$ be the intersection point of lines $CI$ and $BP$. Prove that lines $EX$ and $FY$ meet on the incircle of $\\triangle ABC$.","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2017-6","source":"USA TSTST","year":2017,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"A sequence of positive integers $(a_n)_{n \\geq 1}$ is of \\emph{Fibonacci type} if it satisfies the recursive relation $a_{n+2} = a_{n+1} + a_n$ for all $n \\geq 1$. Is it possible to partition the set of positive integers into an infinite number of Fibonacci type sequences?","url":"https://web.evanchen.cc/exams/TSTST-2017.pdf"},{"id":"USATSTST-2018-1","source":"USA TSTST","year":2018,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"As usual, let $\\mathbb{Z}[x]$ denote the set of single-variable polynomials in $x$ with integer coefficients. Find all functions $\\theta : \\mathbb{Z}[x] \\to \\mathbb{Z}$ such that for any polynomials $p, q \\in \\mathbb{Z}[x]$,\n\\begin{itemize}\n\\item $\\theta(p + 1) = \\theta(p) + 1$, and\n\\item if $\\theta(p) \\neq 0$ then $\\theta(p)$ divides $\\theta(p \\cdot q)$.\n\\end{itemize}","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-2","source":"USA TSTST","year":2018,"code":"C2","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"In the nation of Onewaynia, certain pairs of cities are connected by one-way roads. Every road connects exactly two cities (roads are allowed to cross each other, e.g., via bridges), and each pair of cities has at most one road between them. Moreover, every city has exactly two roads leaving it and exactly two roads entering it. We wish to close half the roads of Onewaynia in such a way that every city has exactly one road leaving it and exactly one road entering it. Show that the number of ways to do so is a power of 2 greater than 1 (i.e. of the form $2^n$ for some integer $n \\geq 1$).","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-3","source":"USA TSTST","year":2018,"code":"G3","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with incenter $I$, circumcenter $O$, and circumcircle $\\Gamma$. Let $M$ be the midpoint of $\\overline{AB}$. Ray $AI$ meets $\\overline{BC}$ at $D$. Denote by $\\omega$ and $\\gamma$ the circumcircles of $\\triangle BIC$ and $\\triangle BAD$, respectively. Line $MO$ meets $\\omega$ at $X$ and $Y$, while line $CO$ meets $\\omega$ at $C$ and $Q$. Assume that $Q$ lies inside $\\triangle ABC$ and $\\angle AQM = \\angle ACB$. Consider the tangents to $\\omega$ at $X$ and $Y$ and the tangents to $\\gamma$ at $A$ and $D$. Given that $\\angle BAC \\neq 60^\\circ$, prove that these four lines are concurrent on $\\Gamma$.","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-4","source":"USA TSTST","year":2018,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"For an integer $n > 0$, denote by $\\mathcal{F}(n)$ the set of integers $m > 0$ for which the polynomial $p(x) = x^2 + mx + n$ has an integer root.\n\\begin{enumerate}\n\\item[(a)] Let $S$ denote the set of integers $n > 0$ for which $\\mathcal{F}(n)$ contains two consecutive integers. Show that $S$ is infinite but\n\\[ \\sum_{n \\in S} \\frac{1}{n} \\leq 1. \\]\n\\item[(b)] Prove that there are infinitely many positive integers $n$ such that $\\mathcal{F}(n)$ contains three consecutive integers.\n\\end{enumerate}","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-5","source":"USA TSTST","year":2018,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with circumcircle $\\omega$, and let $H$ be the foot of the altitude from $A$ to $\\overline{BC}$. Let $P$ and $Q$ be the points on $\\omega$ with $PA = PH$ and $QA = QH$. The tangent to $\\omega$ at $P$ intersects lines $AC$ and $AB$ at $E_1$ and $F_1$ respectively; the tangent to $\\omega$ at $Q$ intersects lines $AC$ and $AB$ at $E_2$ and $F_2$ respectively. Show that the circumcircles of $\\triangle AE_1F_1$ and $\\triangle AE_2F_2$ are congruent, and the line through their centers is parallel to the tangent to $\\omega$ at $A$.","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-6","source":"USA TSTST","year":2018,"code":"C6","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $S = \\{1, \\ldots, 100\\}$, and for every positive integer $n$ define\n\\[ T_n = \\{(a_1, \\ldots, a_n) \\in S^n \\mid a_1 + \\cdots + a_n \\equiv 0 \\pmod{100}\\}. \\]\nDetermine which $n$ have the following property: if we color any 75 elements of $S$ red, then at least half of the $n$-tuples in $T_n$ have an even number of coordinates with red elements.","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-7","source":"USA TSTST","year":2018,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. A frog starts on the number line at 0. Suppose it makes a finite sequence of hops, subject to two conditions:\n\\begin{itemize}\n\\item The frog visits only points in $\\{1, 2, \\ldots, 2^n - 1\\}$, each at most once.\n\\item The length of each hop is in $\\{2^0, 2^1, 2^2, \\ldots\\}$. (The hops may be either direction, left or right.)\n\\end{itemize}\nLet $S$ be the sum of the (positive) lengths of all hops in the sequence. What is the maximum possible value of $S$?","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-8","source":"USA TSTST","year":2018,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"For which positive integers $b > 2$ do there exist infinitely many positive integers $n$ such that $n^2$ divides $b^n + 1$?","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2018-9","source":"USA TSTST","year":2018,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Show that there is an absolute constant $c < 1$ with the following property: whenever $\\mathcal{P}$ is a polygon with area 1 in the plane, one can translate it by a distance of $\\frac{1}{100}$ in some direction to obtain a polygon $\\mathcal{Q}$, for which the intersection of the interiors of $\\mathcal{P}$ and $\\mathcal{Q}$ has total area at most $c$.","url":"https://web.evanchen.cc/exams/TSTST-2018.pdf"},{"id":"USATSTST-2019-1","source":"USA TSTST","year":2019,"code":"A1","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all binary operations $\\diamondsuit : \\mathbb{R}_{>0} \\times \\mathbb{R}_{>0} \\to \\mathbb{R}_{>0}$ (meaning $\\diamondsuit$ takes pairs of positive real numbers to positive real numbers) such that for any real numbers $a, b, c > 0$,\n\\begin{itemize}\n\\item the equation $a \\diamondsuit (b \\diamondsuit c) = (a \\diamondsuit b) \\cdot c$ holds; and\n\\item if $a \\geq 1$ then $a \\diamondsuit a \\geq 1$.\n\\end{itemize}","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-2","source":"USA TSTST","year":2019,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with circumcircle $\\Omega$ and orthocenter $H$. Points $D$ and $E$ lie on segments $AB$ and $AC$ respectively, such that $AD = AE$. The lines through $B$ and $C$ parallel to $\\overline{DE}$ intersect $\\Omega$ again at $P$ and $Q$, respectively. Denote by $\\omega$ the circumcircle of $\\triangle ADE$.\n\\begin{enumerate}\n\\item[(a)] Show that lines $PE$ and $QD$ meet on $\\omega$.\n\\item[(b)] Prove that if $\\omega$ passes through $H$, then lines $PD$ and $QE$ meet on $\\omega$ as well.\n\\end{enumerate}","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-3","source":"USA TSTST","year":2019,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"On an infinite square grid we place finitely many \\emph{cars}, which each occupy a single cell and face in one of the four cardinal directions. Cars may never occupy the same cell. It is given that the cell immediately in front of each car is empty, and moreover no two cars face towards each other (no right-facing car is to the left of a left-facing car within a row, etc.). In a \\emph{move}, one chooses a car and shifts it one cell forward to a vacant cell. Prove that there exists an infinite sequence of valid moves using each car infinitely many times.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-4","source":"USA TSTST","year":2019,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Consider coins with positive real denominations not exceeding 1. Find the smallest $C > 0$ such that the following holds: if we are given any 100 such coins with total value 50, then we can always split them into two stacks of 50 coins each such that the absolute difference between the total values of the two stacks is at most $C$.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-5","source":"USA TSTST","year":2019,"code":"G5","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with orthocenter $H$ and circumcircle $\\Gamma$. A line through $H$ intersects segments $AB$ and $AC$ at $E$ and $F$, respectively. Let $K$ be the circumcenter of $\\triangle AEF$, and suppose line $AK$ intersects $\\Gamma$ again at a point $D$. Prove that line $HK$ and the line through $D$ perpendicular to $\\overline{BC}$ meet on $\\Gamma$.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-6","source":"USA TSTST","year":2019,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Suppose $P$ is a polynomial with integer coefficients such that for every positive integer $n$, the sum of the decimal digits of $|P(n)|$ is not a Fibonacci number. Must $P$ be constant? (A \\emph{Fibonacci number} is an element of the sequence $F_0, F_1, \\ldots$ defined recursively by $F_0 = 0$, $F_1 = 1$, and $F_{k+2} = F_{k+1} + F_k$ for $k \\geq 0$.)","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-7","source":"USA TSTST","year":2019,"code":"N7","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $f : \\mathbb{Z} \\to \\{1, 2, \\ldots, 10^{100}\\}$ be a function satisfying\n\\[ \\gcd(f(x), f(y)) = \\gcd(f(x), x - y) \\]\nfor all integers $x$ and $y$. Show that there exist positive integers $m$ and $n$ such that $f(x) = \\gcd(m + x, n)$ for all integers $x$.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-8","source":"USA TSTST","year":2019,"code":"C8","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $\\mathcal{S}$ be a set of 16 points in the plane, no three collinear. Let $\\chi(\\mathcal{S})$ denote the number of ways to draw 8 line segments with endpoints in $\\mathcal{S}$, such that no two drawn segments intersect, even at endpoints. Find the smallest possible value of $\\chi(\\mathcal{S})$ across all such $\\mathcal{S}$.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2019-9","source":"USA TSTST","year":2019,"code":"G9","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a triangle with incenter $I$. Points $K$ and $L$ are chosen on segment $BC$ such that the incircles of $\\triangle ABK$ and $\\triangle ABL$ are tangent at $P$, and the incircles of $\\triangle ACK$ and $\\triangle ACL$ are tangent at $Q$. Prove that $IP = IQ$.","url":"https://web.evanchen.cc/exams/TSTST-2019.pdf"},{"id":"USATSTST-2020-1","source":"USA TSTST","year":2020,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $a$, $b$, $c$ be fixed positive integers. There are $a + b + c$ ducks sitting in a circle, one behind the other. Each duck picks either rock, paper, or scissors, with $a$ ducks picking rock, $b$ ducks picking paper, and $c$ ducks picking scissors.\n\nA move consists of an operation of one of the following three forms:\n\\begin{itemize}\n\\item If a duck picking rock sits behind a duck picking scissors, they switch places.\n\\item If a duck picking paper sits behind a duck picking rock, they switch places.\n\\item If a duck picking scissors sits behind a duck picking paper, they switch places.\n\\end{itemize}\nDetermine, in terms of $a$, $b$, and $c$, the maximum number of moves which could take place, over all possible initial configurations.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-2","source":"USA TSTST","year":2020,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with incenter $I$. The incircle of $ABC$ touches $\\overline{BC}$, $\\overline{CA}$, $\\overline{AB}$ at points $D$, $E$, $F$, respectively. Let $P$ be the foot of the altitude from $D$ to $\\overline{EF}$, and let $M$ be the midpoint of $\\overline{BC}$. The rays $AP$ and $IP$ intersect the circumcircle of triangle $ABC$ again at points $G$ and $Q$, respectively. Show that the incenter of triangle $GQM$ coincides with $D$.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-3","source":"USA TSTST","year":2020,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"We say a nondegenerate triangle whose angles have measures $\\theta_1$, $\\theta_2$, $\\theta_3$ is \\emph{quirky} if there exist integers $r_1$, $r_2$, $r_3$, not all zero, such that\n\\[ r_1\\theta_1 + r_2\\theta_2 + r_3\\theta_3 = 0. \\]\nFind all integers $n \\ge 3$ for which a triangle with side lengths $n - 1$, $n$, $n + 1$ is quirky.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-4","source":"USA TSTST","year":2020,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Find all pairs of positive integers $(a, b)$ satisfying the following conditions:\n\\begin{enumerate}\n\\item[(i)] $a$ divides $b^4 + 1$,\n\\item[(ii)] $b$ divides $a^4 + 1$,\n\\item[(iii)] $\\lfloor \\sqrt{a} \\rfloor = \\lfloor \\sqrt{b} \\rfloor$.\n\\end{enumerate}","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-5","source":"USA TSTST","year":2020,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $\\mathbb{N}^2$ denote the set of ordered pairs of positive integers. A finite subset $S$ of $\\mathbb{N}^2$ is \\emph{stable} if whenever $(x, y)$ is in $S$, then so are all points $(x', y')$ of $\\mathbb{N}^2$ with both $x' \\le x$ and $y' \\le y$.\n\nProve that if $S$ is a stable set, then among all stable subsets of $S$ (including the empty set and $S$ itself), at least half of them have an even number of elements.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-6","source":"USA TSTST","year":2020,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $A$, $B$, $C$, $D$ be four points such that no three are collinear and $D$ is not the orthocenter of triangle $ABC$. Let $P$, $Q$, $R$ be the orthocenters of $\\triangle BCD$, $\\triangle CAD$, $\\triangle ABD$, respectively. Suppose that lines $AP$, $BQ$, $CR$ are pairwise distinct and are concurrent. Show that the four points $A$, $B$, $C$, $D$ lie on a circle.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-7","source":"USA TSTST","year":2020,"code":"A7","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all nonconstant polynomials $P(z)$ with complex coefficients for which all complex roots of the polynomials $P(z)$ and $P(z) - 1$ have absolute value $1$.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-8","source":"USA TSTST","year":2020,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"For every positive integer $N$, let $\\sigma(N)$ denote the sum of the positive integer divisors of $N$. Find all integers $m \\ge n \\ge 2$ satisfying\n\\[ \\frac{\\sigma(m) - 1}{m - 1} = \\frac{\\sigma(n) - 1}{n - 1} = \\frac{\\sigma(mn) - 1}{mn - 1}. \\]","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2020-9","source":"USA TSTST","year":2020,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Ten million fireflies are glowing in $\\mathbb{R}^3$ at midnight. Some of the fireflies are friends, and friendship is always mutual. Every second, one firefly moves to a new position so that its distance from each one of its friends is the same as it was before moving. This is the only way that the fireflies ever change their positions. No two fireflies may ever occupy the same point.\n\nInitially, no two fireflies, friends or not, are more than a meter away. Following some finite number of seconds, all fireflies find themselves at least ten million meters away from their original positions. Given this information, find the greatest possible number of friendships between the fireflies.","url":"https://web.evanchen.cc/exams/TSTST-2020.pdf"},{"id":"USATSTST-2021-1","source":"USA TSTST","year":2021,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral inscribed in a circle with center $O$. Points $X$ and $Y$ lie on sides $AB$ and $CD$, respectively. Suppose the circumcircles of $ADX$ and $BCY$ meet line $XY$ again at $P$ and $Q$, respectively. Show that $OP = OQ$.","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-2","source":"USA TSTST","year":2021,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $a_1 < a_2 < a_3 < a_4 < \\cdots$ be an infinite sequence of real numbers in the interval $(0, 1)$. Show that there exists a number that occurs exactly once in the sequence\n\\[ \\frac{a_1}{1}, \\ \\frac{a_2}{2}, \\ \\frac{a_3}{3}, \\ \\frac{a_4}{4}, \\ \\ldots. \\]","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-3","source":"USA TSTST","year":2021,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Find all positive integers $k > 1$ for which there exists a positive integer $n$ such that $\\binom{n}{k}$ is divisible by $n$, and $\\binom{n}{m}$ is not divisible by $n$ for $2 \\le m < k$.","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-4","source":"USA TSTST","year":2021,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $a$ and $b$ be positive integers. Suppose that there are infinitely many pairs of positive integers $(m, n)$ for which $m^2 + an + b$ and $n^2 + am + b$ are both perfect squares. Prove that $a$ divides $2b$.","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-5","source":"USA TSTST","year":2021,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $T$ be a tree on $n$ vertices with exactly $k$ leaves. Suppose that there exists a subset of at least $\\frac{n+k-1}{2}$ vertices of $T$, no two of which are adjacent. Show that the longest path in $T$ contains an even number of edges. (A tree is a connected graph with no cycles. A leaf is a vertex of degree $1$.)","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-6","source":"USA TSTST","year":2021,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Triangles $ABC$ and $DEF$ share circumcircle $\\Omega$ and incircle $\\omega$ so that points $A$, $F$, $B$, $D$, $C$, and $E$ occur in this order along $\\Omega$. Let $\\Delta_A$ be the triangle formed by lines $AB$, $AC$, and $EF$, and define triangles $\\Delta_B, \\Delta_C, \\ldots, \\Delta_F$ similarly. Furthermore, let $\\Omega_A$ and $\\omega_A$ be the circumcircle and incircle of triangle $\\Delta_A$, respectively, and define circles $\\Omega_B, \\omega_B, \\ldots, \\Omega_F, \\omega_F$ similarly.\n\\begin{enumerate}\n\\item[(a)] Prove that the two common external tangents to circles $\\Omega_A$ and $\\Omega_D$ and the two common external tangents to circles $\\omega_A$ and $\\omega_D$ are either concurrent or pairwise parallel.\n\\item[(b)] Suppose that these four lines meet at point $T_A$, and define points $T_B$ and $T_C$ similarly. Prove that points $T_A$, $T_B$, and $T_C$ are collinear.\n\\end{enumerate}","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-7","source":"USA TSTST","year":2021,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $M$ be a finite set of lattice points and $n$ be a positive integer. A \\emph{mine-avoiding path} is a path of lattice points with length $n$, beginning at $(0, 0)$ and ending at a point on the line $x + y = n$, that does not contain any point in $M$. Prove that if there exists a mine-avoiding path, then there exist at least $2^{n-|M|}$ mine-avoiding paths. (A lattice point is a point $(x, y)$ where $x$ and $y$ are integers. A path of lattice points with length $n$ is a sequence of lattice points $P_0, P_1, \\ldots, P_n$ in which any two adjacent points in the sequence have distance $1$ from each other.)","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-8","source":"USA TSTST","year":2021,"code":"G8","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle. Points $A_1$, $B_1$ and $C_1$ are chosen on segments $BC$, $CA$, and $AB$, respectively, such that $\\triangle A_1B_1C_1$ and $\\triangle ABC$ are similar. Let $A_2$ be the unique point on line $B_1C_1$ such that $AA_2 = A_1A_2$. Points $B_2$ and $C_2$ are defined similarly. Prove that $\\triangle A_2B_2C_2$ and $\\triangle ABC$ are similar.","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2021-9","source":"USA TSTST","year":2021,"code":"N9","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Let $q = p^r$ for a prime number $p$ and positive integer $r$. Let $\\zeta = e^{\\frac{2\\pi i}{q}}$. Find the least positive integer $n$ such that\n\\[ \\sum_{\\substack{1 \\le k \\le q \\\\ \\gcd(k,p)=1}} \\frac{1}{(1 - \\zeta^k)^n} \\]\nis not an integer. (The sum is over all $1 \\le k \\le q$ with $p$ not dividing $k$.)","url":"https://web.evanchen.cc/exams/TSTST-2021.pdf"},{"id":"USATSTST-2022-1","source":"USA TSTST","year":2022,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. Find the smallest positive integer $k$ such that for any set $S$ of $n$ points in the interior of the unit square, there exists a set of $k$ rectangles such that the following hold:\n\\begin{itemize}\n\\item The sides of each rectangle are parallel to the sides of the unit square.\n\\item Each point in $S$ is \\emph{not} in the interior of any rectangle.\n\\item Each point in the interior of the unit square but \\emph{not} in $S$ is in the interior of at least one of the $k$ rectangles.\n\\end{itemize}\n(The interior of a polygon does not contain its boundary.)","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-2","source":"USA TSTST","year":2022,"code":"G2","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a triangle. Let $\\theta$ be a fixed angle for which\n\\[ \\theta < \\frac{1}{2} \\min(\\angle A, \\angle B, \\angle C). \\]\nPoints $S_A$ and $T_A$ lie on segment $BC$ such that $\\angle BAS_A = \\angle T_AAC = \\theta$. Let $P_A$ and $Q_A$ be the feet from $B$ and $C$ to $\\overline{AS_A}$ and $\\overline{AT_A}$ respectively. Then $\\ell_A$ is defined as the perpendicular bisector of $\\overline{P_AQ_A}$.\n\nDefine $\\ell_B$ and $\\ell_C$ analogously by repeating this construction two more times (using the same value of $\\theta$). Prove that $\\ell_A$, $\\ell_B$, and $\\ell_C$ are concurrent or all parallel.","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-3","source":"USA TSTST","year":2022,"code":"N3","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Determine all positive integers $N$ for which there exists a strictly increasing sequence of positive integers $s_0 < s_1 < s_2 < \\cdots$ satisfying the following properties:\n\\begin{itemize}\n\\item the sequence $s_1 - s_0, \\ s_2 - s_1, \\ s_3 - s_2, \\ldots$ is periodic; and\n\\item $s_{s_n} - s_{s_{n-1}} \\le N < s_{1+s_n} - s_{s_{n-1}}$ for all positive integers $n$.\n\\end{itemize}","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-4","source":"USA TSTST","year":2022,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Let $\\mathbb{N}$ denote the set of positive integers. A function $f : \\mathbb{N} \\to \\mathbb{N}$ has the property that for all positive integers $m$ and $n$, exactly one of the $f(n)$ numbers\n\\[ f(m + 1), f(m + 2), \\ldots, f(m + f(n)) \\]\nis divisible by $n$. Prove that $f(n) = n$ for infinitely many positive integers $n$.","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-5","source":"USA TSTST","year":2022,"code":"C5","subject":"Combinatorics","level":7,"country":"","format":"latex","body":"Let $A_1, \\ldots, A_{2022}$ be the vertices of a regular $2022$-gon in the plane. Alice and Bob play a game. Alice secretly chooses a line and colors all points in the plane on one side of the line blue, and all points on the other side of the line red. Points on the line are colored blue, so every point in the plane is either red or blue. (Bob cannot see the colors of the points.)\n\nIn each round, Bob chooses a point in the plane (not necessarily among $A_1, \\ldots, A_{2022}$) and Alice responds truthfully with the color of that point. What is the smallest number $Q$ for which Bob has a strategy to always determine the colors of points $A_1, \\ldots, A_{2022}$ in $Q$ rounds?","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-6","source":"USA TSTST","year":2022,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $O$ and $H$ be the circumcenter and orthocenter, respectively, of an acute scalene triangle $ABC$. The perpendicular bisector of $\\overline{AH}$ intersects $\\overline{AB}$ and $\\overline{AC}$ at $X_A$ and $Y_A$ respectively. Let $K_A$ denote the intersection of the circumcircles of triangles $OX_AY_A$ and $BOC$ other than $O$.\n\nDefine $K_B$ and $K_C$ analogously by repeating this construction two more times. Prove that $K_A$, $K_B$, $K_C$, and $O$ are concyclic.","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-7","source":"USA TSTST","year":2022,"code":"G7","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABCD$ be a parallelogram. Point $E$ lies on segment $CD$ such that\n\\[ 2\\angle AEB = \\angle ADB + \\angle ACB, \\]\nand point $F$ lies on segment $BC$ such that\n\\[ 2\\angle DFA = \\angle DCA + \\angle DBA. \\]\nLet $K$ be the circumcenter of triangle $ABD$. Prove that $KE = KF$.","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-8","source":"USA TSTST","year":2022,"code":"N8","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Let $\\mathbb{N}$ denote the set of positive integers. Find all functions $f : \\mathbb{N} \\to \\mathbb{Z}$ such that\n\\[ \\left\\lfloor \\frac{f(mn)}{n} \\right\\rfloor = f(m) \\]\nfor all positive integers $m$, $n$.","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2022-9","source":"USA TSTST","year":2022,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $k > 1$ be a fixed positive integer. Prove that if $n$ is a sufficiently large positive integer, there exists a sequence of integers with the following properties:\n\\begin{itemize}\n\\item Each element of the sequence is between $1$ and $n$, inclusive.\n\\item For any two different contiguous subsequences of the sequence with length between $2$ and $k$ inclusive, the multisets of values in those two subsequences is not the same.\n\\item The sequence has length at least $0.499n^2$.\n\\end{itemize}","url":"https://web.evanchen.cc/exams/TSTST-2022.pdf"},{"id":"USATSTST-2023-1","source":"USA TSTST","year":2023,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle with centroid $G$. Points $R$ and $S$ are chosen on rays $GB$ and $GC$, respectively, such that\n\\[\n\\angle ABS = \\angle ACR = 180^\\circ - \\angle BGC.\n\\]\nProve that $\\angle RAS + \\angle BAC = \\angle BGC$.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-2","source":"USA TSTST","year":2023,"code":"A2","subject":"Algebra","level":7,"country":"","format":"latex","body":"Let $n \\ge m \\ge 1$ be integers. Prove that\n\\[\n\\sum_{k=m}^{n} \\left( \\frac{1}{k^2} + \\frac{1}{k^3} \\right) \\ge m \\cdot \\left( \\sum_{k=m}^{n} \\frac{1}{k^2} \\right)^2.\n\\]","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-3","source":"USA TSTST","year":2023,"code":"C3","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Find all positive integers $n$ for which it is possible to color some cells of an infinite grid of unit squares red, such that each rectangle consisting of exactly $n$ cells (and whose edges lie along the lines of the grid) contains an odd number of red cells.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-4","source":"USA TSTST","year":2023,"code":"C4","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n \\ge 3$ be an integer and let $K_n$ be the complete graph on $n$ vertices. Each edge of $K_n$ is colored either red, green, or blue. Let $A$ denote the number of triangles in $K_n$ with all edges of the same color, and let $B$ denote the number of triangles in $K_n$ with all edges of different colors. Prove that\n\\[\nB \\le 2A + \\frac{n(n-1)}{3}.\n\\]\n(The \\emph{complete graph} on $n$ vertices is the graph on $n$ vertices with $\\binom{n}{2}$ edges, with exactly one edge joining every pair of vertices. A \\emph{triangle} consists of the set of $\\binom{3}{2} = 3$ edges between 3 of these $n$ vertices.)","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-5","source":"USA TSTST","year":2023,"code":"A5","subject":"Algebra","level":7,"country":"","format":"latex","body":"Suppose $a$, $b$, and $c$ are three complex numbers with product $1$. Assume that none of $a$, $b$, and $c$ are real or have absolute value $1$. Define\n\\[\np = (a + b + c) + \\left( \\frac{1}{a} + \\frac{1}{b} + \\frac{1}{c} \\right) \\quad \\text{and} \\quad q = \\frac{a}{b} + \\frac{b}{c} + \\frac{c}{a}.\n\\]\nGiven that both $p$ and $q$ are real numbers, find all possible values of the ordered pair $(p, q)$.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-6","source":"USA TSTST","year":2023,"code":"G6","subject":"Geometry","level":8,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle and let $P$ and $Q$ be two distinct points in its interior. Suppose that the angle bisectors of $\\angle PAQ$, $\\angle PBQ$, and $\\angle PCQ$ are the altitudes of triangle $ABC$. Prove that the midpoint of $\\overline{PQ}$ lies on the Euler line of $ABC$.\n(The Euler line is the line through the circumcenter and orthocenter of a triangle.)","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-7","source":"USA TSTST","year":2023,"code":"C7","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"The Bank of Pittsburgh issues coins that have a heads side and a tails side. Vera has a row of $2023$ such coins alternately tails-up and heads-up, with the leftmost coin tails-up.\nIn a \\emph{move}, Vera may flip over one of the coins in the row, subject to the following rules:\n\\begin{itemize}\n\\item On the first move, Vera may flip over any of the $2023$ coins.\n\\item On all subsequent moves, Vera may only flip over a coin adjacent to the coin she flipped on the previous move. (We do not consider a coin to be adjacent to itself.)\n\\end{itemize}\nDetermine the smallest possible number of moves Vera can make to reach a state in which every coin is heads-up.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-8","source":"USA TSTST","year":2023,"code":"G8","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be an equilateral triangle with side length $1$. Points $A_1$ and $A_2$ are chosen on side $BC$, points $B_1$ and $B_2$ are chosen on side $CA$, and points $C_1$ and $C_2$ are chosen on side $AB$ such that $BA_1 < BA_2$, $CB_1 < CB_2$, and $AC_1 < AC_2$.\nSuppose that the three line segments $B_1C_2$, $C_1A_2$, and $A_1B_2$ are concurrent, and the perimeters of triangles $AB_2C_1$, $BC_2A_1$, and $CA_2B_1$ are all equal. Find all possible values of this common perimeter.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2023-9","source":"USA TSTST","year":2023,"code":"N9","subject":"Number Theory","level":8,"country":"","format":"latex","body":"For every integer $m \\ge 1$, let $\\mathbb{Z}/m\\mathbb{Z}$ denote the set of integers modulo $m$. Let $p$ be a fixed prime and let $a \\ge 2$ and $e \\ge 1$ be fixed integers. Given a function $f : \\mathbb{Z}/a\\mathbb{Z} \\to \\mathbb{Z}/p^e\\mathbb{Z}$ and an integer $k \\ge 0$, the $k$th finite difference, denoted $\\Delta^k f$, is the function from $\\mathbb{Z}/a\\mathbb{Z}$ to $\\mathbb{Z}/p^e\\mathbb{Z}$ defined recursively by\n\\[\n\\Delta^0 f(n) = f(n)\n\\]\n\\[\n\\Delta^k f(n) = \\Delta^{k-1} f(n+1) - \\Delta^{k-1} f(n) \\quad \\text{for } k = 1, 2, \\ldots.\n\\]\nDetermine the number of functions $f$ such that there exists some $k \\ge 1$ for which $\\Delta^k f = f$.","url":"https://web.evanchen.cc/exams/TSTST-2023.pdf"},{"id":"USATSTST-2024-1","source":"USA TSTST","year":2024,"code":"C1","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"For every ordered pair of integers $(i, j)$, not necessarily positive, we wish to select a point $P_{i,j}$ in the Cartesian plane whose coordinates lie inside the unit square defined by\n\\[\ni < x < i + 1, \\quad j < y < j + 1.\n\\]\nFind all real numbers $c > 0$ for which it's possible to choose these points such that for all integers $i$ and $j$, the (possibly concave or degenerate) quadrilateral $P_{i,j}P_{i+1,j}P_{i+1,j+1}P_{i,j+1}$ has perimeter strictly less than $c$.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-2","source":"USA TSTST","year":2024,"code":"N2","subject":"Number Theory","level":7,"country":"","format":"latex","body":"Let $p$ be an odd prime number. Suppose $P$ and $Q$ are polynomials with integer coefficients such that $P(0) = Q(0) = 1$, there is no nonconstant polynomial dividing both $P$ and $Q$, and\n\\[\n1 + \\cfrac{x}{1 + \\cfrac{2x}{1 + \\cfrac{\\ddots}{1 + (p-1)x}}} = \\frac{P(x)}{Q(x)}.\n\\]\nShow that all coefficients of $P$ except for the constant coefficient are divisible by $p$, and all coefficients of $Q$ are \\emph{not} divisible by $p$.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-3","source":"USA TSTST","year":2024,"code":"A3","subject":"Algebra","level":8,"country":"","format":"latex","body":"Let $A = \\{a_1, \\ldots, a_{2024}\\}$ be a set of $2024$ pairwise distinct real numbers. Assume that there exist positive integers $b_1, b_2, \\ldots, b_{2024}$ such that\n\\[\na_1 b_1 + a_2 b_2 + \\cdots + a_{2024} b_{2024} = 0.\n\\]\nProve that one can choose $a_{2025}, a_{2026}, a_{2027}, \\ldots$ such that $a_k \\in A$ for all $k \\ge 2025$ and, for every positive integer $d$, there exist infinitely many positive integers $n$ satisfying\n\\[\n\\sum_{k=1}^{n} a_k k^d = 0.\n\\]","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-4","source":"USA TSTST","year":2024,"code":"G4","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral inscribed in a circle with center $O$ and $E$ be the intersection of segments $AC$ and $BD$. Let $\\omega_1$ be the circumcircle of $ADE$ and $\\omega_2$ be the circumcircle of $BCE$. The tangent to $\\omega_1$ at $A$ and the tangent to $\\omega_2$ at $C$ meet at $P$. The tangent to $\\omega_1$ at $D$ and the tangent to $\\omega_2$ at $B$ meet at $Q$. Show that $OP = OQ$.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-5","source":"USA TSTST","year":2024,"code":"N5","subject":"Number Theory","level":7,"country":"","format":"latex","body":"For a positive integer $k$, let $s(k)$ denote the number of $1$s in the binary representation of $k$. Prove that for any positive integer $n$,\n\\[\n\\sum_{i=1}^{n} (-1)^{s(3i)} > 0.\n\\]","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-6","source":"USA TSTST","year":2024,"code":"N6","subject":"Number Theory","level":8,"country":"","format":"latex","body":"Determine whether there exists a function $f : \\mathbb{Z}_{>0} \\to \\mathbb{Z}_{>0}$ such that for all positive integers $m$ and $n$,\n\\[\nf(m + nf(m)) = f(n)^m + 2024! \\cdot m.\n\\]","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-7","source":"USA TSTST","year":2024,"code":"A7","subject":"Algebra","level":6,"country":"","format":"latex","body":"An infinite sequence $a_1, a_2, a_3, \\ldots$ of real numbers satisfies\n\\[\na_{2n-1} + a_{2n} > a_{2n+1} + a_{2n+2} \\quad \\text{and} \\quad a_{2n} + a_{2n+1} < a_{2n+2} + a_{2n+3}\n\\]\nfor every positive integer $n$. Prove that there exists a real number $C$ such that $a_n a_{n+1} < C$ for every positive integer $n$.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-8","source":"USA TSTST","year":2024,"code":"G8","subject":"Geometry","level":7,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle, and let $D$ be a point on side $BC$ satisfying $\\angle BAD = \\angle DAC$. Suppose that $X$ and $Y$ are points inside $ABC$ such that triangles $ABX$ and $ACY$ are similar and quadrilaterals $ACDX$ and $ABDY$ are cyclic. Let lines $BX$ and $CY$ meet at $S$ and lines $BY$ and $CX$ meet at $T$. Prove that lines $DS$ and $AT$ are parallel.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"USATSTST-2024-9","source":"USA TSTST","year":2024,"code":"C9","subject":"Combinatorics","level":8,"country":"","format":"latex","body":"Let $n \\ge 2$ be a fixed integer. The cells of an $n \\times n$ table are filled with the integers from $1$ to $n^2$ with each number appearing exactly once. Let $N$ be the number of unordered quadruples of cells on this board which form an axis-aligned rectangle, with the two smaller integers being on opposite vertices of this rectangle. Find the largest possible value of $N$.","url":"https://web.evanchen.cc/exams/TSTST-2024.pdf"},{"id":"APMO-A1","source":"APMO","year":null,"code":"A1","subject":"Algebra","level":3,"country":"","format":"latex","body":"Let $n$ be a positive integer. Find the largest nonnegative real number $f(n)$ (depending on $n$) with the following property: whenever $a_{1}, a_{2}, \\ldots, a_{n}$ are real numbers such that $a_{1}+a_{2}+\\cdots+a_{n}$ is an integer, there exists some $i$ such that $\\left|a_{i}-\\frac{1}{2}\\right| \\geq f(n)$."},{"id":"APMO-N1","source":"APMO","year":null,"code":"N1","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Prove that every positive integer can be written as a finite sum of distinct integral powers of the golden mean $\\tau=\\frac{1+\\sqrt{5}}{2}$. Here, an integral power of $\\tau$ is of the form $\\tau^{i}$, where $i$ is an integer (not necessarily positive)."},{"id":"APMO-C1","source":"APMO","year":null,"code":"C1","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Let $p \\geq 5$ be a prime and let $r$ be the number of ways of placing $p$ checkers on a $p \\times p$ checkerboard so that not all checkers are in the same row (but they may all be in the same column). Show that $r$ is divisible by $p^{5}$. Here, we assume that all the checkers are identical."},{"id":"APMO-G1","source":"APMO","year":null,"code":"G1","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $A$, $B$ be two distinct points on a given circle $O$ and let $P$ be the midpoint of the line segment $AB$. Let $O_{1}$ be the circle tangent to the line $AB$ at $P$ and tangent to the circle $O$. Let $\\ell$ be the tangent line, different from the line $AB$, to $O_{1}$ passing through $A$. Let $C$ be the intersection point, different from $A$, of $\\ell$ and $O$. Let $Q$ be the midpoint of the line segment $BC$ and $O_{2}$ be the circle tangent to the line $BC$ at $Q$ and tangent to the line segment $AC$. Prove that the circle $O_{2}$ is tangent to the circle $O$."},{"id":"APMO-C2","source":"APMO","year":null,"code":"C2","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"In a circus, there are $n$ clowns who dress and paint themselves up using a selection of 12 distinct colours. Each clown is required to use at least five different colours. One day, the ringmaster of the circus orders that no two clowns have exactly the same set of colours and no more than 20 clowns may use any one particular colour. Find the largest number $n$ of clowns so as to make the ringmaster's order possible."},{"id":"APMO-A2","source":"APMO","year":null,"code":"A2","subject":"Algebra","level":3,"country":"","format":"latex","body":"Let $x_{1}, x_{2}, \\ldots, x_{n}$ be positive real numbers, and let\n$$\nS = x_{1} + x_{2} + \\cdots + x_{n} .\n$$\nProve that\n$$\n\\left(1 + x_{1}\\right)\\left(1 + x_{2}\\right) \\cdots \\left(1 + x_{n}\\right) \\leq 1 + S + \\frac{S^{2}}{2!} + \\frac{S^{3}}{3!} + \\cdots + \\frac{S^{n}}{n!} .\n$$"},{"id":"APMO-N2","source":"APMO","year":null,"code":"N2","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Prove that the equation\n$$\n6\\left(6 a^{2}+3 b^{2}+c^{2}\\right)=5 n^{2}\n$$\nhas no solutions in integers except $a=b=c=n=0$."},{"id":"APMO-G2","source":"APMO","year":null,"code":"G2","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $A_{1}$, $A_{2}$, $A_{3}$ be three points in the plane, and for convenience, let $A_{4}=A_{1}$, $A_{5}=A_{2}$. For $n=1,2$, and $3$, suppose that $B_{n}$ is the midpoint of $A_{n} A_{n+1}$, and suppose that $C_{n}$ is the midpoint of $A_{n} B_{n}$. Suppose that $A_{n} C_{n+1}$ and $B_{n} A_{n+2}$ meet at $D_{n}$, and that $A_{n} B_{n+1}$ and $C_{n} A_{n+2}$ meet at $E_{n}$. Calculate the ratio of the area of triangle $D_{1} D_{2} D_{3}$ to the area of triangle $E_{1} E_{2} E_{3}$.\nAnswer: $\\frac{25}{49}$."},{"id":"APMO-C3","source":"APMO","year":null,"code":"C3","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $S$ be a set consisting of $m$ pairs $(a, b)$ of positive integers with the property that $1 \\leq a < b \\leq n$. Show that there are at least\n$$\n4m \\frac{\\left(m-\\frac{n^{2}}{4}\\right)}{3n}\n$$\ntriples $(a, b, c)$ such that $(a, b), (a, c)$, and $(b, c)$ belong to $S$."},{"id":"APMO-A3","source":"APMO","year":null,"code":"A3","subject":"Algebra","level":4,"country":"","format":"latex","body":"Determine all functions $f$ from the reals to the reals for which\n(1) $f(x)$ is strictly increasing,\n(2) $f(x)+g(x)=2x$ for all real $x$, where $g(x)$ is the composition inverse function to $f(x)$.\n(Note: $f$ and $g$ are said to be composition inverses if $f(g(x))=x$ and $g(f(x))=x$ for all real $x$.)"},{"id":"APMO-A4","source":"APMO","year":null,"code":"A4","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $a_{1}, a_{2}, \\ldots, a_{n}$ be positive real numbers, and let $S_{k}$ be the sum of products of $a_{1}, a_{2}, \\ldots, a_{n}$ taken $k$ at a time.\nShow that\n$$\nS_{k} S_{n-k} \\geq \\binom{ n}{k}^{2} a_{1} a_{2} \\ldots a_{n}, \\quad \\text{ for } \\quad k=1,2, \\ldots, n-1\n$$"},{"id":"APMO-G3","source":"APMO","year":null,"code":"G3","subject":"Geometry","level":3,"country":"","format":"latex","body":"Consider all the triangles $A B C$ which have a fixed base $A B$ and whose altitude from $C$ is a constant $h$. For which of these triangles is the product of its altitudes a maximum?"},{"id":"APMO-C4","source":"APMO","year":null,"code":"C4","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"A set of $1990$ persons is divided into non-intersecting subsets in such a way that\n(a) no one in a subset knows all the others in the subset;\n(b) among any three persons in a subset, there are always at least two who do not know each other; and\n(c) for any two persons in a subset who do not know each other, there is exactly one person in the same subset knowing both of them.\n(i) Prove that within each subset, every person has the same number of acquaintances.\n(ii) Determine the maximum possible number of subsets.\nNote: it is understood that if a person $A$ knows person $B$, then person $B$ will know person $A$; an acquaintance is someone who is known. Every person is assumed to know one's self."},{"id":"APMO-G4","source":"APMO","year":null,"code":"G4","subject":"Geometry","level":3,"country":"","format":"latex","body":"Show that for every integer $n \\geq 6$, there exists a convex hexagon which can be dissected into exactly $n$ congruent triangles."},{"id":"APMO-G5","source":"APMO","year":null,"code":"G5","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $G$ be the centroid of triangle $A B C$ and $M$ be the midpoint of $B C$. Let $X$ be on $A B$ and $Y$ on $A C$ such that the points $X, Y$, and $G$ are collinear and $X Y$ and $B C$ are parallel. Suppose that $X C$ and $G B$ intersect at $Q$ and $Y B$ and $G C$ intersect at $P$. Show that triangle $M P Q$ is similar to triangle $A B C$."},{"id":"APMO-G6","source":"APMO","year":null,"code":"G6","subject":"Geometry","level":6,"country":"","format":"latex","body":"Suppose there are 997 points given in a plane. If every two points are joined by a line segment with its midpoint coloured in red, show that there are at least 1991 red points in the plane. Can you find a special case with exactly 1991 red points?"},{"id":"APMO-A5","source":"APMO","year":null,"code":"A5","subject":"Algebra","level":3,"country":"","format":"latex","body":"Let $a_{1}, a_{2}, \\ldots, a_{n}, b_{1}, b_{2}, \\ldots, b_{n}$ be positive real numbers such that $a_{1}+a_{2}+\\cdots+a_{n}=b_{1}+b_{2}+ \\cdots+b_{n}$. Show that\n\n$$\n\\frac{a_{1}^{2}}{a_{1}+b_{1}}+\\frac{a_{2}^{2}}{a_{2}+b_{2}}+\\cdots+\\frac{a_{n}^{2}}{a_{n}+b_{n}} \\geq \\frac{a_{1}+a_{2}+\\cdots+a_{n}}{2} .\n$$"},{"id":"APMO-G7","source":"APMO","year":null,"code":"G7","subject":"Geometry","level":3,"country":"","format":"latex","body":"Given are two tangent circles and a point $P$ on their common tangent perpendicular to the lines joining their centres. Construct with ruler and compass all the circles that are tangent to these two circles and pass through the point $P$."},{"id":"APMO-G8","source":"APMO","year":null,"code":"G8","subject":"Geometry","level":3,"country":"","format":"latex","body":"In a circle $C$ with centre $O$ and radius $r$, let $C_{1}, C_{2}$ be two circles with centres $O_{1}, O_{2}$ and radii $r_{1}, r_{2}$ respectively, so that each circle $C_{i}$ is internally tangent to $C$ at $A_{i}$ and so that $C_{1}, C_{2}$ are externally tangent to each other at $A$.\nProve that the three lines $O A, O_{1} A_{2}$, and $O_{2} A_{1}$ are concurrent."},{"id":"APMO-N3","source":"APMO","year":null,"code":"N3","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Let $n$ be an integer such that $n>3$. Suppose that we choose three numbers from the set $\\{1,2, \\ldots, n\\}$. Using each of these three numbers only once and using addition, multiplication, and parenthesis, let us form all possible combinations.\n\na. Show that if we choose all three numbers greater than $n / 2$, then the values of these combinations are all distinct.\n\nb. Let $p$ be a prime number such that $p \\leq \\sqrt{n}$. Show that the number of ways of choosing three numbers so that the smallest one is $p$ and the values of the combinations are not all distinct is precisely the number of positive divisors of $p-1$."},{"id":"APMO-G9","source":"APMO","year":null,"code":"G9","subject":"Geometry","level":4,"country":"","format":"latex","body":"Determine all pairs $(h, s)$ of positive integers with the following property: If one draws $h$ horizontal lines and another $s$ lines which satisfy\n(i) they are not horizontal,\n(ii) no two of them are parallel,\n(iii) no three of the $h+s$ lines are concurrent,\nthen the number of regions formed by these $h+s$ lines is $1992$.\n\nAnswer: $(995,1),(176,10)$, and $(80,21)$."},{"id":"APMO-G10","source":"APMO","year":null,"code":"G10","subject":"Geometry","level":5,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral such that all sides have equal length and angle $\\angle ABC$ is $60$ degrees. Let $\\ell$ be a line passing through $D$ and not intersecting the quadrilateral (except at $D$). Let $E$ and $F$ be the points of intersection of $\\ell$ with $AB$ and $BC$ respectively. Let $M$ be the point of intersection of $CE$ and $AF$.\nProve that $CA^{2} = CM \\times CE$."},{"id":"APMO-A6","source":"APMO","year":null,"code":"A6","subject":"Algebra","level":5,"country":"","format":"latex","body":"Find the total number of different integer values the function\n$$\nf(x) = [x] + [2x] + \\left[\\frac{5x}{3}\\right] + [3x] + [4x]\n$$\ntakes for real numbers $x$ with $0 \\leq x \\leq 100$.\n\nNote: $[t]$ is the largest integer that does not exceed $t$."},{"id":"APMO-A7","source":"APMO","year":null,"code":"A7","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let\n$$\nf(x) = a_{n} x^{n} + a_{n-1} x^{n-1} + \\cdots + a_{0} \\quad \\text{and} \\quad g(x) = c_{n+1} x^{n+1} + c_{n} x^{n} + \\cdots + c_{0}\n$$\nbe non-zero polynomials with real coefficients such that $g(x) = (x + r) f(x)$ for some real number $r$. If $a = \\max \\left(\\left|a_{n}\\right|, \\ldots, \\left|a_{0}\\right|\\right)$ and $c = \\max \\left(\\left|c_{n+1}\\right|, \\ldots, \\left|c_{0}\\right|\\right)$, prove that $\\frac{a}{c} \\leq n+1$."},{"id":"APMO-N4","source":"APMO","year":null,"code":"N4","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Determine all positive integers $n$ for which the equation\n$$\nx^{n}+(2+x)^{n}+(2-x)^{n}=0\n$$\nhas an integer as a solution."},{"id":"APMO-C5","source":"APMO","year":null,"code":"C5","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"Let $P_{1}, P_{2}, \\ldots, P_{1993}=P_{0}$ be distinct points in the $xy$-plane with the following properties:\n(i) both coordinates of $P_{i}$ are integers, for $i=1,2, \\ldots, 1993$;\n(ii) there is no point other than $P_{i}$ and $P_{i+1}$ on the line segment joining $P_{i}$ with $P_{i+1}$ whose coordinates are both integers, for $i=0,1, \\ldots, 1992$.\nProve that for some $i, 0 \\leq i \\leq 1992$, there exists a point $Q$ with coordinates ($q_{x}, q_{y}$) on the line segment joining $P_{i}$ with $P_{i+1}$ such that both $2q_{x}$ and $2q_{y}$ are odd integers."},{"id":"APMO-A8","source":"APMO","year":null,"code":"A8","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $f: \\mathbb{R} \\rightarrow \\mathbb{R}$ be a function such that\n(i) For all $x, y \\in \\mathbb{R}$,\n$$\nf(x)+f(y)+1 \\geq f(x+y) \\geq f(x)+f(y)\n$$\n(ii) For all $x \\in [0,1)$, $f(0) \\geq f(x)$,\n(iii) $-f(-1)=f(1)=1$.\nFind all such functions $f$."},{"id":"APMO-G11","source":"APMO","year":null,"code":"G11","subject":"Geometry","level":5,"country":"","format":"latex","body":"Given a nondegenerate triangle $A B C$, with circumcentre $O$, orthocentre $H$, and circumradius $R$, prove that $|O H|<3 R$."},{"id":"APMO-N5","source":"APMO","year":null,"code":"N5","subject":"Number Theory","level":3,"country":"","format":"latex","body":"Let $n$ be an integer of the form $a^{2}+b^{2}$, where $a$ and $b$ are relatively prime integers and such that if $p$ is a prime, $p \\leq \\sqrt{n}$, then $p$ divides $a b$. Determine all such $n$.\n\nAnswer: $n=2,5,13$."},{"id":"APMO-G12","source":"APMO","year":null,"code":"G12","subject":"Geometry","level":4,"country":"","format":"latex","body":"Is there an infinite set of points in the plane such that no three points are collinear, and the distance between any two points is rational?"},{"id":"APMO-A9","source":"APMO","year":null,"code":"A9","subject":"Algebra","level":6,"country":"","format":"latex","body":"You are given three lists $A$, $B$, and $C$. List $A$ contains the numbers of the form $10^{k}$ in base 10, with $k$ any integer greater than or equal to $1$. Lists $B$ and $C$ contain the same numbers translated into base $2$ and $5$ respectively:\n\n| $A$ | $B$ | $C$ |\n| :--- | :--- | :--- |\n| 10 | 1010 | 20 |\n| 100 | 1100100 | 400 |\n| 1000 | 1111101000 | 13000 |\n| $\\vdots$ | $\\vdots$ | $\\vdots$ |\n\nProve that for every integer $n>1$, there is exactly one number in exactly one of the lists $B$ or $C$ that has exactly $n$ digits."},{"id":"APMO-C6","source":"APMO","year":null,"code":"C6","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $F$ be the set of all $n$-tuples $(A_{1}, A_{2}, \\ldots, A_{n})$ where each $A_{i}$, $i=1,2, \\ldots, n$ is a subset of $\\{1,2, \\ldots, 1998\\}$. Let $|A|$ denote the number of elements of the set $A$. Find the number\n$$\n\\sum_{(A_{1}, A_{2}, \\ldots, A_{n})} |A_{1} \\cup A_{2} \\cup \\ldots \\cup A_{n}|.\n$$"},{"id":"APMO-N6","source":"APMO","year":null,"code":"N6","subject":"Number Theory","level":3,"country":"","format":"latex","body":"Show that for any positive integers $a$ and $b$, $(36a + b)(a + 36b)$ cannot be a power of $2$."},{"id":"APMO-G13","source":"APMO","year":null,"code":"G13","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $ABC'$ be a triangle and $D$ the foot of the altitude from $A$. Let $E$ and $F$ be on a line passing through $D$ such that $AE$ is perpendicular to $BE$, $AF$ is perpendicular to $CF$, and $E$ and $F$ are different from $D$. Let $M$ and $N$ be the midpoints of the line segments $BC$ and $EF$, respectively. Prove that $AN$ is perpendicular to $NM$."},{"id":"APMO-N7","source":"APMO","year":null,"code":"N7","subject":"Number Theory","level":5,"country":"","format":"latex","body":"Determine the largest of all integers $n$ with the property that $n$ is divisible by all positive integers that are less than $\\sqrt[3]{n}$."},{"id":"APMO-A10","source":"APMO","year":null,"code":"A10","subject":"Algebra","level":5,"country":"","format":"latex","body":"Find the smallest positive integer $n$ with the following property: There does not exist an arithmetic progression of $1999$ terms of real numbers containing exactly $n$ integers."},{"id":"APMO-A11","source":"APMO","year":null,"code":"A11","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $a_{1}, a_{2}, \\cdots$ be a sequence of real numbers satisfying $a_{i+j} \\leq a_{i}+a_{j}$ for all $i, j=1,2, \\cdots$. Prove that\n$$\na_{1}+\\frac{a_{2}}{2}+\\frac{a_{3}}{3}+\\cdots+\\frac{a_{n}}{n} \\geq a_{n}\n$$\nfor each positive integer $n$."},{"id":"APMO-G14","source":"APMO","year":null,"code":"G14","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $\\Gamma_{1}$ and $\\Gamma_{2}$ be two circles intersecting at $P$ and $Q$. The common tangent, closer to $P$, of $\\Gamma_{1}$ and $\\Gamma_{2}$ touches $\\Gamma_{1}$ at $A$ and $\\Gamma_{2}$ at $B$. The tangent of $\\Gamma_{1}$ at $P$ meets $\\Gamma_{2}$ at $C$, which is different from $P$ and the extension of $A P$ meets $B C$ at $R$. Prove that the circumcircle of triangle $P Q R$ is tangent to $B P$ and $B R$."},{"id":"APMO-N8","source":"APMO","year":null,"code":"N8","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Determine all pairs $(a, b)$ of integers with the property that the numbers $a^{2}+4b$ and $b^{2}+4a$ are both perfect squares."},{"id":"APMO-G15","source":"APMO","year":null,"code":"G15","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $S$ be a set of $2n+1$ points in the plane such that no three are collinear and no four concyclic. A circle will be called good if it has 3 points of $S$ on its circumference, $n-1$ points in its interior and $n-1$ in its exterior. Prove that the number of good circles has the same parity as $n$."},{"id":"APMO-A12","source":"APMO","year":null,"code":"A12","subject":"Algebra","level":6,"country":"","format":"latex","body":"Compute the sum $S=\\sum_{i=0}^{101} \\frac{x_{i}^{3}}{1-3 x_{i}+3 x_{i}^{2}}$ for $x_{i}=\\frac{i}{101}$.\nAnswer: $S=51$."},{"id":"APMO-G16","source":"APMO","year":null,"code":"G16","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $A B C$ be a triangle. Let $M$ and $N$ be the points in which the median and angle bisector, respectively, at $A$ meet the side $B C$. Let $Q$ and $P$ be the points in which the perpendicular at $N$ to $N A$ meets $M A$ and $B A$, respectively, and $O$ be the point in which the perpendicular at $P$ to $B A$ meets $A N$ produced. Prove that $Q O$ is perpendicular to $B C$."},{"id":"APMO-A13","source":"APMO","year":null,"code":"A13","subject":"Algebra","level":3,"country":"","format":"latex","body":"Let $n$, $k$ be given positive integers with $n > k$. Prove that\n$$\n\\frac{1}{n+1} \\cdot \\frac{n^{n}}{k^{k}(n-k)^{n-k}} < \\frac{n!}{k!(n-k)!} < \\frac{n^{n}}{k^{k}(n-k)^{n-k}}.\n$$"},{"id":"APMO-A14","source":"APMO","year":null,"code":"A14","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $a_{1}, a_{2}, a_{3}, \\ldots, a_{n}$ be a sequence of non-negative integers, where $n$ is a positive integer. Let\n$$\nA_{n} = \\frac{a_{1} + a_{2} + \\cdots + a_{n}}{n}\n$$\nProve that\n$$\na_{1}! a_{2}! \\ldots a_{n}! \\geq \\left( \\left\\lfloor A_{n} \\right\\rfloor ! \\right)^{n}\n$$\nwhere $\\left\\lfloor A_{n} \\right\\rfloor$ is the greatest integer less than or equal to $A_{n}$, and $a! = 1 \\times 2 \\times \\cdots \\times a$ for $a \\geq 1$ (and $0! = 1$). When does equality hold?"},{"id":"APMO-N9","source":"APMO","year":null,"code":"N9","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Find all positive integers $a$ and $b$ such that\n$$\n\\frac{a^{2}+b}{b^{2}-a} \\text{ and } \\frac{b^{2}+a}{a^{2}-b}\n$$\nare both integers."},{"id":"APMO-G17","source":"APMO","year":null,"code":"G17","subject":"Geometry","level":5,"country":"","format":"latex","body":"Let $ABC$ be an equilateral triangle. Let $P$ be a point on the side $AC$ and $Q$ be a point on the side $AB$ so that both triangles $ABP$ and $ACQ$ are acute. Let $R$ be the orthocentre of triangle $ABP$ and $S$ be the orthocentre of triangle $ACQ$. Let $T$ be the point common to the segments $BP$ and $CQ$. Find all possible values of $\\angle CBP$ and $\\angle BCQ$ such that triangle $TRS$ is equilateral."},{"id":"APMO-A15","source":"APMO","year":null,"code":"A15","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $x$, $y$, $z$ be positive numbers such that\n$$\n\\frac{1}{x} + \\frac{1}{y} + \\frac{1}{z} = 1.\n$$\nShow that\n$$\n\\sqrt{x + y z} + \\sqrt{y + z x} + \\sqrt{z + x y} \\geq \\sqrt{x y z} + \\sqrt{x} + \\sqrt{y} + \\sqrt{z}.\n$$"},{"id":"APMO-A16","source":"APMO","year":null,"code":"A16","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $\\mathbb{R}$ denote the set of all real numbers. Find all functions $f$ from $\\mathbb{R}$ to $\\mathbb{R}$ satisfying:\n(i) there are only finitely many $s$ in $\\mathbb{R}$ such that $f(s)=0$, and\n(ii) $f\\left(x^{4}+y\\right)=x^{3} f(x)+f(f(y))$ for all $x, y$ in $\\mathbb{R}$."},{"id":"APMO-A17","source":"APMO","year":null,"code":"A17","subject":"Algebra","level":3,"country":"","format":"latex","body":"Let $a, b, c, d, e, f$ be real numbers such that the polynomial\n$$\np(x) = x^{8} - 4x^{7} + 7x^{6} + a x^{5} + b x^{4} + c x^{3} + d x^{2} + e x + f\n$$\nfactorises into eight linear factors $x - x_{i}$, with $x_{i} > 0$ for $i = 1, 2, \\ldots, 8$. Determine all possible values of $f$."},{"id":"APMO-G18","source":"APMO","year":null,"code":"G18","subject":"Geometry","level":6,"country":"","format":"latex","body":"Suppose $ABCD$ is a square piece of cardboard with side length $a$. On a plane are two parallel lines $\\ell_{1}$ and $\\ell_{2}$, which are also $a$ units apart. The square $ABCD$ is placed on the plane so that sides $AB$ and $AD$ intersect $\\ell_{1}$ at $E$ and $F$ respectively. Also, sides $CB$ and $CD$ intersect $\\ell_{2}$ at $G$ and $H$ respectively. Let the perimeters of $\\triangle AEF$ and $\\triangle CGH$ be $m_{1}$ and $m_{2}$ respectively. Prove that no matter how the square was placed, $m_{1}+m_{2}$ remains constant."},{"id":"APMO-N10","source":"APMO","year":null,"code":"N10","subject":"Number Theory","level":5,"country":"","format":"latex","body":"Let $k \\geq 14$ be an integer, and let $p_{k}$ be the largest prime number which is strictly less than $k$. You may assume that $p_{k} \\geq 3k/4$. Let $n$ be a composite integer. Prove:\n\na. if $n = 2p_{k}$, then $n$ does not divide $(n-k)!$;\n\nb. if $n > 2p_{k}$, then $n$ divides $(n-k)!$."},{"id":"APMO-G19","source":"APMO","year":null,"code":"G19","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $a$, $b$, $c$ be the sides of a triangle, with $a + b + c = 1$, and let $n \\geq 2$ be an integer. Show that\n$$\n\\sqrt[n]{a^{n} + b^{n}} + \\sqrt[n]{b^{n} + c^{n}} + \\sqrt[n]{c^{n} + a^{n}} < 1 + \\frac{\\sqrt[n]{2}}{2}\n$$"},{"id":"APMO-C7","source":"APMO","year":null,"code":"C7","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"Given two positive integers $m$ and $n$, find the smallest positive integer $k$ such that among any $k$ people, either there are $2m$ of them who form $m$ pairs of mutually acquainted people or there are $2n$ of them forming $n$ pairs of mutually unacquainted people."},{"id":"APMO-N11","source":"APMO","year":null,"code":"N11","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Determine all finite nonempty sets $S$ of positive integers satisfying\n$$\n\\frac{i+j}{(i, j)} \\quad \\text{is an element of } S \\text{ for all } i, j \\text{ in } S,\n$$\nwhere $(i, j)$ is the greatest common divisor of $i$ and $j$."},{"id":"APMO-G20","source":"APMO","year":null,"code":"G20","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $O$ be the circumcentre and $H$ the orthocentre of an acute triangle $A B C$. Prove that the area of one of the triangles $A O H$, $B O H$ and $C O H$ is equal to the sum of the areas of the other two."},{"id":"APMO-G21","source":"APMO","year":null,"code":"G21","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let a set $S$ of 2004 points in the plane be given, no three of which are collinear. Let $\\mathcal{L}$ denote the set of all lines (extended indefinitely in both directions) determined by pairs of points from the set. Show that it is possible to colour the points of $S$ with at most two colours, such that for any points $p, q$ of $S$, the number of lines in $\\mathcal{L}$ which separate $p$ from $q$ is odd if and only if $p$ and $q$ have the same colour.\n\nNote: A line $\\ell$ separates two points $p$ and $q$ if $p$ and $q$ lie on opposite sides of $\\ell$ with neither point on $\\ell$."},{"id":"APMO-N12","source":"APMO","year":null,"code":"N12","subject":"Number Theory","level":6,"country":"","format":"latex","body":"For a real number $x$, let $\\lfloor x\\rfloor$ stand for the largest integer that is less than or equal to $x$. Prove that\n$$\n\\left\\lfloor\\frac{(n-1)!}{n(n+1)}\\right\\rfloor\n$$\nis even for every positive integer $n$."},{"id":"APMO-A18","source":"APMO","year":null,"code":"A18","subject":"Algebra","level":3,"country":"","format":"latex","body":"Prove that\n$$\n\\left(a^{2}+2\\right)\\left(b^{2}+2\\right)\\left(c^{2}+2\\right) \\geq 9(ab+bc+ca)\n$$\nfor all real numbers $a, b, c > 0$."},{"id":"APMO-A19","source":"APMO","year":null,"code":"A19","subject":"Algebra","level":6,"country":"","format":"latex","body":"Prove that for every irrational real number $a$, there are irrational real numbers $b$ and $b^{\\prime}$ so that $a+b$ and $a b^{\\prime}$ are both rational while $a b$ and $a+b^{\\prime}$ are both irrational."},{"id":"APMO-A20","source":"APMO","year":null,"code":"A20","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $a$, $b$ and $c$ be positive real numbers such that $a b c = 8$. Prove that\n$$\n\\frac{a^{2}}{\\sqrt{\\left(1+a^{3}\\right)\\left(1+b^{3}\\right)}} + \\frac{b^{2}}{\\sqrt{\\left(1+b^{3}\\right)\\left(1+c^{3}\\right)}} + \\frac{c^{2}}{\\sqrt{\\left(1+c^{3}\\right)\\left(1+a^{3}\\right)}} \\geq \\frac{4}{3}\n$$"},{"id":"APMO-G22","source":"APMO","year":null,"code":"G22","subject":"Geometry","level":6,"country":"","format":"latex","body":"Prove that there exists a triangle which can be cut into 2005 congruent triangles."},{"id":"APMO-C8","source":"APMO","year":null,"code":"C8","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"In a small town, there are $n \\times n$ houses indexed by $(i, j)$ for $1 \\leq i, j \\leq n$ with $(1,1)$ being the house at the top left corner, where $i$ and $j$ are the row and column indices, respectively. At time $0$, a fire breaks out at the house indexed by $(1, c)$, where $c \\leq \\frac{n}{2}$. During each subsequent time interval $[t, t+1]$, the fire fighters defend a house which is not yet on fire while the fire spreads to all undefended neighbors of each house which was on fire at time $t$. Once a house is defended, it remains so all the time. The process ends when the fire can no longer spread. At most how many houses can be saved by the fire fighters? A house indexed by $(i, j)$ is a neighbor of a house indexed by $(k, \\ell)$ if $|i-k|+|j-\\ell|=1$."},{"id":"APMO-G23","source":"APMO","year":null,"code":"G23","subject":"Geometry","level":6,"country":"","format":"latex","body":"In a triangle $A B C$, points $M$ and $N$ are on sides $A B$ and $A C$, respectively, such that $M B = B C = C N$. Let $R$ and $r$ denote the circumradius and the inradius of the triangle $A B C$, respectively. Express the ratio $M N / B C$ in terms of $R$ and $r$."},{"id":"APMO-C9","source":"APMO","year":null,"code":"C9","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $S$ be a set of 9 distinct integers all of whose prime factors are at most $3$. Prove that $S$ contains 3 distinct integers such that their product is a perfect cube."},{"id":"APMO-G24","source":"APMO","year":null,"code":"G24","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be an acute angled triangle with $\\angle BAC = 60^\\circ$ and $AB > AC$. Let $I$ be the incenter, and $H$ the orthocenter of the triangle $ABC$. Prove that\n$$\n2 \\angle AHI = 3 \\angle ABC.\n$$"},{"id":"APMO-G25","source":"APMO","year":null,"code":"G25","subject":"Geometry","level":6,"country":"","format":"latex","body":"Consider $n$ disks $C_{1}, C_{2}, \\ldots, C_{n}$ in a plane such that for each $1 \\leq i < n$, the center of $C_{i}$ is on the circumference of $C_{i+1}$, and the center of $C_{n}$ is on the circumference of $C_{1}$. Define the score of such an arrangement of $n$ disks to be the number of pairs $(i, j)$ for which $C_{i}$ properly contains $C_{j}$. Determine the maximum possible score."},{"id":"APMO-A21","source":"APMO","year":null,"code":"A21","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $x$, $y$ and $z$ be positive real numbers such that $\\sqrt{x}+\\sqrt{y}+\\sqrt{z}=1$. Prove that\n$$\n\\frac{x^{2}+y z}{\\sqrt{2 x^{2}(y+z)}}+\\frac{y^{2}+z x}{\\sqrt{2 y^{2}(z+x)}}+\\frac{z^{2}+x y}{\\sqrt{2 z^{2}(x+y)}} \\geq 1\n$$"},{"id":"APMO-C10","source":"APMO","year":null,"code":"C10","subject":"Combinatorics","level":3,"country":"","format":"latex","body":"A regular ($5 \\times 5$)-array of lights is defective, so that toggling the switch for one light causes each adjacent light in the same row and in the same column as well as the light itself to change state, from on to off, or from off to on. Initially all the lights are switched off. After a certain number of toggles, exactly one light is switched on. Find all the possible positions of this light."},{"id":"APMO-G26","source":"APMO","year":null,"code":"G26","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be a triangle with $\\angle A < 60^{\\circ}$. Let $X$ and $Y$ be the points on the sides $AB$ and $AC$, respectively, such that $CA + AX = CB + BX$ and $BA + AY = BC + CY$. Let $P$ be the point in the plane such that the lines $PX$ and $PY$ are perpendicular to $AB$ and $AC$, respectively. Prove that $\\angle BPC < 120^{\\circ}$."},{"id":"APMO-C11","source":"APMO","year":null,"code":"C11","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Students in a class form groups each of which contains exactly three members such that any two distinct groups have at most one member in common. Prove that, when the class size is $46$, there is a set of $10$ students in which no group is properly contained."},{"id":"APMO-G27","source":"APMO","year":null,"code":"G27","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $\\Gamma$ be the circumcircle of a triangle $A B C$. A circle passing through points $A$ and $C$ meets the sides $B C$ and $B A$ at $D$ and $E$, respectively. The lines $A D$ and $C E$ meet $\\Gamma$ again at $G$ and $H$, respectively. The tangent lines of $\\Gamma$ at $A$ and $C$ meet the line $D E$ at $L$ and $M$, respectively. Prove that the lines $L H$ and $M G$ meet at $\\Gamma$."},{"id":"APMO-A22","source":"APMO","year":null,"code":"A22","subject":"Algebra","level":6,"country":"","format":"latex","body":"Consider the function $f: \\mathbb{N}_0 \\rightarrow \\mathbb{N}_0$, where $\\mathbb{N}_0$ is the set of all non-negative integers, defined by the following conditions:\n(i) $f(0)=0$,\n(ii) $f(2 n)=2 f(n)$ and\n(iii) $f(2 n+1)=n+2 f(n)$ for all $n \\geq 0$.\n\na. Determine the three sets $L:=\\{n \\mid f(n)<f(n+1)\\}$, $E:=\\{n \\mid f(n)=f(n+1)\\}$, and $G:=\\{n \\mid f(n)>f(n+1)\\}$.\n\nb. For each $k \\geq 0$, find a formula for $a_k:=\\max \\left\\{f(n): 0 \\leq n \\leq 2^k\\right\\}$ in terms of $k$."},{"id":"APMO-N13","source":"APMO","year":null,"code":"N13","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Let $a$, $b$, $c$ be integers satisfying $0 < a < c - 1$ and $1 < b < c$. For each $k$, $0 \\leq k \\leq a$, let $r_{k}$, $0 \\leq r_{k} < c$, be the remainder of $k b$ when divided by $c$. Prove that the two sets $\\{r_{0}, r_{1}, r_{2}, \\ldots, r_{a}\\}$ and $\\{0, 1, 2, \\ldots, a\\}$ are different."},{"id":"APMO-C12","source":"APMO","year":null,"code":"C12","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"Consider the following operation on positive real numbers written on a blackboard:\nChoose a number $r$ written on the blackboard, erase that number, and then write a pair of positive real numbers $a$ and $b$ satisfying the condition $2 r^{2}=a b$ on the board.\nAssume that you start out with just one positive real number $r$ on the blackboard, and apply this operation $k^{2}-1$ times to end up with $k^{2}$ positive real numbers, not necessarily distinct. Show that there exists a number on the board which does not exceed $k r$."},{"id":"APMO-A23","source":"APMO","year":null,"code":"A23","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $a_{1}, a_{2}, a_{3}, a_{4}, a_{5}$ be real numbers satisfying the following equations:\n$$\n\\frac{a_{1}}{k^{2}+1}+\\frac{a_{2}}{k^{2}+2}+\\frac{a_{3}}{k^{2}+3}+\\frac{a_{4}}{k^{2}+4}+\\frac{a_{5}}{k^{2}+5}=\\frac{1}{k^{2}} \\text{ for } k=1,2,3,4,5 .\n$$\nFind the value of $\\frac{a_{1}}{37}+\\frac{a_{2}}{38}+\\frac{a_{3}}{39}+\\frac{a_{4}}{40}+\\frac{a_{5}}{41}$. (Express the value in a single fraction.)"},{"id":"APMO-G28","source":"APMO","year":null,"code":"G28","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let three circles $\\Gamma_{1}, \\Gamma_{2}, \\Gamma_{3}$, which are non-overlapping and mutually external, be given in the plane. For each point $P$ in the plane, outside the three circles, construct six points $A_{1}, B_{1}, A_{2}, B_{2}, A_{3}, B_{3}$ as follows: For each $i=1,2,3$, $A_{i}, B_{i}$ are distinct points on the circle $\\Gamma_{i}$ such that the lines $P A_{i}$ and $P B_{i}$ are both tangents to $\\Gamma_{i}$. Call the point $P$ exceptional if, from the construction, three lines $A_{1} B_{1}, A_{2} B_{2}, A_{3} B_{3}$ are concurrent. Show that every exceptional point of the plane, if exists, lies on the same circle."},{"id":"APMO-N14","source":"APMO","year":null,"code":"N14","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Prove that for any positive integer $k$, there exists an arithmetic sequence\n$$\n\\frac{a_{1}}{b_{1}}, \\quad \\frac{a_{2}}{b_{2}}, \\quad \\ldots, \\quad \\frac{a_{k}}{b_{k}}\n$$\nof rational numbers, where $a_{i}, b_{i}$ are relatively prime positive integers for each $i=1,2, \\ldots, k$, such that the positive integers $a_{1}, b_{1}, a_{2}, b_{2}, \\ldots, a_{k}, b_{k}$ are all distinct."},{"id":"APMO-N15","source":"APMO","year":null,"code":"N15","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Larry and Rob are two robots travelling in one car from Argovia to Zillis. Both robots have control over the steering and steer according to the following algorithm: Larry makes a $90^{\\circ}$ left turn after every $\\ell$ kilometer driving from start; Rob makes a $90^{\\circ}$ right turn after every $r$ kilometer driving from start, where $\\ell$ and $r$ are relatively prime positive integers. In the event of both turns occurring simultaneously, the car will keep going without changing direction. Assume that the ground is flat and the car can move in any direction.\nLet the car start from Argovia facing towards Zillis. For which choices of the pair ( $\\ell, r$ ) is the car guaranteed to reach Zillis, regardless of how far it is from Argovia?"},{"id":"APMO-G29","source":"APMO","year":null,"code":"G29","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be a triangle with $\\angle BAC \\neq 90^{\\circ}$. Let $O$ be the circumcenter of the triangle $ABC$ and let $\\Gamma$ be the circumcircle of the triangle $BOC$. Suppose that $\\Gamma$ intersects the line segment $AB$ at $P$ different from $B$, and the line segment $AC$ at $Q$ different from $C$. Let $ON$ be a diameter of the circle $\\Gamma$. Prove that the quadrilateral $APNQ$ is a parallelogram."},{"id":"APMO-A24","source":"APMO","year":null,"code":"A24","subject":"Algebra","level":5,"country":"","format":"latex","body":"For a positive integer $k$, call an integer a pure $k$-th power if it can be represented as $m^{k}$ for some integer $m$. Show that for every positive integer $n$ there exist $n$ distinct positive integers such that their sum is a pure $2009$-th power, and their product is a pure $2010$-th power."},{"id":"APMO-C13","source":"APMO","year":null,"code":"C13","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer. $n$ people take part in a certain party. For any pair of the participants, either the two are acquainted with each other or they are not. What is the maximum possible number of the pairs for which the two are not acquainted but have a common acquaintance among the participants?"},{"id":"APMO-G30","source":"APMO","year":null,"code":"G30","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle satisfying the condition $AB > BC$ and $AC > BC$. Denote by $O$ and $H$ the circumcenter and the orthocenter, respectively, of the triangle $ABC$. Suppose that the circumcircle of the triangle $AHC$ intersects the line $AB$ at $M$ different from $A$, and that the circumcircle of the triangle $AHB$ intersects the line $AC$ at $N$ different from $A$. Prove that the circumcenter of the triangle $MNH$ lies on the line $OH$."},{"id":"APMO-A25","source":"APMO","year":null,"code":"A25","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all functions $f$ from the set $\\{\\mathbf{R}\\}$ of real numbers into $\\{\\mathbf{R}\\}$ which satisfy for all $x, y, z \\in \\{\\mathbf{R}\\}$ the identity\n$$\nf(f(x)+f(y)+f(z))=f(f(x)-f(y))+f(2 x y+f(z))+2 f(x z-y z)\n$$"},{"id":"APMO-G31","source":"APMO","year":null,"code":"G31","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle with altitudes $AD$, $BE$ and $CF$, and let $O$ be the center of its circumcircle. Show that the segments $OA$, $OF$, $OB$, $OD$, $OC$, $OE$ dissect the triangle $ABC$ into three pairs of triangles that have equal areas."},{"id":"APMO-G32","source":"APMO","year":null,"code":"G32","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $ABCD$ be a quadrilateral inscribed in a circle $\\omega$, and let $P$ be a point on the extension of $AC$ such that $PB$ and $PD$ are tangent to $\\omega$. The tangent at $C$ intersects $PD$ at $Q$ and the line $AD$ at $R$. Let $E$ be the second point of intersection between $AQ$ and $\\omega$. Prove that $B$, $E$, $R$ are collinear."},{"id":"APMO-N16","source":"APMO","year":null,"code":"N16","subject":"Number Theory","level":6,"country":"","format":"latex","body":"For a positive integer $m$ denote by $S(m)$ and $P(m)$ the sum and product, respectively, of the digits of $m$. Show that for each positive integer $n$, there exist positive integers $a_{1}, a_{2}, \\ldots, a_{n}$ satisfying the following conditions:\n$$\nS\\left(a_{1}\\right)<S\\left(a_{2}\\right)<\\cdots<S\\left(a_{n}\\right) \\text{ and } S\\left(a_{i}\\right)=P\\left(a_{i+1}\\right) \\quad(i=1,2, \\ldots, n) .\n$$\n(We let $a_{n+1}=a_{1}$.) (Problem Committee of the Japan Mathematical Olympiad Foundation)"},{"id":"APMO-G33","source":"APMO","year":null,"code":"G33","subject":"Geometry","level":5,"country":"","format":"latex","body":"Let $ABC$ be a triangle, and let $D$ be a point on side $BC$. A line through $D$ intersects side $AB$ at $X$ and ray $AC$ at $Y$. The circumcircle of triangle $BXD$ intersects the circumcircle $\\omega$ of triangle $ABC$ again at point $Z \\neq B$. The lines $ZD$ and $ZY$ intersect $\\omega$ again at $V$ and $W$, respectively. Prove that $AB = VW$."},{"id":"APMO-A26","source":"APMO","year":null,"code":"A26","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $S=\\{2,3,4, \\ldots\\}$ denote the set of integers that are greater than or equal to $2$. Does there exist a function $f: S \\rightarrow S$ such that\n$$\nf(a) f(b) = f\\left(a^{2} b^{2}\\right) \\text{ for all } a, b \\in S \\text{ with } a \\neq b?\n$$"},{"id":"APMO-A27","source":"APMO","year":null,"code":"A27","subject":"Algebra","level":5,"country":"","format":"latex","body":"A sequence of real numbers $a_{0}, a_{1}, \\ldots$ is said to be $\\operatorname{good}$ if the following three conditions hold.\n(i) The value of $a_{0}$ is a positive integer.\n(ii) For each non-negative integer $i$ we have $a_{i+1}=2 a_{i}+1$ or $a_{i+1}=\\frac{a_{i}}{a_{i}+2}$.\n(iii) There exists a positive integer $k$ such that $a_{k}=2014$.\nFind the smallest positive integer $n$ such that there exists a good sequence $a_{0}, a_{1}, \\ldots$ of real numbers with the property that $a_{n}=2014$."},{"id":"APMO-G34","source":"APMO","year":null,"code":"G34","subject":"Geometry","level":5,"country":"","format":"latex","body":"Let $n$ be a positive integer. Consider $2n$ distinct lines on the plane, no two of which are parallel. Of the $2n$ lines, $n$ are colored blue, the other $n$ are colored red. Let $\\mathcal{B}$ be the set of all points on the plane that lie on at least one blue line, and $\\mathcal{R}$ the set of all points on the plane that lie on at least one red line. Prove that there exists a circle that intersects $\\mathcal{B}$ in exactly $2n-1$ points, and also intersects $\\mathcal{R}$ in exactly $2n-1$ points."},{"id":"APMO-G35","source":"APMO","year":null,"code":"G35","subject":"Geometry","level":3,"country":"","format":"latex","body":"We say that a triangle $ABC$ is great if the following holds: for any point $D$ on the side $BC$, if $P$ and $Q$ are the feet of the perpendiculars from $D$ to the lines $AB$ and $AC$, respectively, then the reflection of $D$ in the line $PQ$ lies on the circumcircle of the triangle $ABC$.\nProve that triangle $ABC$ is great if and only if $\\angle A = 90^{\\circ}$ and $AB = AC$."},{"id":"APMO-N17","source":"APMO","year":null,"code":"N17","subject":"Number Theory","level":5,"country":"","format":"latex","body":"A positive integer is called fancy if it can be expressed in the form\n$$\n2^{a_{1}} + 2^{a_{2}} + \\cdots + 2^{a_{100}}\n$$\nwhere $a_{1}, a_{2}, \\ldots, a_{100}$ are non-negative integers that are not necessarily distinct.\nFind the smallest positive integer $n$ such that no multiple of $n$ is a fancy number."},{"id":"APMO-G36","source":"APMO","year":null,"code":"G36","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $AB$ and $AC$ be two distinct rays not lying on the same line, and let $\\omega$ be a circle with center $O$ that is tangent to ray $AC$ at $E$ and ray $AB$ at $F$. Let $R$ be a point on segment $EF$. The line through $O$ parallel to $EF$ intersects line $AB$ at $P$. Let $N$ be the intersection of lines $PR$ and $AC$, and let $M$ be the intersection of line $AB$ and the line through $R$ parallel to $AC$. Prove that line $MN$ is tangent to $\\omega$."},{"id":"APMO-C14","source":"APMO","year":null,"code":"C14","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"The country Dreamland consists of 2016 cities. The airline Starways wants to establish some one-way flights between pairs of cities in such a way that each city has exactly one flight out of it. Find the smallest positive integer $k$ such that no matter how Starways establishes its flights, the cities can always be partitioned into $k$ groups so that from any city it is not possible to reach another city in the same group by using at most 28 flights."},{"id":"APMO-A28","source":"APMO","year":null,"code":"A28","subject":"Algebra","level":5,"country":"","format":"latex","body":"Find all functions $f: \\mathbb{R}^{+} \\rightarrow \\mathbb{R}^{+}$ such that\n$$\n(z+1) f(x+y) = f(x f(z) + y) + f(y f(z) + x)\n$$\nfor all positive real numbers $x$, $y$, $z$."},{"id":"APMO-A29","source":"APMO","year":null,"code":"A29","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $\\mathbb{Z}^{+}$ be the set of positive integers. Determine all functions $f: \\mathbb{Z}^{+} \\rightarrow \\mathbb{Z}^{+}$ such that $a^{2} + f(a) f(b)$ is divisible by $f(a) + b$ for all positive integers $a$ and $b$."},{"id":"APMO-A30","source":"APMO","year":null,"code":"A30","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $m$ be a fixed positive integer. The infinite sequence $\\{a_{n}\\}_{n \\geq 1}$ is defined in the following way: $a_{1}$ is a positive integer, and for every integer $n \\geq 1$ we have\n$$\na_{n+1}= \\begin{cases}a_{n}^{2}+2^{m} & \\text{ if } a_{n}<2^{m} \\\\ a_{n} / 2 & \\text{ if } a_{n} \\geq 2^{m}\\end{cases}\n$$\nFor each $m$, determine all possible values of $a_{1}$ such that every term in the sequence is an integer."},{"id":"APMO-G37","source":"APMO","year":null,"code":"G37","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $ABC$ be a scalene triangle with circumcircle $\\Gamma$. Let $M$ be the midpoint of $BC$. A variable point $P$ is selected in the line segment $AM$. The circumcircles of triangles $BPM$ and $CPM$ intersect $\\Gamma$ again at points $D$ and $E$, respectively. The lines $DP$ and $EP$ intersect (a second time) the circumcircles to triangles $CPM$ and $BPM$ at $X$ and $Y$, respectively. Prove that as $P$ varies, the circumcircle of $\\triangle AXY$ passes through a fixed point $T$ distinct from $A$."},{"id":"APMO-C15","source":"APMO","year":null,"code":"C15","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"Consider a $2018 \\times 2019$ board with integers in each unit square. Two unit squares are said to be neighbours if they share a common edge. In each turn, you choose some unit squares. Then for each chosen unit square the average of all its neighbours is calculated. Finally, after these calculations are done, the number in each chosen unit square is replaced by the corresponding average. Is it always possible to make the numbers in all squares become the same after finitely many turns?"},{"id":"APMO-A31","source":"APMO","year":null,"code":"A31","subject":"Algebra","level":5,"country":"","format":"latex","body":"Determine all the functions $f: \\mathbb{R} \\rightarrow \\mathbb{R}$ such that\n$$\nf\\left(x^{2}+f(y)\\right)=f(f(x))+f\\left(y^{2}\\right)+2 f(x y)\n$$\nfor all real number $x$ and $y$."},{"id":"APMO-G38","source":"APMO","year":null,"code":"G38","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $\\Gamma$ be the circumcircle of $\\triangle A B C$. Let $D$ be a point on the side $B C$. The tangent to $\\Gamma$ at $A$ intersects the parallel line to $B A$ through $D$ at point $E$. The segment $C E$ intersects $\\Gamma$ again at $F$. Suppose $B, D, F, E$ are concyclic. Prove that $A C, B F, D E$ are concurrent."},{"id":"APMO-A32","source":"APMO","year":null,"code":"A32","subject":"Algebra","level":6,"country":"","format":"latex","body":"Show that $r=2$ is the largest real number $r$ which satisfies the following condition:\nIf a sequence $a_{1}, a_{2}, \\ldots$ of positive integers fulfills the inequalities\n$$\na_{n} \\leq a_{n+2} \\leq \\sqrt{a_{n}^{2}+r a_{n+1}}\n$$\nfor every positive integer $n$, then there exists a positive integer $M$ such that $a_{n+2}=a_{n}$ for every $n \\geq M$."},{"id":"APMO-C16","source":"APMO","year":null,"code":"C16","subject":"Combinatorics","level":3,"country":"","format":"latex","body":"Determine all positive integers $k$ for which there exist a positive integer $m$ and a set $S$ of positive integers such that any integer $n>m$ can be written as a sum of distinct elements of $S$ in exactly $k$ ways."},{"id":"APMO-A33","source":"APMO","year":null,"code":"A33","subject":"Algebra","level":4,"country":"","format":"latex","body":"Let $\\mathbb{Z}$ denote the set of all integers. Find all polynomials $P(x)$ with integer coefficients that satisfy the following property:\nFor any infinite sequence $a_{1}, a_{2}, \\ldots$ of integers in which each integer in $\\mathbb{Z}$ appears exactly once, there exist indices $i<j$ and an integer $k$ such that $a_{i}+a_{i+1}+\\cdots+a_{j}=P(k)$."},{"id":"APMO-G39","source":"APMO","year":null,"code":"G39","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABCD$ be a cyclic convex quadrilateral and $\\Gamma$ be its circumcircle. Let $E$ be the intersection of the diagonals $AC$ and $BD$, let $L$ be the center of the circle tangent to sides $AB$, $BC$, and $CD$, and let $M$ be the midpoint of the arc $BC$ of $\\Gamma$ not containing $A$ and $D$. Prove that the excenter of triangle $BCE$ opposite $E$ lies on the line $LM$."},{"id":"APMO-N18","source":"APMO","year":null,"code":"N18","subject":"Number Theory","level":4,"country":"","format":"latex","body":"Find all pairs $(a, b)$ of positive integers such that $a^{3}$ is a multiple of $b^{2}$ and $b-1$ is a multiple of $a-1$. Note: An integer $n$ is said to be a multiple of an integer $m$ if there is an integer $k$ such that $n=k m$."},{"id":"APMO-G40","source":"APMO","year":null,"code":"G40","subject":"Geometry","level":3,"country":"","format":"latex","body":"Let $ABC$ be a right triangle with $\\angle B = 90^{\\circ}$. Point $D$ lies on the line $CB$ such that $B$ is between $D$ and $C$. Let $E$ be the midpoint of $AD$ and let $F$ be the second intersection point of the circumcircle of $\\triangle ACD$ and the circumcircle of $\\triangle BDE$. Prove that as $D$ varies, the line $EF$ passes through a fixed point."},{"id":"APMO-A34","source":"APMO","year":null,"code":"A34","subject":"Algebra","level":6,"country":"","format":"latex","body":"Find all positive integers $k<202$ for which there exists a positive integer $n$ such that\n$$\n\\left\\{\\frac{n}{202}\\right\\}+\\left\\{\\frac{2 n}{202}\\right\\}+\\cdots+\\left\\{\\frac{k n}{202}\\right\\}=\\frac{k}{2}\n$$\nwhere $\\{x\\}$ denote the fractional part of $x$.\nNote: $\\{x\\}$ denotes the real number $k$ with $0 \\leq k<1$ such that $x-k$ is an integer."},{"id":"APMO-C17","source":"APMO","year":null,"code":"C17","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $n$ and $k$ be positive integers. Cathy is playing the following game. There are $n$ marbles and $k$ boxes, with the marbles labelled $1$ to $n$. Initially, all marbles are placed inside one box. Each turn, Cathy chooses a box and then moves the marbles with the smallest label, say $i$, to either any empty box or the box containing marble $i+1$. Cathy wins if at any point there is a box containing only marble $n$.\nDetermine all pairs of integers $(n, k)$ such that Cathy can win this game."},{"id":"APMO-A35","source":"APMO","year":null,"code":"A35","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $a, b, c, d$ be real numbers such that $a^{2}+b^{2}+c^{2}+d^{2}=1$. Determine the minimum value of $(a-b)(b-c)(c-d)(d-a)$ and determine all values of $(a, b, c, d)$ such that the minimum value is achieved."},{"id":"APMO-G41","source":"APMO","year":null,"code":"G41","subject":"Geometry","level":6,"country":"","format":"latex","body":"Let $n \\geq 5$ be an integer. Consider $n$ squares with side lengths $1,2, \\ldots, n$, respectively. The squares are arranged in the plane with their sides parallel to the $x$ and $y$ axes. Suppose that no two squares touch, except possibly at their vertices.\nShow that it is possible to arrange these squares in a way such that every square touches exactly two other squares."},{"id":"APMO-N19","source":"APMO","year":null,"code":"N19","subject":"Number Theory","level":5,"country":"","format":"latex","body":"Find all integers $n$ satisfying $n \\geq 2$ and $\\frac{\\sigma(n)}{p(n)-1}=n$, in which $\\sigma(n)$ denotes the sum of all positive divisors of $n$, and $p(n)$ denotes the largest prime divisor of $n$."},{"id":"APMO-G42","source":"APMO","year":null,"code":"G42","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABCD$ be a parallelogram. Let $W$, $X$, $Y$, and $Z$ be points on sides $AB$, $BC$, $CD$, and $DA$, respectively, such that the incenters of triangles $AWZ$, $BXW$, $CYX$ and $DZY$ form a parallelogram. Prove that $WXYZ$ is a parallelogram."},{"id":"APMO-A36","source":"APMO","year":null,"code":"A36","subject":"Algebra","level":5,"country":"","format":"latex","body":"Let $c>0$ be a given positive real and $\\mathbb{R}_{>0}$ be the set of all positive reals. Find all functions $f: \\mathbb{R}_{>0} \\rightarrow \\mathbb{R}_{>0}$ such that\n$$\nf((c+1) x+f(y))=f(x+2 y)+2 c x \\quad \\text{ for all } x, y \\in \\mathbb{R}_{>0} .\n$$"},{"id":"APMO-G43","source":"APMO","year":null,"code":"G43","subject":"Geometry","level":5,"country":"","format":"latex","body":"There are $n$ line segments on the plane, no three intersecting at a point, and each pair intersecting once in their respective interiors. Tony and his $2 n-1$ friends each stand at a distinct endpoint of a line segment. Tony wishes to send Christmas presents to each of his friends as follows:\nFirst, he chooses an endpoint of each segment as a \"sink\". Then he places the present at the endpoint of the segment he is at. The present moves as follows:\n- If it is on a line segment, it moves towards the sink.\n- When it reaches an intersection of two segments, it changes the line segment it travels on and starts moving towards the new sink.\nIf the present reaches an endpoint, the friend on that endpoint can receive their present. Prove Tony can send presents to exactly $n$ of his $2 n-1$ friends."},{"id":"APMO-G44","source":"APMO","year":null,"code":"G44","subject":"Geometry","level":4,"country":"","format":"latex","body":"Let $ABC$ be an acute triangle. Let $D$ be a point on side $AB$ and $E$ be a point on side $AC$ such that lines $BC$ and $DE$ are parallel. Let $X$ be an interior point of $BCED$. Suppose rays $DX$ and $EX$ meet side $BC$ at points $P$ and $Q$, respectively, such that both $P$ and $Q$ lie between $B$ and $C$. Suppose that the circumcircles of triangles $BQX$ and $CPX$ intersect at a point $Y \\neq X$. Prove that points $A$, $X$, and $Y$ are collinear."},{"id":"APMO-C18","source":"APMO","year":null,"code":"C18","subject":"Combinatorics","level":4,"country":"","format":"latex","body":"Consider a $100 \\times 100$ table, and identify the cell in row $a$ and column $b$, $1 \\leq a, b \\leq 100$, with the ordered pair $(a, b)$. Let $k$ be an integer such that $51 \\leq k \\leq 99$. A $k$-knight is a piece that moves one cell vertically or horizontally and $k$ cells to the other direction; that is, it moves from $(a, b)$ to $(c, d)$ such that $(|a-c|,|b-d|)$ is either $(1, k)$ or $(k, 1)$. The $k$-knight starts at cell $(1,1)$, and performs several moves. A sequence of moves is a sequence of cells $(x_{0}, y_{0})=(1,1)$, $(x_{1}, y_{1})$, $(x_{2}, y_{2}), \\ldots, (x_{n}, y_{n})$ such that, for all $i=1,2, \\ldots, n$, $1 \\leq x_{i}, y_{i} \\leq 100$ and the $k$-knight can move from $(x_{i-1}, y_{i-1})$ to $(x_{i}, y_{i})$. In this case, each cell $(x_{i}, y_{i})$ is said to be reachable. For each $k$, find $L(k)$, the number of reachable cells.\nAnswer: $L(k)=\\left\\{\\begin{array}{ll}100^{2}-(2 k-100)^{2} & \\text{ if } k \\text{ is even } \\\\ \\frac{100^{2}-(2 k-100)^{2}}{2} & \\text{ if } k \\text{ is odd }\\end{array}\\right.$."},{"id":"APMO-A37","source":"APMO","year":null,"code":"A37","subject":"Algebra","level":6,"country":"","format":"latex","body":"Let $n$ be a positive integer and $a_{1}, a_{2}, \\ldots, a_{n}$ be positive real numbers. Prove that\n$$\n\\sum_{i=1}^{n} \\frac{1}{2^{i}}\\left(\\frac{2}{1+a_{i}}\\right)^{2^{i}} \\geq \\frac{2}{1+a_{1} a_{2} \\ldots a_{n}}-\\frac{1}{2^{n}} .\n$$"},{"id":"APMO-N20","source":"APMO","year":null,"code":"N20","subject":"Number Theory","level":6,"country":"","format":"latex","body":"Prove that for every positive integer $t$ there is a unique permutation $a_{0}, a_{1}, \\ldots, a_{t-1}$ of $0,1, \\ldots, t-1$ such that, for every $0 \\leq i \\leq t-1$, the binomial coefficient $\\binom{t+i}{2 a_{i}}$ is odd and $2 a_{i} \\neq t+i$."},{"id":"APMO-G45","source":"APMO","year":null,"code":"G45","subject":"Geometry","level":5,"country":"","format":"latex","body":"Line $\\ell$ intersects sides $B C$ and $A D$ of cyclic quadrilateral $A B C D$ in its interior points $R$ and $S$ respectively, and intersects ray $D C$ beyond point $C$ at $Q$, and ray $B A$ beyond point $A$ at $P$. Circumcircles of the triangles $Q C R$ and $Q D S$ intersect at $N \\neq Q$, while circumcircles of the triangles $P A S$ and $P B R$ intersect at $M \\neq P$. Let lines $M P$ and $N Q$ meet at point $X$, lines $A B$ and $C D$ meet at point $K$ and lines $B C$ and $A D$ meet at point $L$. Prove that point $X$ lies on line $K L$."},{"id":"APMO-C19","source":"APMO","year":null,"code":"C19","subject":"Combinatorics","level":6,"country":"","format":"latex","body":"Let $\\alpha$ and $\\beta$ be positive real numbers. Emerald makes a trip in the coordinate plane, starting off from the origin $(0,0)$. Each minute she moves one unit up or one unit to the right, restricting herself to the region $|x-y|<2025$, in the coordinate plane. By the time she visits a point ( $x, y$ ) she writes down the integer $\\lfloor x \\alpha+y \\beta\\rfloor$ on it. It turns out that Emerald wrote each non-negative integer exactly once. Find all the possible pairs $(\\alpha, \\beta)$ for which such a trip would be possible."},{"id":"APMO-N21","source":"APMO","year":null,"code":"N21","subject":"Number Theory","level":3,"country":"","format":"latex","body":"Let $P(x)$ be a non-constant polynomial with integer coefficients such that $P(0) \\neq 0$. Let $a_{1}, a_{2}, a_{3}, \\ldots$ be an infinite sequence of integers such that $P(i-j)$ divides $a_{i}-a_{j}$ for all distinct positive integers $i, j$. Prove that the sequence $a_{1}, a_{2}, a_{3}, \\ldots$ must be constant, that is, $a_{n}$ equals a constant $c$ for all $n$ positive integer."},{"id":"APMO-C20","source":"APMO","year":null,"code":"C20","subject":"Combinatorics","level":5,"country":"","format":"latex","body":"Let $n \\geq 3$ be an integer. There are $n$ cells on a circle, and each cell is assigned either $0$ or $1$. There is a rooster on one of these cells, and it repeats the following operations:\n- If the rooster is on a cell assigned $0$, it changes the assigned number to $1$ and moves to the next cell counterclockwise.\n- If the rooster is on a cell assigned $1$, it changes the assigned number to $0$ and moves to the cell after the next cell counterclockwise.\n\nProve that the following statement holds true after sufficiently many operations:\nIf the rooster is on a cell $C$, then the rooster would go around the circle exactly three times, stopping again at $C$. Moreover, every cell would be assigned the same number as it was assigned right before the rooster went around the circle $3$ times."},{"id":"APMO-N22","source":"APMO","year":null,"code":"N22","subject":"Number Theory","level":3,"country":"","format":"latex","body":"Consider an infinite sequence $a_{1}, a_{2}, \\ldots$ of positive integers such that\n$$\n100!\\left(a_{m}+a_{m+1}+\\cdots+a_{n}\\right) \\quad \\text{ is a multiple of } a_{n-m+1} a_{n+m}\n$$\nfor all positive integers $m, n$ such that $m \\leq n$.\nProve that the sequence is either bounded or linear.\n\nObservation: A sequence of positive integers is bounded if there exists a constant $N$ such that $a_{n}<N$ for all $n \\in \\mathbb{Z}_{>0}$. A sequence is linear if $a_{n}=n \\cdot a_{1}$ for all $n \\in \\mathbb{Z}_{>0}$."}]
);

